// Hub game list translations: GAME_I18N[id][lang] = { title, desc, controls, label }
// English lives in hub.js. Key labels inside <kbd> tags stay the same in every language.
const GAME_I18N = {
  towrush: {
    ko: { title: "견인차 러시", desc: "도시 곳곳에서 차들이 고장 나고 있어요! 라이벌 견인차보다 먼저 출동하고, 차 사이를 드리프트로 빠져나가 고장 난 차를 차고로 끌고 오세요. 길에서 일감을 줍고, 연속 배달을 이어 가고, 근무 계약을 완수하고, 러시아워를 버텨 내세요. 하지만 경찰은 조심! 50달러를 벌 때마다 스퍼드 1개를 받아요.", controls: "<kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> 또는 방향키로 운전, <kbd>Space</kbd> 핸드브레이크 / 드리프트, <kbd>Shift</kbd> 니트로, <kbd>E</kbd> 차 걸기, <kbd>B</kbd> 보석금 내기, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거. 터치스크린에서는 화면 버튼을 쓰세요.", label: "최고 근무 수익" },
    ja: { title: "レッカーラッシュ", desc: "街じゅうで車が故障中！ライバルのレッカー車より先に現場へかけつけ、車のあいだをドリフトですり抜けて、車をヤードまで運ぼう。道ばたの仕事もゲットして、連続配達をつなげ、シフトの契約を達成し、ラッシュアワーを乗り切ろう。でも警察には気をつけて！$50かせぐごとに1スパッドもらえるよ。", controls: "<kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> または矢印キーで運転、<kbd>Space</kbd> サイドブレーキ / ドリフト、<kbd>Shift</kbd> ニトロ、<kbd>E</kbd> 車をフック、<kbd>B</kbd> 保釈金を払う、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート。タッチ画面では画面のボタンを使ってね。", label: "最高シフト収入" },
    zh: { title: "拖车大作战", desc: "全城的汽车都抛锚啦！和对手拖车抢着出警，在车流中漂移穿梭，把车拖回你的车场。顺路接单、保持连续送达、完成班次合同、挺过交通高峰，但要小心警察！每赚 $50 就能得到 1 个土豆币。", controls: "<kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> 或方向键驾驶，<kbd>Space</kbd> 手刹 / 漂移，<kbd>Shift</kbd> 氮气加速，<kbd>E</kbd> 挂上车辆，<kbd>B</kbd> 交保释金，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音。触屏设备请使用屏幕按钮。", label: "单班最高收入" },
    es: { title: "Grúa Turbo", desc: "¡Los coches se averían por toda la ciudad! Gánales a las grúas rivales en cada aviso, derrapa entre el tráfico y remolca los coches hasta tu depósito. Recoge encargos por la calle, mantén tu racha de entregas, cumple los contratos del turno y sobrevive a la hora punta, ¡pero cuidado con la policía! Cada $50 que ganas te da 1 Spud.", controls: "<kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> o las flechas para conducir, <kbd>Space</kbd> freno de mano / derrape, <kbd>Shift</kbd> nitro, <kbd>E</kbd> enganchar un coche, <kbd>B</kbd> pagar la fianza, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar. En pantallas táctiles, usa los botones de la pantalla.", label: "Mejor turno" },
    fr: { title: "Dépanneuse Express", desc: "Les voitures tombent en panne partout en ville ! Devance les dépanneuses rivales à chaque appel, drifte dans la circulation et ramène les voitures à ta fourrière. Prends des missions en route, enchaîne les livraisons, remplis tes contrats et survis à l'heure de pointe, mais attention à la police ! Chaque tranche de 50 $ gagnée te rapporte 1 Spud.", controls: "<kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> ou les flèches pour conduire, <kbd>Space</kbd> frein à main / drift, <kbd>Shift</kbd> nitro, <kbd>E</kbd> accrocher une voiture, <kbd>B</kbd> payer la caution, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son. Sur écran tactile, utilise les boutons à l'écran.", label: "Meilleur service" },
    de: { title: "Turbo-Abschlepper", desc: "Überall in der Stadt bleiben Autos liegen! Sei schneller als die anderen Abschleppwagen, drifte durch den Verkehr und schlepp die Autos auf deinen Hof. Schnapp dir Aufträge am Straßenrand, halte deine Lieferserie am Laufen, erfülle deine Schichtaufträge und überstehe die Rushhour – aber pass auf die Polizei auf! Für je 50 $ bekommst du 1 Spud.", controls: "<kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> oder Pfeiltasten zum Fahren, <kbd>Space</kbd> Handbremse / Drift, <kbd>Shift</kbd> Nitro, <kbd>E</kbd> Auto anhängen, <kbd>B</kbd> Kaution zahlen, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus. Auf dem Touchscreen nimmst du die Tasten auf dem Bildschirm.", label: "Beste Schicht" },
    pt: { title: "Guincho Turbo", desc: "Os carros estão quebrando pela cidade toda! Chegue antes dos guinchos rivais em cada chamado, drifte no trânsito e reboque os carros até o seu pátio. Pegue serviços na rua, mantenha a sequência de entregas, cumpra os contratos do turno e sobreviva à hora do rush, mas cuidado com a polícia! A cada $50 que você ganha, leva 1 Spud.", controls: "<kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> ou setas para dirigir, <kbd>Space</kbd> freio de mão / drift, <kbd>Shift</kbd> nitro, <kbd>E</kbd> engatar um carro, <kbd>B</kbd> pagar a fiança, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo. Em telas de toque, use os botões na tela.", label: "Melhor turno" },
  },
  tatertyper: {
    ko: { title: "감자 타자왕", desc: "감자들의 대경주! 재미있는 상식 문장(영어)을 최대한 빨리 쳐서 해시 브라운, 매슐리와 친구들을 제치고 달려 보세요. 황금 단어를 치면 깜짝 파워가 생겨요. 러셋 왕과 겨루는 스퍼드 컵, 데일리 대시, 매셔를 피해 달리는 무한 모드, 레이스 코드로 친구와 대결까지! 레벨을 올려 운동화와 꼬리 효과를 열어요.", controls: "그냥 타자를 치세요! 대문자와 문장 부호까지 문장과 똑같이 쳐야 해요. <kbd>Esc</kbd> 메뉴, <kbd>Enter</kbd> 다시 레이스. 혼자 하는 레이스는 일시정지 버튼으로 멈출 수 있어요.", label: "최고 속도" },
    ja: { title: "ポテトタイピング", desc: "ポテトの大レース！楽しい豆知識の文（英語）をできるだけ速く打って、ハッシュブラウンやマッシュリーたちを追い抜こう。金色の単語を打つとふしぎなパワーが手に入るよ。ラセット王とたたかうスパッドカップ、デイリーダッシュ、マッシャーから逃げるエンドレス、レースコードで友だちと対戦も！レベルを上げてスニーカーや軌跡をゲットしよう。", controls: "とにかく打つだけ！大文字や記号まで文とぴったり同じに打とう。<kbd>Esc</kbd> メニュー、<kbd>Enter</kbd> もう一度レース。ひとりのレースは一時停止ボタンで止められるよ。", label: "最高スピード" },
    zh: { title: "土豆打字赛", desc: "土豆大赛跑！用最快的速度打出有趣的冷知识句子（英文），让你的土豆超过薯饼、土豆泥妹和大伙儿。打出金色单词能获得神秘能力。挑战赤褐国王赢下土豆币杯，试试每日冲刺，在无尽模式中甩开捣泥怪，或用比赛码和好友对战！升级还能解锁跑鞋和拖尾特效。", controls: "直接打字就行！要和句子一模一样，大小写和标点也不能错。<kbd>Esc</kbd> 打开菜单，<kbd>Enter</kbd> 再赛一场。单人比赛可以按暂停按钮暂停。", label: "最快速度" },
    es: { title: "Papa Tecleadora", desc: "¡La gran carrera de papas! Escribe datos curiosos (en inglés) lo más rápido que puedas para que tu papa adelante a Hash Brown, Mashley y la pandilla. Completa palabras doradas para ganar poderes sorpresa, gana la Copa Spud contra el Rey Russet, prueba el Sprint Diario, escapa del Masher en Infinito o reta a un amigo con un código de carrera. Sube de nivel para desbloquear zapatillas y estelas.", controls: "¡Solo escribe! Copia la frase exactamente, con mayúsculas y signos incluidos. <kbd>Esc</kbd> para el menú, <kbd>Enter</kbd> para correr otra vez. El botón de pausa pausa una carrera en solitario.", label: "Mejor velocidad" },
    fr: { title: "Patate Tape-Vite", desc: "La grande course des patates ! Tape des anecdotes rigolotes (en anglais) le plus vite possible pour faire filer ta patate devant Hash Brown, Mashley et toute la bande. Réussis les mots dorés pour gagner des pouvoirs mystère, remporte la Coupe Spud contre le Roi Russet, tente le Sprint du jour, échappe au Masher en mode Infini ou défie un ami avec un code de course. Monte de niveau pour débloquer baskets et traînées.", controls: "Tape, c'est tout ! Recopie la phrase exactement, majuscules et ponctuation comprises. <kbd>Esc</kbd> pour le menu, <kbd>Enter</kbd> pour rejouer. Le bouton Pause met en pause une course en solo.", label: "Meilleure vitesse" },
    de: { title: "Kartoffel-Tipper", desc: "Das große Kartoffelrennen! Tippe lustige Fakten (auf Englisch) so schnell du kannst, damit deine Kartoffel an Hash Brown, Mashley und der Bande vorbeisaust. Goldene Wörter bringen geheimnisvolle Kräfte. Hol dir den Spud-Pokal gegen König Russet, probier den Tages-Sprint, renn im Endlos-Modus dem Masher davon oder fordere Freunde per Renn-Code heraus. Steig im Level auf und schalte Sneaker und Spuren frei.", controls: "Einfach tippen! Schreib den Satz genau ab, auch Großbuchstaben und Satzzeichen. <kbd>Esc</kbd> fürs Menü, <kbd>Enter</kbd> für ein neues Rennen. Mit der Pause-Taste hältst du ein Solo-Rennen an.", label: "Bestes Tempo" },
    pt: { title: "Batata Digitadora", desc: "A grande corrida das batatas! Digite curiosidades divertidas (em inglês) o mais rápido que puder para sua batata passar Hash Brown, Mashley e a turma. Complete palavras douradas para ganhar poderes surpresa, vença a Copa Spud contra o Rei Russet, tente a Corrida Diária, fuja do Masher no modo Infinito ou desafie um amigo com um código de corrida. Suba de nível para liberar tênis e rastros.", controls: "É só digitar! Copie a frase igualzinha, com maiúsculas e pontuação. <kbd>Esc</kbd> abre o menu, <kbd>Enter</kbd> corre de novo. O botão Pausar pausa uma corrida solo.", label: "Melhor velocidade" },
  },
  orderup: {
    ko: { title: "주문 나왔습니다!", desc: "동네에서 제일 바쁜 식당을 운영해요! 손님들의 인내심이 바닥나기 전에 버거와 핫도그를 굽고, 감자튀김을 튀기고, 탄산음료를 따르고, 밀크셰이크를 만드세요. 콤보를 이어 팁을 듬뿍 받고, 음식 평론가를 감동시키고, 설거지 담당에서 전설의 요리왕까지 승진하세요. 매일 별 3개를 모으고, 점심 러시에서 얼마나 버티는지 도전!", controls: "클릭(또는 터치)으로 물건을 집고, 놓을 곳을 클릭하세요. 손님을 클릭하면 음식을 내줘요. <kbd>Esc</kbd> 들고 있는 것 내려놓기, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거.", label: "모은 별" },
    ja: { title: "オーダー入りまーす！", desc: "町いちばん大人気のダイナーを切り盛りしよう！お客さんがしびれを切らす前に、バーガーやホットドッグを焼いて、ポテトを揚げて、ソーダを注いで、ミルクシェイクを作ろう。コンボをつなげてチップをがっぽり、料理評論家をうならせ、皿洗いからダイナーの伝説までランクアップ！毎日スター3つをねらって、ランチラッシュでどこまで粘れるか挑戦だ！", controls: "クリック（またはタップ）で物を取って、置きたい場所をクリック。お客さんをクリックすると料理を出せるよ。<kbd>Esc</kbd> 持っている物を置く、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート。", label: "獲得スター" },
    zh: { title: "上菜啦！", desc: "经营全镇最忙的小餐馆！在顾客失去耐心之前，煎汉堡、烤热狗、炸薯条、倒汽水、打奶昔。连击拿大笔小费，征服美食评论家，从洗碗工一路升到餐馆传奇，每天拿满 3 颗星星，看看你能在午餐高峰里坚持多久！", controls: "点击（或轻触）拿起东西，再点击要放的地方。点击顾客就能上菜。<kbd>Esc</kbd> 放下手里的东西，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音。", label: "获得星星" },
    es: { title: "¡Marchando!", desc: "¡Lleva el restaurante más concurrido de la ciudad! Asa hamburguesas y perritos calientes, fríe papas fritas, sirve refrescos y bate batidos antes de que tus clientes pierdan la paciencia. Encadena combos para ganar grandes propinas, impresiona al crítico gastronómico, asciende de Friegaplatos a Leyenda del Restaurante, consigue 3 estrellas cada día ¡y aguanta todo lo que puedas en la Hora de la Comida!", controls: "Haz clic (o toca) para coger algo y luego haz clic donde va. Haz clic en un cliente para servirle. <kbd>Esc</kbd> suelta lo que llevas, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar.", label: "Estrellas ganadas" },
    fr: { title: "Commande prête !", desc: "Gère le resto le plus animé de la ville ! Grille des burgers et des hot-dogs, fais des frites, sers des sodas et mixe des milk-shakes avant que tes clients perdent patience. Enchaîne les combos pour de gros pourboires, épate le critique culinaire, passe de Plongeur à Légende du Resto, gagne 3 étoiles chaque jour et tiens le plus longtemps possible au Coup de feu du midi !", controls: "Clique (ou touche) pour prendre un objet, puis clique là où il va. Clique sur un client pour le servir. <kbd>Esc</kbd> lâche ce que tu tiens, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son.", label: "Étoiles gagnées" },
    de: { title: "Bestellung kommt!", desc: "Leite das vollste Diner der Stadt! Brate Burger und Hotdogs, frittiere Pommes, zapfe Limo und mix Milchshakes, bevor deinen Gästen die Geduld ausgeht. Mit Combos gibt's dickes Trinkgeld. Beeindrucke den Restaurantkritiker, steig vom Tellerwäscher zur Diner-Legende auf, hol jeden Tag 3 Sterne und schau, wie lange du im Mittagsansturm durchhältst!", controls: "Klicke (oder tippe), um etwas zu nehmen, dann klicke dorthin, wo es hinsoll. Klicke einen Gast an, um ihn zu bedienen. <kbd>Esc</kbd> legt ab, was du hältst, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus.", label: "Gesammelte Sterne" },
    pt: { title: "Saindo o Pedido!", desc: "Comande a lanchonete mais movimentada da cidade! Grelhe hambúrgueres e cachorros-quentes, frite batatas, sirva refrigerantes e bata milk-shakes antes que os clientes percam a paciência. Faça combos para ganhar gorjetas gordas, impressione o crítico de comida, suba de Lavador de Pratos a Lenda da Lanchonete, ganhe 3 estrelas todo dia e veja quanto tempo você aguenta na Correria do Almoço!", controls: "Clique (ou toque) para pegar algo e depois clique onde vai. Clique num cliente para servi-lo. <kbd>Esc</kbd> solta o que você está segurando, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo.", label: "Estrelas ganhas" },
  },
  goblingate: {
    ko: { title: "고블린 게이트", desc: "고블린, 슬라임, 풍선, 방패 고블린, 그리고 트롤 왕이 성으로 쳐들어와요! 궁수, 대포, 얼음, 번개 탑을 짓고, 용감한 기사 핍 경을 싸움터로 보내고, 보물 상자를 챙기고, 적 무리에 운석을 떨어뜨리세요. 전투 12개와 무한 호드 모드가 기다려요.", controls: "돌 받침을 클릭해 탑을 짓고, 탑을 클릭해 업그레이드하거나 팔아요. <kbd>Space</kbd> 다음 웨이브, <kbd>1</kbd>–<kbd>4</kbd> 탑 고르기, <kbd>U</kbd> 업그레이드, <kbd>Q</kbd> 운석, <kbd>E</kbd> 얼음 폭풍, <kbd>H</kbd> 핍 경 출동, <kbd>F</kbd> 속도 1x/2x/3x, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "모은 별" },
    ja: { title: "ゴブリンゲート", desc: "ゴブリン、スライム、風船、盾ゴブリン、そしてトロール王がお城にせめてくる！弓矢、大砲、氷、いなずまのタワーを建てて、勇かんな騎士サー・ピップを戦場へ送りこもう。宝箱をゲットして、敵の大群にいん石を落とせ！12のバトルとエンドレスホードが待っているよ。", controls: "石の台をクリックして建設、タワーをクリックして強化か売却。<kbd>Space</kbd> 次のウェーブ、<kbd>1</kbd>–<kbd>4</kbd> タワーを選ぶ、<kbd>U</kbd> 強化、<kbd>Q</kbd> いん石、<kbd>E</kbd> アイスストーム、<kbd>H</kbd> サー・ピップ出動、<kbd>F</kbd> スピード 1x/2x/3x、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "獲得スター" },
    zh: { title: "哥布林城门", desc: "哥布林、史莱姆、气球、盾牌哥布林还有巨魔国王正向城堡进军！建造弓箭塔、大炮塔、冰霜塔和闪电塔，派勇敢的皮普爵士上阵，抢宝箱，再往敌群里砸流星！共有 12 场战斗，外加无尽大军模式。", controls: "点击石台建造，点击塔进行升级或出售。<kbd>Space</kbd> 下一波，<kbd>1</kbd>–<kbd>4</kbd> 选择塔，<kbd>U</kbd> 升级，<kbd>Q</kbd> 流星，<kbd>E</kbd> 冰暴，<kbd>H</kbd> 派出皮普爵士，<kbd>F</kbd> 速度 1x/2x/3x，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "获得星星" },
    es: { title: "La Puerta Goblin", desc: "¡Goblins, slimes, globos, goblins con escudo y el Rey Trol marchan hacia el castillo! Construye torres de arqueros, cañones, hielo y rayos, manda al valiente caballero Sir Pip a la pelea, abre cofres del tesoro y lanza meteoritos sobre la horda en 12 batallas y en la Horda Infinita.", controls: "Haz clic en una losa de piedra para construir y en una torre para mejorarla o venderla. <kbd>Space</kbd> siguiente oleada, <kbd>1</kbd>–<kbd>4</kbd> elegir torre, <kbd>U</kbd> mejorar, <kbd>Q</kbd> meteorito, <kbd>E</kbd> tormenta de hielo, <kbd>H</kbd> enviar a Sir Pip, <kbd>F</kbd> velocidad 1x/2x/3x, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Estrellas ganadas" },
    fr: { title: "La Porte des Gobelins", desc: "Gobelins, slimes, ballons, gobelins à bouclier et le Roi Troll marchent sur le château ! Construis des tours d'archers, des canons, des tours de givre et d'éclairs, envoie le brave chevalier Sire Pip au combat, ramasse des coffres au trésor et fais pleuvoir des météores sur la horde dans 12 batailles et la Horde infinie.", controls: "Clique sur une dalle de pierre pour construire, sur une tour pour l'améliorer ou la vendre. <kbd>Space</kbd> vague suivante, <kbd>1</kbd>–<kbd>4</kbd> choisir une tour, <kbd>U</kbd> améliorer, <kbd>Q</kbd> météore, <kbd>E</kbd> tempête de glace, <kbd>H</kbd> envoyer Sire Pip, <kbd>F</kbd> vitesse 1x/2x/3x, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Étoiles gagnées" },
    de: { title: "Goblin-Tor", desc: "Goblins, Schleime, Ballons, Schildgoblins und der Trollkönig marschieren auf die Burg zu! Bau Bogenschützen-, Kanonen-, Frost- und Blitztürme, schick den tapferen Ritter Sir Pip in den Kampf, schnapp dir Schatztruhen und lass Meteore auf die Horde regnen – in 12 Schlachten und der Endlos-Horde.", controls: "Klicke auf eine Steinplatte zum Bauen, auf einen Turm zum Verbessern oder Verkaufen. <kbd>Space</kbd> nächste Welle, <kbd>1</kbd>–<kbd>4</kbd> Turm wählen, <kbd>U</kbd> verbessern, <kbd>Q</kbd> Meteor, <kbd>E</kbd> Eissturm, <kbd>H</kbd> Sir Pip losschicken, <kbd>F</kbd> Tempo 1x/2x/3x, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Gesammelte Sterne" },
    pt: { title: "Portão dos Goblins", desc: "Goblins, gosmas, balões, goblins de escudo e o Rei Troll estão marchando contra o castelo! Construa torres de arqueiros, canhões, gelo e raios, mande o corajoso cavaleiro Sir Pip para a luta, pegue baús de tesouro e jogue meteoros na horda em 12 batalhas e na Horda Infinita.", controls: "Clique numa base de pedra para construir e numa torre para melhorar ou vender. <kbd>Space</kbd> próxima onda, <kbd>1</kbd>–<kbd>4</kbd> escolher torre, <kbd>U</kbd> melhorar, <kbd>Q</kbd> meteoro, <kbd>E</kbd> tempestade de gelo, <kbd>H</kbd> enviar Sir Pip, <kbd>F</kbd> velocidade 1x/2x/3x, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Estrelas ganhas" },
  },
  gemmine: {
    ko: { title: "보석 광산", desc: "반짝이는 보석을 바꿔 3개를 한 줄로 맞추고, 줄 폭탄, 폭탄, 무지개 보석을 만들어 다섯 광산의 30개 레벨을 파고 내려가요. 끈적한 젤리를 터뜨리고, 보물 상자를 열고, 메가 드릴을 충전하세요. 매일 새로운 데일리 발굴도 잊지 마세요!", controls: "보석을 끌거나(또는 붙어 있는 보석 두 개를 클릭해) 서로 바꿔요. 방향키와 <kbd>Space</kbd>도 돼요. <kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> 부스터, <kbd>4</kbd> 메가 드릴, <kbd>H</kbd> 힌트, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "모은 별" },
    ja: { title: "ジェムマイン", desc: "キラキラの宝石を入れかえて3つそろえよう！ライン消し、ばくだん、にじ色の宝石を作って、5つの鉱山にある30レベルを掘り進もう。ねばねばスライムをはじけさせ、宝箱を割って、メガドリルをチャージ！毎日新しいデイリー発掘にも来てね！", controls: "宝石をドラッグ（またはとなりの宝石2つをクリック）して入れかえ。矢印キーと <kbd>Space</kbd> も使えるよ。<kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> ブースター、<kbd>4</kbd> メガドリル、<kbd>H</kbd> ヒント、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "獲得スター" },
    zh: { title: "宝石矿山", desc: "交换闪亮的宝石，三个连成一排就消除！制造直线爆破、炸弹和彩虹宝石，深入五座矿山的 30 个关卡。弄破黏黏胶、撬开宝箱、给超级钻头充能。每天都回来挑战全新的每日挖宝吧！", controls: "拖动宝石（或点击相邻的两个宝石）来交换。方向键和 <kbd>Space</kbd> 也可以。<kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> 道具，<kbd>4</kbd> 超级钻头，<kbd>H</kbd> 提示，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "获得星星" },
    es: { title: "Mina de Gemas", desc: "¡Intercambia gemas brillantes para hacer líneas de 3, crea lanzarrayos, bombas y gemas arcoíris, y excava por 30 niveles en cinco minas! Revienta el moco pegajoso, abre cofres del tesoro y carga tu Megataladro. ¡Vuelve cada día para una nueva Excavación Diaria!", controls: "Arrastra una gema (o haz clic en dos gemas vecinas) para cambiarlas. También sirven las flechas y <kbd>Space</kbd>. <kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> potenciadores, <kbd>4</kbd> Megataladro, <kbd>H</kbd> pista, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Estrellas ganadas" },
    fr: { title: "La Mine de Gemmes", desc: "Échange des gemmes brillantes pour en aligner 3, crée des lignes explosives, des bombes et des gemmes arc-en-ciel, et creuse à travers 30 niveaux dans cinq mines ! Fais éclater la glu collante, ouvre des coffres au trésor et charge ta Méga-Foreuse. Reviens chaque jour pour une nouvelle Fouille du jour !", controls: "Fais glisser une gemme (ou clique sur deux gemmes voisines) pour les échanger. Les flèches et <kbd>Space</kbd> marchent aussi. <kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> bonus, <kbd>4</kbd> Méga-Foreuse, <kbd>H</kbd> indice, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Étoiles gagnées" },
    de: { title: "Edelstein-Mine", desc: "Tausche funkelnde Edelsteine, bis 3 in einer Reihe liegen, bau Linienblaster, Bomben und Regenbogensteine und grab dich durch 30 Level in fünf Minen! Lass klebrigen Schleim platzen, knack Schatztruhen und lade deinen Mega-Bohrer auf. Komm jeden Tag wieder für eine neue Tages-Grabung!", controls: "Zieh einen Edelstein (oder klicke zwei Nachbarsteine an), um sie zu tauschen. Pfeiltasten und <kbd>Space</kbd> gehen auch. <kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> Booster, <kbd>4</kbd> Mega-Bohrer, <kbd>H</kbd> Tipp, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Gesammelte Sterne" },
    pt: { title: "Mina de Gemas", desc: "Troque gemas brilhantes para formar linhas de 3, crie raios de linha, bombas e gemas arco-íris, e cave por 30 fases em cinco minas! Estoure a gosma grudenta, abra baús de tesouro e carregue sua Megabroca. Volte todo dia para uma nova Escavação Diária!", controls: "Arraste uma gema (ou clique em duas gemas vizinhas) para trocá-las. As setas e <kbd>Space</kbd> também funcionam. <kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> reforços, <kbd>4</kbd> Megabroca, <kbd>H</kbd> dica, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Estrelas ganhas" },
  },
  jungledash: {
    ko: { title: "정글 대시", desc: "정글, 잃어버린 신전, 화산을 달리고 점프하며 딱정벌레를 콩! 코코넛 던지는 원숭이를 피하고, 스타프루트로 무적 파워를 얻고, 월드마다 마지막에 나오는 큰 보스를 물리치세요. 레벨마다 숨은 보석 3개를 모두 찾고, 시간과 겨뤄 금메달을 따고, 코인으로 이단 점프, 공중 대시, 멋진 모자를 사요.", controls: "<kbd>←</kbd> <kbd>→</kbd> 또는 <kbd>A</kbd> <kbd>D</kbd>로 달리기, <kbd>Space</kbd>, <kbd>↑</kbd> 또는 <kbd>W</kbd>로 점프(길게 누르면 더 높이), 대시를 사면 <kbd>Shift</kbd> 또는 <kbd>X</kbd>로 대시, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거. 휴대폰과 태블릿에서는 큰 터치 버튼이 나와요.", label: "찾은 보석" },
    ja: { title: "ジャングルダッシュ", desc: "ジャングル、なぞの神殿、火山を走ってジャンプして、カブトムシをふみつけよう！ココナッツを投げるおサルをかわし、スターフルーツでスターパワーをゲット、各ワールドの最後には大ボスが待っているよ。レベルごとにかくれた宝石3つを全部見つけて、タイムアタックで金メダルをねらい、コインで二段ジャンプ、空中ダッシュ、カッコいい帽子を買おう。", controls: "<kbd>←</kbd> <kbd>→</kbd> または <kbd>A</kbd> <kbd>D</kbd> で走る、<kbd>Space</kbd>、<kbd>↑</kbd> または <kbd>W</kbd> でジャンプ（長押しでもっと高く）、ダッシュを買ったら <kbd>Shift</kbd> または <kbd>X</kbd> でダッシュ、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート。スマホやタブレットでは大きなタッチボタンが出るよ。", label: "見つけた宝石" },
    zh: { title: "丛林冲刺", desc: "在丛林、失落神殿和火山里奔跑跳跃，踩扁甲虫！躲开扔椰子的猴子，吃杨桃获得星星之力，每个世界的最后还要打败大Boss。找齐每关藏着的 3 颗宝石，和时间赛跑拿金牌，再用金币买二段跳、空中冲刺和超酷帽子。", controls: "<kbd>←</kbd> <kbd>→</kbd> 或 <kbd>A</kbd> <kbd>D</kbd> 奔跑，<kbd>Space</kbd>、<kbd>↑</kbd> 或 <kbd>W</kbd> 跳跃（按住跳得更高），买下冲刺后用 <kbd>Shift</kbd> 或 <kbd>X</kbd> 冲刺，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音。手机和平板上会出现大号触屏按钮。", label: "找到的宝石" },
    es: { title: "Carrera en la Jungla", desc: "¡Corre, salta y aplasta escarabajos por la jungla, un templo perdido y un volcán! Esquiva a los monos lanzacocos, coge carambolas para el poder estelar y vence a un gran jefe al final de cada mundo. Encuentra las 3 gemas escondidas de cada nivel, corre contra el reloj por medallas de oro y gasta monedas en doble salto, impulso aéreo y gorros chulísimos.", controls: "<kbd>←</kbd> <kbd>→</kbd> o <kbd>A</kbd> <kbd>D</kbd> para correr, <kbd>Space</kbd>, <kbd>↑</kbd> o <kbd>W</kbd> para saltar (mantén para subir más), <kbd>Shift</kbd> o <kbd>X</kbd> para el impulso cuando lo compres, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar. En móviles y tabletas aparecen botones táctiles grandes.", label: "Gemas encontradas" },
    fr: { title: "Course dans la Jungle", desc: "Cours, saute et écrase des scarabées dans la jungle, un temple perdu et un volcan ! Esquive les singes lanceurs de noix de coco, attrape des caramboles pour le super pouvoir étoile et bats un gros boss à la fin de chaque monde. Trouve les 3 gemmes cachées de chaque niveau, fais la course contre la montre pour l'or et dépense tes pièces en double saut, ruée aérienne et chapeaux trop cool.", controls: "<kbd>←</kbd> <kbd>→</kbd> ou <kbd>A</kbd> <kbd>D</kbd> pour courir, <kbd>Space</kbd>, <kbd>↑</kbd> ou <kbd>W</kbd> pour sauter (maintiens pour aller plus haut), <kbd>Shift</kbd> ou <kbd>X</kbd> pour la ruée une fois achetée, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son. De gros boutons tactiles s'affichent sur téléphone et tablette.", label: "Gemmes trouvées" },
    de: { title: "Dschungel-Sprint", desc: "Renn, spring und plätte Käfer im Dschungel, in einem verlorenen Tempel und in einem Vulkan! Weich Kokosnuss-Affen aus, schnapp dir Sternfrüchte für Sternenkraft und besiege am Ende jeder Welt einen großen Boss. Finde in jedem Level alle 3 versteckten Edelsteine, hol dir im Rennen gegen die Uhr Goldmedaillen und gib Münzen für Doppelsprung, Luft-Dash und coole Hüte aus.", controls: "<kbd>←</kbd> <kbd>→</kbd> oder <kbd>A</kbd> <kbd>D</kbd> zum Laufen, <kbd>Space</kbd>, <kbd>↑</kbd> oder <kbd>W</kbd> zum Springen (gedrückt halten für mehr Höhe), <kbd>Shift</kbd> oder <kbd>X</kbd> zum Dashen, sobald du es gekauft hast, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus. Auf Handys und Tablets erscheinen große Touch-Tasten.", label: "Gefundene Edelsteine" },
    pt: { title: "Corrida na Selva", desc: "Corra, pule e esmague besouros pela selva, por um templo perdido e por um vulcão! Desvie dos macacos que jogam cocos, pegue carambolas para ganhar poder estelar e vença um chefão no fim de cada mundo. Ache as 3 gemas escondidas de cada fase, corra contra o relógio por medalhas de ouro e gaste moedas com pulo duplo, impulso no ar e chapéus irados.", controls: "<kbd>←</kbd> <kbd>→</kbd> ou <kbd>A</kbd> <kbd>D</kbd> para correr, <kbd>Space</kbd>, <kbd>↑</kbd> ou <kbd>W</kbd> para pular (segure para ir mais alto), <kbd>Shift</kbd> ou <kbd>X</kbd> para o impulso depois de comprar, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo. Botões de toque grandes aparecem em celulares e tablets.", label: "Gemas encontradas" },
  },
  beatdrop: {
    ko: { title: "비트 드롭", desc: "반짝이는 네온 무대에서 박자에 딱 맞춰 노트를 치세요! 신나는 노래 7곡을 쉬움, 보통, 어려움으로 즐기고, 황금 별 노트를 잡아 점수가 두 배가 되는 스타 파워를 충전하세요. 매일 새로운 데일리 챌린지에 도전하고 트로피를 모두 모아 보세요.", controls: "<kbd>D</kbd> <kbd>F</kbd> <kbd>J</kbd> <kbd>K</kbd> 또는 <kbd>←</kbd> <kbd>↓</kbd> <kbd>↑</kbd> <kbd>→</kbd>로 노트 치기(긴 노트는 길게 누르기), 터치 화면에서는 레인을 탭, <kbd>Space</kbd> 스타 파워, 방향키 + <kbd>Enter</kbd> 노래 고르기, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "모은 별" },
    ja: { title: "ビートドロップ", desc: "光かがやくネオンステージで、リズムにぴったり合わせてノーツをたたこう！ノリノリの7曲をかんたん、ふつう、むずかしいで楽しんで、金色のスターノーツでスターパワーをためれば得点2倍！毎日新しいデイリーチャレンジに挑戦して、トロフィーを全部集めよう。", controls: "<kbd>D</kbd> <kbd>F</kbd> <kbd>J</kbd> <kbd>K</kbd> または <kbd>←</kbd> <kbd>↓</kbd> <kbd>↑</kbd> <kbd>→</kbd> でノーツをたたく（ロングノーツは長押し）、タッチではレーンをタップ、<kbd>Space</kbd> スターパワー、矢印キー + <kbd>Enter</kbd> 曲を選ぶ、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "獲得スター" },
    zh: { title: "节奏爆爆乐", desc: "在闪耀的霓虹舞台上踩准节拍敲击音符！用简单、普通、困难三种难度嗨翻 7 首洗脑好歌，接住金色星星音符，充满星星之力就能双倍得分。每天挑战全新的每日挑战，集齐所有奖杯吧！", controls: "<kbd>D</kbd> <kbd>F</kbd> <kbd>J</kbd> <kbd>K</kbd> 或 <kbd>←</kbd> <kbd>↓</kbd> <kbd>↑</kbd> <kbd>→</kbd> 敲击音符（长音符要按住），触屏上直接点轨道，<kbd>Space</kbd> 星星之力，方向键 + <kbd>Enter</kbd> 选歌，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "获得星星" },
    es: { title: "Beat Drop", desc: "¡Toca las notas justo al ritmo en un escenario de neón brillante! Rockea con 7 canciones pegadizas en Fácil, Normal o Difícil, atrapa notas de estrella doradas para cargar el Poder Estelar y ganar puntos dobles, acepta un Desafío Diario nuevo cada día y colecciona todos los trofeos.", controls: "<kbd>D</kbd> <kbd>F</kbd> <kbd>J</kbd> <kbd>K</kbd> o <kbd>←</kbd> <kbd>↓</kbd> <kbd>↑</kbd> <kbd>→</kbd> para tocar notas (mantén en las notas largas), toca los carriles en pantallas táctiles, <kbd>Space</kbd> Poder Estelar, flechas + <kbd>Enter</kbd> elegir canción, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Estrellas ganadas" },
    fr: { title: "Beat Drop", desc: "Frappe les notes pile dans le rythme sur une scène néon étincelante ! Éclate-toi sur 7 chansons entraînantes en Facile, Normal ou Difficile, attrape les notes étoile dorées pour charger le Pouvoir Étoile et doubler tes points, relève un nouveau Défi du jour chaque jour et collectionne tous les trophées.", controls: "<kbd>D</kbd> <kbd>F</kbd> <kbd>J</kbd> <kbd>K</kbd> ou <kbd>←</kbd> <kbd>↓</kbd> <kbd>↑</kbd> <kbd>→</kbd> pour frapper les notes (maintiens pour les notes longues), touche les pistes sur écran tactile, <kbd>Space</kbd> Pouvoir Étoile, flèches + <kbd>Enter</kbd> choisir une chanson, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Étoiles gagnées" },
    de: { title: "Beat Drop", desc: "Triff die Noten genau im Takt auf einer leuchtenden Neonbühne! Rock zu 7 Ohrwürmern auf Leicht, Normal oder Schwer, fang goldene Sternnoten für Sternenkraft mit doppelten Punkten, stell dich jeden Tag einer neuen Tages-Challenge und sammle alle Pokale.", controls: "<kbd>D</kbd> <kbd>F</kbd> <kbd>J</kbd> <kbd>K</kbd> oder <kbd>←</kbd> <kbd>↓</kbd> <kbd>↑</kbd> <kbd>→</kbd> Noten treffen (lange Noten halten), auf dem Touchscreen die Bahnen antippen, <kbd>Space</kbd> Sternenkraft, Pfeiltasten + <kbd>Enter</kbd> Song wählen, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Gesammelte Sterne" },
    pt: { title: "Beat Drop", desc: "Acerte as notas bem no ritmo num palco de neon brilhante! Agite com 7 músicas grudentas no Fácil, Normal ou Difícil, pegue notas de estrela douradas para carregar o Poder Estelar e ganhar pontos em dobro, encare um Desafio Diário novo todo dia e colecione todos os troféus.", controls: "<kbd>D</kbd> <kbd>F</kbd> <kbd>J</kbd> <kbd>K</kbd> ou <kbd>←</kbd> <kbd>↓</kbd> <kbd>↑</kbd> <kbd>→</kbd> para acertar as notas (segure nas notas longas), toque nas pistas na tela de toque, <kbd>Space</kbd> Poder Estelar, setas + <kbd>Enter</kbd> escolher música, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Estrelas ganhas" },
  },
  sunnyacres: {
    ko: { title: "햇살 농장", desc: "나만의 아늑한 농장을 꾸려요! 작물을 기르고, 닭, 소, 양, 염소를 키우고, 해가 지기 전에 트럭 주문을 채우세요. 과수원에서 사과를 따고, 헛간 오븐에서 빵과 사과파이를 굽고, 마을 축제에서 파란 리본을 받고, 레벨을 올려 농장을 마음대로 꾸며 보세요.", controls: "밭을 클릭(또는 드래그)해서 갈고, 심고, 물 주고, 수확해요. 맨손이면 알맞은 씨앗을 알아서 골라 줘요. <kbd>1</kbd>–<kbd>9</kbd> <kbd>0</kbd> 도구와 씨앗, <kbd>Q</kbd>/<kbd>E</kbd> 도구 바꾸기, <kbd>←</kbd> <kbd>↑</kbd> <kbd>↓</kbd> <kbd>→</kbd> 또는 <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> 커서 이동, <kbd>Space</kbd> 사용, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "농장 레벨" },
    ja: { title: "ひだまり農場", desc: "自分だけのほっこり農場をつくろう！作物を育てて、ニワトリ、ウシ、ヒツジ、ヤギを飼って、日がしずむ前にトラックの注文をそろえよう。果樹園でリンゴをつみ、納屋のオーブンでパンやアップルパイを焼いて、郡のお祭りで青リボンをゲット。レベルを上げて農場を好きにかざろう。", controls: "畑をクリック（またはドラッグ）して、耕す、植える、水やり、収穫。素手なら合ったタネを自動で選んでくれるよ。<kbd>1</kbd>–<kbd>9</kbd> <kbd>0</kbd> 道具とタネ、<kbd>Q</kbd>/<kbd>E</kbd> 道具切りかえ、<kbd>←</kbd> <kbd>↑</kbd> <kbd>↓</kbd> <kbd>→</kbd> または <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> カーソル移動、<kbd>Space</kbd> 使う、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "農場レベル" },
    zh: { title: "阳光农场", desc: "经营属于你的温馨农场！种庄稼，养鸡、牛、绵羊和山羊，赶在日落前装满卡车订单。去果园摘苹果，用谷仓烤炉烤面包和苹果派，在县集市上赢得蓝丝带，然后升级农场，随心装扮！", controls: "点击（或拖动）田地来翻土、播种、浇水和收获。空手时会自动帮你选对种子。<kbd>1</kbd>–<kbd>9</kbd> <kbd>0</kbd> 工具和种子，<kbd>Q</kbd>/<kbd>E</kbd> 切换工具，<kbd>←</kbd> <kbd>↑</kbd> <kbd>↓</kbd> <kbd>→</kbd> 或 <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> 移动光标，<kbd>Space</kbd> 使用，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "农场等级" },
    es: { title: "Granja Soleada", desc: "¡Lleva tu propia granja acogedora! Cultiva cosechas, cría gallinas, vacas, ovejas y cabras, y completa los pedidos del camión antes del atardecer. Recoge manzanas en tu huerto, hornea pan y tartas de manzana en el horno del granero, gana lazos azules en la Feria del Condado, sube de nivel y decora tu granja a tu manera.", controls: "Haz clic (o arrastra) en las parcelas para arar, plantar, regar y cosechar. Con las Manos Vacías se elige la semilla correcta por ti. <kbd>1</kbd>–<kbd>9</kbd> <kbd>0</kbd> herramientas y semillas, <kbd>Q</kbd>/<kbd>E</kbd> cambiar herramienta, <kbd>←</kbd> <kbd>↑</kbd> <kbd>↓</kbd> <kbd>→</kbd> o <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> mover el cursor, <kbd>Space</kbd> usar, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Nivel de granja" },
    fr: { title: "La Ferme Ensoleillée", desc: "Gère ta propre petite ferme douillette ! Fais pousser des cultures, élève poules, vaches, moutons et chèvres, et remplis les commandes du camion avant le coucher du soleil. Cueille des pommes dans ton verger, cuis du pain et des tartes aux pommes dans le four de la grange, gagne des rubans bleus à la Foire du comté, puis monte de niveau et décore ta ferme comme tu veux.", controls: "Clique (ou fais glisser) sur les parcelles pour labourer, planter, arroser et récolter. Les Mains nues choisissent la bonne graine pour toi. <kbd>1</kbd>–<kbd>9</kbd> <kbd>0</kbd> outils et graines, <kbd>Q</kbd>/<kbd>E</kbd> changer d'outil, <kbd>←</kbd> <kbd>↑</kbd> <kbd>↓</kbd> <kbd>→</kbd> ou <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> déplacer le curseur, <kbd>Space</kbd> utiliser, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Niveau de la ferme" },
    de: { title: "Sonnenhof", desc: "Führe deinen eigenen gemütlichen Bauernhof! Bau Pflanzen an, halte Hühner, Kühe, Schafe und Ziegen und erfülle die Lkw-Bestellungen vor Sonnenuntergang. Pflück Äpfel im Obstgarten, back Brot und Apfelkuchen im Scheunenofen, gewinn blaue Schleifen auf dem Jahrmarkt, steig im Level auf und gestalte deinen Hof, wie du willst.", controls: "Klicke (oder zieh) auf Felder zum Pflügen, Pflanzen, Gießen und Ernten. Mit leeren Händen wird automatisch der passende Samen gewählt. <kbd>1</kbd>–<kbd>9</kbd> <kbd>0</kbd> Werkzeuge und Samen, <kbd>Q</kbd>/<kbd>E</kbd> Werkzeug wechseln, <kbd>←</kbd> <kbd>↑</kbd> <kbd>↓</kbd> <kbd>→</kbd> oder <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> Cursor bewegen, <kbd>Space</kbd> benutzen, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Hof-Level" },
    pt: { title: "Fazenda Ensolarada", desc: "Cuide da sua própria fazendinha aconchegante! Plante, crie galinhas, vacas, ovelhas e cabras, e complete os pedidos do caminhão antes do pôr do sol. Colha maçãs no pomar, asse pães e tortas de maçã no forno do celeiro, ganhe fitas azuis na Feira do Condado e depois suba de nível e decore a fazenda do seu jeito.", controls: "Clique (ou arraste) nos canteiros para arar, plantar, regar e colher. As Mãos Livres escolhem a semente certa para você. <kbd>1</kbd>–<kbd>9</kbd> <kbd>0</kbd> ferramentas e sementes, <kbd>Q</kbd>/<kbd>E</kbd> trocar ferramenta, <kbd>←</kbd> <kbd>↑</kbd> <kbd>↓</kbd> <kbd>→</kbd> ou <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> mover o cursor, <kbd>Space</kbd> usar, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Nível da fazenda" },
  },
  brickblitz: {
    ko: { title: "벽돌 블리츠", desc: "네온 시티, 스타 항해, 크리스털 코어의 30개 네온 레벨에서 반짝이는 사탕 벽돌을 부숴요! 블리츠 게이지를 채워 거대한 충격파를 날리고, 월드마다 마지막에 나오는 웃긴 보스를 물리치고, 끝없는 벽돌 비 모드에서 얼마나 버티는지 도전하세요.", controls: "마우스나 <kbd>←</kbd> <kbd>→</kbd> / <kbd>A</kbd> <kbd>D</kbd>로 패들을 움직여요. <kbd>Space</kbd> 또는 클릭으로 공 발사와 레이저 쏘기, <kbd>B</kbd> 또는 <kbd>Shift</kbd>로 블리츠 웨이브, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "모은 별" },
    ja: { title: "ブロックブリッツ", desc: "ネオンシティ、スターボヤージュ、クリスタルコアの30のネオンレベルで、光るキャンディブロックをくだきまくろう！BLITZメーターをためて巨大な衝撃波をはなち、各ワールドの最後のヘンテコなボスをたおして、エンドレスのブロックレインでどこまで粘れるか挑戦だ。", controls: "マウスか <kbd>←</kbd> <kbd>→</kbd> / <kbd>A</kbd> <kbd>D</kbd> でパドルを動かす。<kbd>Space</kbd> かクリックでボール発射とレーザー、<kbd>B</kbd> か <kbd>Shift</kbd> でBLITZウェーブ、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "獲得スター" },
    zh: { title: "砖块闪击战", desc: "在霓虹之城、星际远航和水晶核心的 30 个霓虹关卡里，砸碎发光的糖果砖块！攒满闪击能量，放出超大冲击波，打败每个世界最后的搞笑Boss，再去无尽的砖块雨模式看看你能撑多久。", controls: "用鼠标或 <kbd>←</kbd> <kbd>→</kbd> / <kbd>A</kbd> <kbd>D</kbd> 移动挡板。<kbd>Space</kbd> 或点击发球和发射激光，<kbd>B</kbd> 或 <kbd>Shift</kbd> 放出闪击波，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "获得星星" },
    es: { title: "Ladrillos Blitz", desc: "¡Rompe ladrillos de caramelo brillantes en 30 niveles de neón en Ciudad Neón, Viaje Estelar y el Núcleo de Cristal! Llena tu medidor BLITZ para soltar una onda expansiva gigante, vence a un jefe chiflado al final de cada mundo y mira cuánto aguantas en el modo infinito Lluvia de Ladrillos.", controls: "Mueve la paleta con el ratón o <kbd>←</kbd> <kbd>→</kbd> / <kbd>A</kbd> <kbd>D</kbd>. <kbd>Space</kbd> o clic para lanzar y disparar láseres, <kbd>B</kbd> o <kbd>Shift</kbd> para una onda BLITZ, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Estrellas ganadas" },
    fr: { title: "Brique Blitz", desc: "Pulvérise des briques-bonbons lumineuses dans 30 niveaux néon à Néon City, Voyage Stellaire et le Cœur de Cristal ! Remplis ta jauge BLITZ pour une onde de choc géante, bats un boss rigolo à la fin de chaque monde et vois combien de temps tu tiens dans le mode infini Pluie de briques.", controls: "Déplace la raquette avec la souris ou <kbd>←</kbd> <kbd>→</kbd> / <kbd>A</kbd> <kbd>D</kbd>. <kbd>Space</kbd> ou clic pour lancer et tirer des lasers, <kbd>B</kbd> ou <kbd>Shift</kbd> pour une vague BLITZ, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Étoiles gagnées" },
    de: { title: "Steine-Blitz", desc: "Zertrümmere leuchtende Bonbon-Steine in 30 Neon-Leveln in Neon City, Sternenreise und dem Kristallkern! Füll deine BLITZ-Leiste für eine riesige Schockwelle, besiege am Ende jeder Welt einen albernen Boss und schau, wie lange du im endlosen Steinregen-Modus durchhältst.", controls: "Beweg den Schläger mit der Maus oder <kbd>←</kbd> <kbd>→</kbd> / <kbd>A</kbd> <kbd>D</kbd>. <kbd>Space</kbd> oder Klick zum Abschießen und für Laser, <kbd>B</kbd> oder <kbd>Shift</kbd> für eine BLITZ-Welle, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Gesammelte Sterne" },
    pt: { title: "Blitz de Tijolos", desc: "Destrua tijolos de doce brilhantes em 30 fases de neon na Cidade Neon, na Viagem Estelar e no Núcleo de Cristal! Encha sua barra BLITZ para uma onda de choque gigante, vença um chefão maluco no fim de cada mundo e veja quanto tempo você aguenta no modo infinito Chuva de Tijolos.", controls: "Mova a raquete com o mouse ou <kbd>←</kbd> <kbd>→</kbd> / <kbd>A</kbd> <kbd>D</kbd>. <kbd>Space</kbd> ou clique para lançar e atirar lasers, <kbd>B</kbd> ou <kbd>Shift</kbd> para uma onda BLITZ, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Estrelas ganhas" },
  },
  puttparty: {
    ko: { title: "퍼팅 파티", desc: "꽃 정원, 해적 섬, 우주 정거장, 달콤한 사탕 왕국에서 펼쳐지는 신나는 미니 골프! 젤리 패드에서 통통 튀고, 설탕 부스트 패드로 슝 날아가고, 사탕 버튼을 눌러 감초 벽을 열어요. 별과 메달을 모으거나, 한 화면에서 친구 최대 4명과 파티 모드를 즐겨요.", controls: "공에서 뒤로 끌었다 놓으면 퍼팅(마우스나 터치). 또는 <kbd>←</kbd> <kbd>→</kbd>로 조준하고 <kbd>Space</kbd>를 눌러 힘을 모아요. <kbd>U</kbd> 다시 치기, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "모은 별" },
    ja: { title: "パターパーティー", desc: "花の庭、海ぞくの島、宇宙ステーション、あまーいキャンディ王国でワイルドなミニゴルフ！ゼリーパッドでボヨーン、シュガーブーストでビューン、キャンディボタンを押してグミのかべを開けよう。スターやメダルを集めたり、1つの画面で4人までパーティーモードで遊べるよ。", controls: "ボールから後ろへドラッグして、はなすとパット（マウスかタッチ）。または <kbd>←</kbd> <kbd>→</kbd> でねらって <kbd>Space</kbd> 長押しでパワーをためる。<kbd>U</kbd> 打ち直し、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "獲得スター" },
    zh: { title: "迷你高尔夫派对", desc: "在花园、海盗岛、太空站和甜甜的糖果王国里玩疯狂迷你高尔夫！在果冻垫上弹跳，冲过糖粉加速垫，按下糖果按钮打开甘草糖墙。收集星星和奖牌，或者在同一块屏幕上和最多 4 个朋友玩派对模式。", controls: "从球往后拖，松手就推杆（鼠标或触屏）。也可以用 <kbd>←</kbd> <kbd>→</kbd> 瞄准，按住 <kbd>Space</kbd> 蓄力。<kbd>U</kbd> 重打，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "获得星星" },
    es: { title: "Fiesta de Minigolf", desc: "¡Minigolf alocado en un jardín de flores, una isla pirata, una estación espacial y el dulce Reino de los Caramelos! Rebota en almohadillas de gelatina, acelera sobre turbos de azúcar y pulsa botones de caramelo para abrir muros de regaliz. Colecciona estrellas y medallas, o juega al Modo Fiesta con hasta 4 amigos en una sola pantalla.", controls: "Arrastra hacia atrás desde la bola y suelta para golpear (ratón o pantalla táctil). O apunta con <kbd>←</kbd> <kbd>→</kbd> y mantén <kbd>Space</kbd> para cargar. <kbd>U</kbd> repetir golpe, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Estrellas ganadas" },
    fr: { title: "Minigolf en Folie", desc: "Du minigolf déjanté dans un jardin fleuri, sur une île de pirates, à bord d'une station spatiale et dans le doux Royaume des Bonbons ! Rebondis sur des coussins de gelée, file sur des tremplins sucrés et appuie sur des boutons en bonbon pour ouvrir des murs de réglisse. Collectionne étoiles et médailles, ou joue en Mode Fête jusqu'à 4 amis sur un seul écran.", controls: "Tire en arrière depuis la balle et relâche pour putter (souris ou tactile). Ou vise avec <kbd>←</kbd> <kbd>→</kbd> et maintiens <kbd>Space</kbd> pour charger. <kbd>U</kbd> rejouer le coup, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Étoiles gagnées" },
    de: { title: "Minigolf-Party", desc: "Verrücktes Minigolf im Blumengarten, auf einer Pirateninsel, an Bord einer Raumstation und im süßen Bonbonreich! Hüpf auf Wackelpudding-Polstern, düs über Zucker-Boostfelder und drück Bonbon-Knöpfe, um Lakritzwände zu öffnen. Sammle Sterne und Medaillen oder spiel den Party-Modus mit bis zu 4 Freunden an einem Bildschirm.", controls: "Zieh vom Ball nach hinten und lass los zum Putten (Maus oder Touch). Oder ziel mit <kbd>←</kbd> <kbd>→</kbd> und halte <kbd>Space</kbd> zum Aufladen. <kbd>U</kbd> Schlag wiederholen, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Gesammelte Sterne" },
    pt: { title: "Festa do Minigolfe", desc: "Minigolfe maluco num jardim florido, numa ilha pirata, a bordo de uma estação espacial e no doce Reino dos Doces! Quique em almofadas de gelatina, acelere em turbos de açúcar e aperte botões de bala para abrir muros de alcaçuz. Colecione estrelas e medalhas, ou jogue o Modo Festa com até 4 amigos numa tela só.", controls: "Arraste para trás a partir da bola e solte para tacar (mouse ou toque). Ou mire com <kbd>←</kbd> <kbd>→</kbd> e segure <kbd>Space</kbd> para carregar. <kbd>U</kbd> repetir tacada, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Estrelas ganhas" },
  },
  snakearena: {
    ko: { title: "스네이크 아레나", desc: "초원, 사막, 네온 시티, 미끄러운 얼음 동굴을 미끄러지듯 누비며 빛나는 구슬을 먹고 엄청 길어져요! 라이벌 뱀이 내 몸에 부딪히게 유인하고, 거대한 왕 뱀을 물리치고, 얼음과 거대화 파워업을 챙기고, 매일 새로운 데일리 챌린지에 도전하세요.", controls: "마우스나 <kbd>A</kbd> <kbd>D</kbd> / <kbd>←</kbd> <kbd>→</kbd>로 방향 조종. 마우스 버튼, <kbd>Space</kbd> 또는 <kbd>W</kbd>를 누르고 있으면 부스트, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "모은 별" },
    ja: { title: "スネークアリーナ", desc: "草原、さばく、ネオンシティ、つるつるの氷の洞くつをにょろにょろ進み、光るオーブを食べてどんどん長くなろう！ライバルのヘビを自分にぶつからせて、巨大なキングスネークをたおし、フリーズやジャイアントのパワーアップをゲット。毎日新しいデイリーチャレンジもあるよ。", controls: "マウスか <kbd>A</kbd> <kbd>D</kbd> / <kbd>←</kbd> <kbd>→</kbd> で方向を変える。マウスボタン、<kbd>Space</kbd> か <kbd>W</kbd> を押し続けるとブースト、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "獲得スター" },
    zh: { title: "贪吃蛇竞技场", desc: "游过草原、沙漠、霓虹之城和滑溜溜的冰霜洞窟，吞下发光的能量球，长成超级长蛇！引诱对手蛇撞上你，打败巨大的蛇王，抢到冰冻和巨大化道具，每天还有全新的每日挑战等你来！", controls: "用鼠标或 <kbd>A</kbd> <kbd>D</kbd> / <kbd>←</kbd> <kbd>→</kbd> 转向。按住鼠标键、<kbd>Space</kbd> 或 <kbd>W</kbd> 加速，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "获得星星" },
    es: { title: "Arena de Serpientes", desc: "¡Repta por la Pradera, el Desierto, Ciudad Neón y la resbaladiza Caverna Helada, zámpate orbes brillantes y crece muchísimo! Engaña a las serpientes rivales para que choquen contigo, vence a las gigantescas serpientes Rey, coge potenciadores de Congelar y Gigante y acepta un Desafío Diario nuevo cada día.", controls: "Dirige con el ratón o <kbd>A</kbd> <kbd>D</kbd> / <kbd>←</kbd> <kbd>→</kbd>. Mantén el botón del ratón, <kbd>Space</kbd> o <kbd>W</kbd> para acelerar, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Estrellas ganadas" },
    fr: { title: "L'Arène des Serpents", desc: "Ondule à travers la Prairie, le Désert, Néon City et la glissante Caverne de Givre, dévore des orbes lumineux et deviens super long ! Piège les serpents rivaux pour qu'ils te foncent dedans, bats les serpents Rois géants, attrape les bonus Gel et Géant et relève un nouveau Défi du jour chaque jour.", controls: "Dirige avec la souris ou <kbd>A</kbd> <kbd>D</kbd> / <kbd>←</kbd> <kbd>→</kbd>. Maintiens le bouton de la souris, <kbd>Space</kbd> ou <kbd>W</kbd> pour accélérer, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Étoiles gagnées" },
    de: { title: "Schlangen-Arena", desc: "Schlängel dich durch Wiese, Wüste, Neon City und die rutschige Frosthöhle, verschling leuchtende Kugeln und werd superlang! Lock gegnerische Schlangen in deinen Körper, besiege die riesigen Königsschlangen, schnapp dir Frost- und Riesen-Power-ups und stell dich jeden Tag einer neuen Tages-Challenge.", controls: "Steuere mit der Maus oder <kbd>A</kbd> <kbd>D</kbd> / <kbd>←</kbd> <kbd>→</kbd>. Halte die Maustaste, <kbd>Space</kbd> oder <kbd>W</kbd> für Boost, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Gesammelte Sterne" },
    pt: { title: "Arena das Cobras", desc: "Deslize pelo Campo, pelo Deserto, pela Cidade Neon e pela escorregadia Caverna Gelada, devore orbes brilhantes e fique enorme! Engane as cobras rivais para baterem em você, derrote as gigantes cobras Rei, pegue os poderes Congelar e Gigante e encare um Desafio Diário novo todo dia.", controls: "Guie com o mouse ou <kbd>A</kbd> <kbd>D</kbd> / <kbd>←</kbd> <kbd>→</kbd>. Segure o botão do mouse, <kbd>Space</kbd> ou <kbd>W</kbd> para turbinar, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Estrelas ganhas" },
  },
  luckylake: {
    ko: { title: "행운의 호수", desc: "햇살 연못, 안개 강, 산호만, 얼음 호수, 그리고 새로운 정글 석호에서 아침부터 달빛 아래까지 낚싯대를 던져요! 소나기, 황금 시간, 먹이 쟁탈전 속에서 낚시하고, 줄을 초록 구간에 유지해 퍼펙트 캐치를 노리고, 물고기 도감을 45마리로 채워 보세요.", controls: "<kbd>Space</kbd>나 마우스를 누르고 있으면 힘이 모이고, 놓으면 던져요. 탭하면 미끼가 멈추고, 입질이 오면 탭해서 걸어요. 누르고 있으면 감기, 줄이 빨갛게 되면 손을 떼세요. <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "찾은 어종" },
    ja: { title: "ラッキーレイク", desc: "ひだまり池、きりの川、サンゴ湾、こおった湖、そして新しいジャングルラグーンで、朝から月夜まで釣りざおをふろう！にわか雨、ゴールデンアワー、入れ食いタイムの中で釣って、ラインを緑にキープしてパーフェクトキャッチ。45種の魚で図かんをうめよう。", controls: "<kbd>Space</kbd> かマウスを長押しでパワーをためて、はなすとキャスト。タップでルアーを止めて、アタリが来たらタップで合わせる。長押しでリールを巻き、ラインが赤くなったらはなそう。<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "見つけた種類" },
    zh: { title: "幸运湖", desc: "从清晨到月夜，在阳光池塘、迷雾河、珊瑚湾、冰封湖和全新的丛林泻湖抛竿钓鱼！在阵雨、黄金时刻和鱼群狂欢中垂钓，把鱼线保持在绿色区域完成完美钓获，把 45 种鱼都收进你的鱼类图鉴。", controls: "按住 <kbd>Space</kbd> 或鼠标蓄力，松开抛竿。轻点让鱼饵停下，鱼咬钩时再轻点钩住。按住收线，鱼线变红时松开。<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "发现鱼种" },
    es: { title: "Lago de la Suerte", desc: "¡Lanza tu caña desde la mañana hasta la luz de la luna en el Estanque Soleado, el Río Brumoso, la Bahía de Coral, el Lago Helado y la nueva Laguna de la Jungla! Pesca entre chubascos, horas doradas y frenesís de peces, mantén el sedal en verde para lograr Capturas Perfectas y llena tu Libro de Peces con 45 especies.", controls: "Mantén <kbd>Space</kbd> o el ratón para cargar y suelta para lanzar. Toca para parar el señuelo y para clavar cuando piquen. Mantén para recoger y suelta cuando el sedal se ponga rojo. <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Especies halladas" },
    fr: { title: "Le Lac de la Chance", desc: "Lance ta ligne du matin au clair de lune à l'Étang Ensoleillé, la Rivière Brumeuse, la Baie de Corail, le Lac Gelé et le nouveau Lagon de la Jungle ! Pêche sous les averses, aux heures dorées et pendant les frénésies, garde ta ligne dans le vert pour des Prises Parfaites et remplis ton Livre des Poissons avec 45 espèces.", controls: "Maintiens <kbd>Space</kbd> ou la souris pour charger, relâche pour lancer. Touche pour arrêter le leurre et pour ferrer quand ça mord. Maintiens pour remonter, et relâche quand la ligne devient rouge. <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Espèces trouvées" },
    de: { title: "Glückssee", desc: "Wirf deine Angel vom Morgen bis ins Mondlicht aus – am Sonnenteich, am Nebelfluss, in der Korallenbucht, am Eissee und in der neuen Dschungel-Lagune! Angle bei Regenschauern, goldenen Stunden und Fressrausch, halte die Schnur im grünen Bereich für perfekte Fänge und füll dein Fischbuch mit 45 Fischen.", controls: "Halte <kbd>Space</kbd> oder die Maus zum Aufladen, lass los zum Auswerfen. Tippe, um den Köder anzuhalten und um anzuschlagen, wenn einer beißt. Halte zum Einholen und lass los, wenn die Schnur rot wird. <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Gefundene Arten" },
    pt: { title: "Lago da Sorte", desc: "Jogue sua linha da manhã até o luar no Lago Ensolarado, no Rio Nebuloso, na Baía de Coral, no Lago Congelado e na nova Lagoa da Selva! Pesque em pancadas de chuva, horas douradas e frenesis de peixes, mantenha a linha no verde para Fisgadas Perfeitas e complete seu Livro dos Peixes com 45 espécies.", controls: "Segure <kbd>Space</kbd> ou o mouse para carregar e solte para arremessar. Toque para parar a isca e para fisgar quando o peixe morder. Segure para puxar a linha e solte quando ela ficar vermelha. <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Espécies achadas" },
  },
  shadowheist: {
    ko: { title: "그림자 대도둑", desc: "살금살금 고양이 도둑이 되어 박물관, 저택, 은행에서 도둑맞은 보물을 되찾아요! 손전등 불빛을 피하고, 동전을 던져 경비원과 강아지의 주의를 돌리고, 환기구로 기어가서 황금 회중시계를 슬쩍하세요. 털 때마다 별 3개를 노리고, 매일 새로운 데일리 작전에 도전!", controls: "<kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> 또는 방향키(또는 클릭)로 이동, <kbd>Shift</kbd>를 누르고 있으면 살금살금, <kbd>E</kbd> 또는 오른쪽 클릭으로 동전 던지기, <kbd>Space</kbd> 연막탄, <kbd>P</kbd> 일시정지", label: "모은 별" },
    ja: { title: "怪盗シャドウ", desc: "こっそり怪盗ネコになって、博物館、お屋しき、銀行からぬすまれたお宝を取りもどそう！懐中電灯の光をよけて、コインを投げて警備員とワンちゃんの気をそらし、通気口をはって進み、金の懐中時計をいただこう。ミッションごとにスター3つをねらって、毎日新しいデイリーミッションにも挑戦！", controls: "<kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> または矢印キー（またはクリック）で移動、<kbd>Shift</kbd> 長押しで忍び足、<kbd>E</kbd> か右クリックでコインを投げる、<kbd>Space</kbd> けむり玉、<kbd>P</kbd> 一時停止", label: "獲得スター" },
    zh: { title: "暗影大盗", desc: "化身鬼鬼祟祟的猫咪神偷，从博物馆、庄园和银行夺回被偷走的宝藏！躲开手电筒的光，扔硬币引开保安和他们的小狗，钻进通风管道，顺走金怀表。每次行动都争取 3 颗星星，每天还有全新的每日行动！", controls: "<kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> 或方向键（或点击）移动，按住 <kbd>Shift</kbd> 潜行，<kbd>E</kbd> 或右键扔硬币，<kbd>Space</kbd> 烟雾弹，<kbd>P</kbd> 暂停", label: "获得星星" },
    es: { title: "Golpe en las Sombras", desc: "¡Conviértete en un gato ladrón sigiloso y recupera tesoros robados de un museo, una mansión y un banco! Esquiva los haces de las linternas, lanza monedas para distraer a los guardias y sus perritos, gatea por los conductos de ventilación y birla relojes de bolsillo dorados. ¡Consigue 3 estrellas por golpe y prueba un Golpe Diario nuevo cada día!", controls: "<kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> o flechas (o clic) para moverte, mantén <kbd>Shift</kbd> para ir sigiloso, <kbd>E</kbd> o clic derecho para lanzar una moneda, <kbd>Space</kbd> bomba de humo, <kbd>P</kbd> pausa", label: "Estrellas ganadas" },
    fr: { title: "Casse dans l'Ombre", desc: "Deviens un chat cambrioleur rusé et récupère des trésors volés dans un musée, un manoir et une banque ! Évite les faisceaux des lampes torches, lance des pièces pour distraire les gardes et leurs chiots, rampe dans les conduits d'aération et chipe des montres à gousset dorées. Gagne 3 étoiles par casse et tente un nouveau Casse du jour chaque jour !", controls: "<kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> ou les flèches (ou clic) pour bouger, maintiens <kbd>Shift</kbd> pour te faufiler, <kbd>E</kbd> ou clic droit pour lancer une pièce, <kbd>Space</kbd> bombe fumigène, <kbd>P</kbd> pause", label: "Étoiles gagnées" },
    de: { title: "Schatten-Coup", desc: "Werde eine schlaue Katzen-Meisterdiebin und hol gestohlene Schätze aus einem Museum, einem Herrenhaus und einer Bank zurück! Bleib aus den Taschenlampenkegeln, wirf Münzen, um Wachen und ihre Hündchen abzulenken, kriech durch Lüftungsschächte und stibitz goldene Taschenuhren. Hol dir 3 Sterne pro Coup und probier jeden Tag einen neuen Tages-Coup!", controls: "<kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> oder Pfeiltasten (oder Klick) zum Bewegen, <kbd>Shift</kbd> halten zum Schleichen, <kbd>E</kbd> oder Rechtsklick wirft eine Münze, <kbd>Space</kbd> Rauchbombe, <kbd>P</kbd> Pause", label: "Gesammelte Sterne" },
    pt: { title: "Assalto nas Sombras", desc: "Seja um gato ladrão sorrateiro e recupere tesouros roubados de um museu, uma mansão e um banco! Fique longe dos fachos das lanternas, jogue moedas para distrair os guardas e seus cachorrinhos, rasteje pelos dutos de ar e surrupie relógios de bolso dourados. Ganhe 3 estrelas por assalto e tente um Assalto Diário novo todo dia!", controls: "<kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> ou setas (ou clique) para andar, segure <kbd>Shift</kbd> para andar escondido, <kbd>E</kbd> ou clique direito para jogar uma moeda, <kbd>Space</kbd> bomba de fumaça, <kbd>P</kbd> pausar", label: "Estrelas ganhas" },
  },
  wordwizard: {
    ko: { title: "단어 마법사", desc: "마법 글자 타일로 영어 단어를 만들어 슬라임, 유령, 드래곤을 날려 버려요! 마법책은 단어를 1만 개 넘게 알고 있고, 긴 단어일수록 마법이 세져요. 마나 구슬을 채워 유성우를 퍼붓고, 글자를 사슬로 묶는 임프를 조심하고, 불꽃 왕을 물리치고, 데일리 주문 연습에도 도전하세요!", controls: "타일을 클릭하거나 글자를 입력하고, <kbd>Enter</kbd>로 주문 발사, <kbd>Backspace</kbd>로 되돌리기. <kbd>1</kbd> 물약, <kbd>2</kbd> 힌트, <kbd>3</kbd> 섞기, <kbd>4</kbd> 특수 마법, <kbd>Esc</kbd> 지우기 또는 일시정지", label: "모은 별" },
    ja: { title: "ワードウィザード", desc: "魔法の文字タイルで英単語をつづって、スライム、おばけ、ドラゴンをふっとばそう！呪文の本は1万語以上を知っていて、長い単語ほど強い魔法になるよ。マナオーブをためてメテオシャワーを放ち、文字をくさりでしばるインプに注意して、炎の王をたおそう。デイリー呪文練習にも挑戦！", controls: "タイルをクリックするか文字を入力、<kbd>Enter</kbd> で呪文を放つ、<kbd>Backspace</kbd> で取り消し。<kbd>1</kbd> ポーション、<kbd>2</kbd> ヒント、<kbd>3</kbd> シャッフル、<kbd>4</kbd> 必殺呪文、<kbd>Esc</kbd> クリアか一時停止", label: "獲得スター" },
    zh: { title: "单词巫师", desc: "用魔法字母块拼出英文单词，轰飞史莱姆、幽灵和巨龙！你的魔法书认识一万多个单词，单词越长，法术越强。攒满法力球释放流星雨，小心会用锁链锁住字母的小恶魔，打败余烬之王，再来试试每日咒语练习！", controls: "点击字母块或直接打字，<kbd>Enter</kbd> 施法，<kbd>Backspace</kbd> 撤销。<kbd>1</kbd> 药水，<kbd>2</kbd> 提示，<kbd>3</kbd> 打乱，<kbd>4</kbd> 特殊法术，<kbd>Esc</kbd> 清空或暂停", label: "获得星星" },
    es: { title: "Mago de las Palabras", desc: "¡Forma palabras en inglés con fichas de letras mágicas para fulminar slimes, fantasmas y dragones! Tu libro de hechizos conoce más de 10.000 palabras, y cuanto más larga la palabra, más fuerte el hechizo. Llena tu orbe de maná para desatar una Lluvia de Meteoros, cuidado con los diablillos que encadenan tus letras, derrota al Rey Ascua ¡y prueba la Práctica de Hechizos Diaria!", controls: "Haz clic en las fichas o escribe las letras, <kbd>Enter</kbd> para lanzar, <kbd>Backspace</kbd> para deshacer. <kbd>1</kbd> poción, <kbd>2</kbd> pista, <kbd>3</kbd> mezclar, <kbd>4</kbd> hechizo especial, <kbd>Esc</kbd> borrar o pausa", label: "Estrellas ganadas" },
    fr: { title: "Le Sorcier des Mots", desc: "Forme des mots anglais avec des tuiles de lettres magiques pour pulvériser slimes, fantômes et dragons ! Ton grimoire connaît plus de 10 000 mots, et plus le mot est long, plus le sort est puissant. Remplis ton orbe de mana pour déclencher une Pluie de Météores, méfie-toi des diablotins qui enchaînent tes lettres, bats le Roi des Braises et essaie l'Entraînement de sorts du jour !", controls: "Clique sur les tuiles ou tape les lettres, <kbd>Enter</kbd> pour lancer le sort, <kbd>Backspace</kbd> pour annuler. <kbd>1</kbd> potion, <kbd>2</kbd> indice, <kbd>3</kbd> mélanger, <kbd>4</kbd> sort spécial, <kbd>Esc</kbd> effacer ou pause", label: "Étoiles gagnées" },
    de: { title: "Wort-Zauberer", desc: "Bilde englische Wörter aus magischen Buchstabenplättchen und puste Schleime, Geister und Drachen weg! Dein Zauberbuch kennt über 10.000 Wörter, und je länger das Wort, desto stärker der Zauber. Füll deine Mana-Kugel für einen Meteorschauer, pass auf Kobolde auf, die deine Buchstaben anketten, besiege den Glutkönig und probier das tägliche Zaubertraining!", controls: "Klicke Plättchen an oder tippe die Buchstaben, <kbd>Enter</kbd> zum Zaubern, <kbd>Backspace</kbd> zum Rückgängigmachen. <kbd>1</kbd> Trank, <kbd>2</kbd> Tipp, <kbd>3</kbd> mischen, <kbd>4</kbd> Spezialzauber, <kbd>Esc</kbd> löschen oder Pause", label: "Gesammelte Sterne" },
    pt: { title: "Mago das Palavras", desc: "Forme palavras em inglês com peças de letras mágicas para detonar gosmas, fantasmas e dragões! Seu livro de feitiços conhece mais de 10.000 palavras, e quanto maior a palavra, mais forte o feitiço. Encha seu orbe de mana para soltar uma Chuva de Meteoros, cuidado com os diabretes que acorrentam suas letras, derrote o Rei das Brasas e tente o Treino de Feitiços Diário!", controls: "Clique nas peças ou digite as letras, <kbd>Enter</kbd> para lançar, <kbd>Backspace</kbd> para desfazer. <kbd>1</kbd> poção, <kbd>2</kbd> dica, <kbd>3</kbd> embaralhar, <kbd>4</kbd> feitiço especial, <kbd>Esc</kbd> limpar ou pausar", label: "Estrelas ganhas" },
  },
  starblaster: {
    ko: { title: "스타 블래스터", desc: "별빛 전투기를 몰고 빛나는 은하 3곳을 누비며 외계인 편대, 기뢰 부설선, 방패 드론을 날려 버려요! 확산탄, 레이저, 황금 윙맨 드론을 챙기고, 오버드라이브로 화력을 두 배로 올리고, 크랩 드레드노트와 공허 황제 같은 거대한 보스를 물리치세요. 보스에게 졌다고요? 바로 재대결!", controls: "마우스, 손가락 드래그, 또는 <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> / 방향키로 비행. 자동으로 쏴요(또는 <kbd>Space</kbd>를 누르고 있기). <kbd>B</kbd> 또는 오른쪽 클릭으로 폭탄, <kbd>Shift</kbd> 또는 <kbd>V</kbd>로 오버드라이브, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "모은 별" },
    ja: { title: "スターブラスター", desc: "スターファイターに乗って3つのかがやく銀河を飛び、エイリアン編隊、機雷をまく敵、シールドドローンをうちたおせ！拡散ショット、レーザー、金色のウイングマンドローンをゲットして、オーバードライブで火力2倍。カニ型戦艦や虚空の皇帝みたいな巨大ボスをやっつけよう。ボスに負けた？すぐにリベンジだ！", controls: "マウス、指でドラッグ、または <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> / 矢印キーで飛ぶ。ショットは自動（または <kbd>Space</kbd> 長押し）。<kbd>B</kbd> か右クリックでボム、<kbd>Shift</kbd> か <kbd>V</kbd> でオーバードライブ、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "獲得スター" },
    zh: { title: "星际爆破手", desc: "驾驶星际战机穿越 3 个闪耀的星系，轰掉外星中队、布雷舰和护盾无人机！抢到散射弹、激光和金色僚机，开启超频让火力翻倍，打败螃蟹无畏舰和虚空皇帝这样的巨型Boss。输给Boss了？立刻再战一场！", controls: "用鼠标、手指拖动或 <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> / 方向键飞行。会自动射击（也可以按住 <kbd>Space</kbd>）。<kbd>B</kbd> 或右键放炸弹，<kbd>Shift</kbd> 或 <kbd>V</kbd> 开启超频，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "获得星星" },
    es: { title: "Cañón Estelar", desc: "¡Pilota un caza estelar por 3 galaxias brillantes y revienta escuadrones alienígenas, sembradores de minas y drones con escudo! Coge disparos múltiples, láseres y drones escolta dorados, activa la Sobremarcha para el doble de potencia y derrota a jefes gigantes como el Acorazado Cangrejo y el Emperador del Vacío. ¿Perdiste contra un jefe? ¡Revancha al instante!", controls: "Vuela con el ratón, arrastrando el dedo o con <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> / flechas. Dispara solo (o mantén <kbd>Space</kbd>). <kbd>B</kbd> o clic derecho para una bomba, <kbd>Shift</kbd> o <kbd>V</kbd> para la Sobremarcha, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Estrellas ganadas" },
    fr: { title: "Blaster Stellaire", desc: "Pilote un chasseur stellaire à travers 3 galaxies scintillantes et dégomme des escadrons aliens, des poseurs de mines et des drones à bouclier ! Attrape tirs multiples, lasers et drones ailiers dorés, active la Surchauffe pour doubler ta puissance de feu et bats des boss géants comme le Crabe Cuirassé et l'Empereur du Néant. Battu par un boss ? Revanche immédiate !", controls: "Vole avec la souris, en glissant le doigt ou avec <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> / les flèches. Le tir est automatique (ou maintiens <kbd>Space</kbd>). <kbd>B</kbd> ou clic droit pour une bombe, <kbd>Shift</kbd> ou <kbd>V</kbd> pour la Surchauffe, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Étoiles gagnées" },
    de: { title: "Sternenblaster", desc: "Flieg einen Sternenjäger durch 3 leuchtende Galaxien und schieß Alien-Staffeln, Minenleger und Schilddrohnen ab! Schnapp dir Streuschüsse, Laser und goldene Flügeldrohnen, zünde den Overdrive für doppelte Feuerkraft und besiege Riesenbosse wie den Krabben-Kreuzer und den Leere-Kaiser. Gegen einen Boss verloren? Sofort Revanche!", controls: "Flieg mit der Maus, per Fingerziehen oder mit <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> / Pfeiltasten. Es schießt von selbst (oder halte <kbd>Space</kbd>). <kbd>B</kbd> oder Rechtsklick für eine Bombe, <kbd>Shift</kbd> oder <kbd>V</kbd> für Overdrive, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Gesammelte Sterne" },
    pt: { title: "Blaster Estelar", desc: "Pilote um caça estelar por 3 galáxias brilhantes e detone esquadrões alienígenas, lançadores de minas e drones com escudo! Pegue tiros espalhados, lasers e drones parceiros dourados, ative a Sobrecarga para dobrar o poder de fogo e derrote chefões gigantes como o Encouraçado Caranguejo e o Imperador do Vazio. Perdeu para um chefão? Revanche na hora!", controls: "Voe com o mouse, arrastando o dedo ou com <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> / setas. Ele atira sozinho (ou segure <kbd>Space</kbd>). <kbd>B</kbd> ou clique direito para uma bomba, <kbd>Shift</kbd> ou <kbd>V</kbd> para a Sobrecarga, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Estrelas ganhas" },
  },
  hoopshot: {
    ko: { title: "농구왕 슛", desc: "함성이 터지는 경기장에서 휙 튕겨 슛을 쏴요! 클린슛을 연달아 넣어 불타오르고, 시간 공과 무지개 공 같은 특별한 공을 잡고, 트릭 슛 챌린지 25개에서 블록 로봇 블로키를 이기고, 컴퓨터와 HORSE 대결을 하고, 매일 새로운 데일리 슛아웃을 즐기세요.", controls: "마우스나 손가락으로 골대를 향해 위로 휙 튕기세요. 또는 <kbd>↑</kbd> <kbd>↓</kbd>로 조준하고 <kbd>Space</kbd>를 누르고 있으면 힘이 모여요. <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "최고 점수" },
    ja: { title: "フープショット", desc: "大歓声のアリーナで、フリックしてシュートを決めよう！スウィッシュを連続で決めて燃え上がり、時間ボールやにじ色ボールをゲット。25のトリックショットチャレンジでブロックロボのブロッキーを出しぬき、CPUとHORSE対決、毎日新しいデイリーシュートアウトも楽しめるよ。", controls: "マウスか指でゴールに向かって上にフリック。または <kbd>↑</kbd> <kbd>↓</kbd> でねらって <kbd>Space</kbd> 長押しでパワーをためる。<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "ベストスコア" },
    zh: { title: "投篮高手", desc: "在欢声雷动的球馆里轻轻一甩就投篮！连续空心入网让你手感火热，抢到时间球和彩虹球，在 25 个花式投篮挑战中智胜挡板机器人布洛基，和电脑比拼 HORSE，每天还有全新的每日投篮赛！", controls: "用鼠标或手指朝篮筐往上一甩。也可以用 <kbd>↑</kbd> <kbd>↓</kbd> 瞄准，按住 <kbd>Space</kbd> 蓄力。<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "最高分" },
    es: { title: "Tiro a Canasta", desc: "¡Desliza para encestar en un estadio rugiente! Mete canastas limpias para ponerte en racha de fuego, coge balones especiales de tiempo y arcoíris, supera a Blocky, el robot taponador, en 25 desafíos de tiros de fantasía, gana a la CPU al HORSE y juega un Concurso de Tiros Diario nuevo cada día.", controls: "Desliza hacia arriba, hacia el aro, con el ratón o el dedo, o apunta con <kbd>↑</kbd> <kbd>↓</kbd> y mantén <kbd>Space</kbd> para cargar. <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Mejor puntuación" },
    fr: { title: "Tir au Panier", desc: "Lance d'un coup de doigt dans une salle en délire ! Enchaîne les paniers parfaits pour t'enflammer, attrape les ballons spéciaux temps et arc-en-ciel, déjoue Blocky le robot contreur dans 25 défis de tirs acrobatiques, bats l'ordi au HORSE et joue un nouveau Concours de tirs du jour chaque jour.", controls: "Glisse vers le haut, vers le panier, avec la souris ou le doigt, ou vise avec <kbd>↑</kbd> <kbd>↓</kbd> et maintiens <kbd>Space</kbd> pour charger. <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Meilleur score" },
    de: { title: "Korbjäger", desc: "Schnipp den Ball in einer tobenden Arena in den Korb! Versenke saubere Würfe, bis du Feuer fängst, schnapp dir Zeit- und Regenbogenbälle, trickse Blocky den Blockroboter in 25 Trickwurf-Challenges aus, schlag den Computer bei HORSE und spiel jeden Tag ein neues Tages-Werfen.", controls: "Schnipp mit der Maus oder dem Finger nach oben zum Korb, oder ziel mit <kbd>↑</kbd> <kbd>↓</kbd> und halte <kbd>Space</kbd> zum Aufladen. <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Beste Punktzahl" },
    pt: { title: "Arremesso Certeiro", desc: "Deslize para arremessar numa arena lotada! Acerte cestas limpas para pegar fogo, pegue bolas especiais de tempo e arco-íris, engane Blocky, o robô bloqueador, em 25 desafios de arremessos malucos, vença o computador no HORSE e jogue um Desafio de Arremessos Diário novo todo dia.", controls: "Deslize para cima, rumo à cesta, com o mouse ou o dedo, ou mire com <kbd>↑</kbd> <kbd>↓</kbd> e segure <kbd>Space</kbd> para carregar. <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Melhor pontuação" },
  },
  petpals: {
    ko: { title: "펫 친구들", desc: "강아지, 고양이, 토끼를 입양해서 단짝 친구가 되어 보세요! 밥 주고, 씻기고, 꼭 안아 주고, 재주를 가르치고, 정원에서 맛있는 먹이를 기르고, 댄스 파티를 포함한 미니게임 5개를 즐겨요. 매일 소원을 들어주고, 스티커북을 채우고, 간식, 옷, 방 꾸미기 아이템을 사세요.", controls: "버튼을 클릭하거나 탭해서 펫을 돌보고, 간식을 입으로 끌어다 주고, 펫을 문질러 쓰다듬어 주세요. <kbd>1</kbd>–<kbd>9</kbd>와 <kbd>0</kbd> 행동 고르기, 재주 연습 중에는 <kbd>Space</kbd>. 미니게임은 마우스나 터치로 하고, 간식 받기에서는 <kbd>←</kbd> <kbd>→</kbd>, 공 물어오기에서는 <kbd>Space</kbd> 누르기, 댄스 파티에서는 <kbd>←</kbd> <kbd>↑</kbd> <kbd>→</kbd>도 써요. <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거.", label: "펫 레벨" },
    ja: { title: "ペットなかよし", desc: "子犬、子ネコ、子ウサギをむかえて、大親友になろう！ごはんをあげて、洗って、ぎゅっとして、芸を教えて、お庭でおいしいごはんを育てよう。ダンスパーティーをふくむ5つのミニゲームも遊べるよ。毎日のおねがいをかなえて、シール帳をうめて、おやつや服、お部屋のかざりを買おう。", controls: "ボタンをクリックかタップしてお世話、おやつを口までドラッグ、ペットをなでなでしてスキンシップ。<kbd>1</kbd>–<kbd>9</kbd> と <kbd>0</kbd> で行動を選ぶ、芸の練習中は <kbd>Space</kbd>。ミニゲームはマウスかタッチ、おやつキャッチでは <kbd>←</kbd> <kbd>→</kbd>、ボール取りでは <kbd>Space</kbd> 長押し、ダンスパーティーでは <kbd>←</kbd> <kbd>↑</kbd> <kbd>→</kbd> も使うよ。<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート。", label: "ペットのレベル" },
    zh: { title: "宠物好伙伴", desc: "领养一只小狗、小猫或小兔子，和它成为最好的朋友！喂它吃饭、帮它洗澡、抱抱它、教它才艺，在花园里种好吃的，还能玩包括舞会在内的 5 个小游戏。每天实现它的愿望，集满贴纸册，再去买零食、服装和房间装饰吧。", controls: "点击或轻触按钮照顾宠物，把零食拖到它嘴边，摸摸它就能抱抱。<kbd>1</kbd>–<kbd>9</kbd> 和 <kbd>0</kbd> 选择动作，才艺练习时按 <kbd>Space</kbd>。小游戏用鼠标或触屏，接零食用 <kbd>←</kbd> <kbd>→</kbd>，捡球按住 <kbd>Space</kbd>，舞会用 <kbd>←</kbd> <kbd>↑</kbd> <kbd>→</kbd>。<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音。", label: "宠物等级" },
    es: { title: "Amigos Mascota", desc: "¡Adopta un perrito, un gatito o un conejito y hazlo tu mejor amigo! Dale de comer, báñalo, abrázalo y enséñale trucos, cultiva comida riquísima en el jardín y juega a cinco minijuegos, entre ellos una Fiesta de Baile. Cumple deseos diarios, llena tu álbum de pegatinas y compra golosinas, ropa y decoración para su cuarto.", controls: "Haz clic o toca los botones para cuidar a tu mascota, arrastra golosinas hasta su boca y acaríciala para darle mimos. <kbd>1</kbd>–<kbd>9</kbd> y <kbd>0</kbd> eligen acciones, <kbd>Space</kbd> al practicar trucos. Los minijuegos usan el ratón o la pantalla táctil, además de <kbd>←</kbd> <kbd>→</kbd> en Atrapa Golosinas, mantener <kbd>Space</kbd> en Trae la Pelota y <kbd>←</kbd> <kbd>↑</kbd> <kbd>→</kbd> en la Fiesta de Baile. <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar.", label: "Nivel de mascota" },
    fr: { title: "Mes Copains Animaux", desc: "Adopte un chiot, un chaton ou un lapin et deviens son meilleur ami ! Nourris-le, lave-le, fais-lui des câlins et apprends-lui des tours, fais pousser de bons petits plats au jardin et joue à cinq mini-jeux, dont une Fête dansante. Exauce ses souhaits du jour, remplis ton album d'autocollants et achète friandises, tenues et déco pour sa chambre.", controls: "Clique ou touche les boutons pour t'occuper de ton animal, glisse les friandises jusqu'à sa bouche et caresse-le pour un câlin. <kbd>1</kbd>–<kbd>9</kbd> et <kbd>0</kbd> choisissent les actions, <kbd>Space</kbd> pendant l'entraînement aux tours. Les mini-jeux se jouent à la souris ou au doigt, avec <kbd>←</kbd> <kbd>→</kbd> dans Attrape-Friandises, <kbd>Space</kbd> maintenu dans Va chercher et <kbd>←</kbd> <kbd>↑</kbd> <kbd>→</kbd> dans la Fête dansante. <kbd>P</kbd> pause, <kbd>M</kbd> couper le son.", label: "Niveau de l'animal" },
    de: { title: "Tierfreunde", desc: "Adoptiere einen Welpen, ein Kätzchen oder ein Häschen und werdet beste Freunde! Füttern, waschen, kuscheln und Kunststücke beibringen, leckeres Futter im Garten anbauen und fünf Minispiele spielen, darunter eine Tanzparty. Erfülle tägliche Wünsche, füll dein Stickerbuch und kauf Leckerlis, Outfits und Deko fürs Zimmer.", controls: "Klicke oder tippe auf die Buttons, um dein Haustier zu versorgen, zieh Leckerlis zu seinem Maul und streichle es zum Kuscheln. <kbd>1</kbd>–<kbd>9</kbd> und <kbd>0</kbd> wählen Aktionen, <kbd>Space</kbd> beim Kunststück-Training. Minispiele gehen mit Maus oder Touch, dazu <kbd>←</kbd> <kbd>→</kbd> beim Leckerli-Fangen, <kbd>Space</kbd> halten beim Apportieren und <kbd>←</kbd> <kbd>↑</kbd> <kbd>→</kbd> bei der Tanzparty. <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus.", label: "Haustier-Level" },
    pt: { title: "Amigos Pets", desc: "Adote um cachorrinho, um gatinho ou um coelhinho e vire o melhor amigo dele! Dê comida, dê banho, faça carinho e ensine truques, plante comidinhas gostosas no jardim e jogue cinco minijogos, incluindo uma Festa de Dança. Realize desejos diários, complete seu álbum de figurinhas e compre petiscos, roupinhas e decoração para o quarto.", controls: "Clique ou toque nos botões para cuidar do seu pet, arraste petiscos até a boca dele e faça carinho para ganhar um chamego. <kbd>1</kbd>–<kbd>9</kbd> e <kbd>0</kbd> escolhem ações, <kbd>Space</kbd> no treino de truques. Os minijogos usam o mouse ou o toque, além de <kbd>←</kbd> <kbd>→</kbd> no Pega-Petisco, segurar <kbd>Space</kbd> no Buscar e <kbd>←</kbd> <kbd>↑</kbd> <kbd>→</kbd> na Festa de Dança. <kbd>P</kbd> pausar, <kbd>M</kbd> mudo.", label: "Nível do pet" },
  },
  ghostmaze: {
    ko: { title: "유령 미로", desc: "빛나는 미로를 쌩쌩 달리며 별을 모두 모으세요! 장난꾸러기 유령들이 쫓아오고, 그중 지피는 엄청 빨라요! 파워 구슬, 스피드 운동화, 눈송이를 챙기고, 별 체인을 이어 가고, 월드마다 마지막에 나오는 보스 구름 빅 퍼프를 터뜨리세요. 5개 월드의 미로 25개, 그리고 스타 러시까지!", controls: "<kbd>←</kbd><kbd>↑</kbd><kbd>↓</kbd><kbd>→</kbd> 또는 <kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd>로 이동(미리 방향을 누르면 다음 모퉁이에서 꺾어요), 터치스크린에서는 스와이프. <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거.", label: "최고 점수" },
    ja: { title: "おばけめいろ", desc: "光るめいろをビュンビュン走って、スターを全部集めよう！いたずらおばけが追いかけてくるよ、すばしっこいジッピーもいる！パワーオーブ、スピードスニーカー、雪の結晶をゲットして、スターチェーンをつなげ、各ワールドの最後でボス雲ビッグパフをはじけさせよう。5ワールド25めいろ、さらにスターラッシュも！", controls: "<kbd>←</kbd><kbd>↑</kbd><kbd>↓</kbd><kbd>→</kbd> または <kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> で移動（早めに曲がる方向を押すと次の角で曲がるよ）、タッチ画面ではスワイプ。<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート。", label: "ベストスコア" },
    zh: { title: "幽灵迷宫", desc: "在发光的迷宫里飞速穿梭，收集每一颗星星，调皮的幽灵在后面紧追不舍，还有超快的小快快！抢到能量球、加速跑鞋和雪花，连成星星链，在每个世界的最后戳破Boss云朵大噗噗。5 个世界共 25 座迷宫，外加星星冲刺模式！", controls: "<kbd>←</kbd><kbd>↑</kbd><kbd>↓</kbd><kbd>→</kbd> 或 <kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> 移动（提前按方向，到下个拐角就会转弯），触屏上滑动操作。<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音。", label: "最高分" },
    es: { title: "Laberinto Fantasma", desc: "¡Recorre a toda velocidad laberintos brillantes recogiendo todas las estrellas mientras te persiguen fantasmas traviesos, como el veloz Zippy! Coge orbes de poder, Zapatillas Veloces y Copos de Nieve, encadena estrellas y revienta a Gran Puf, la nube jefe al final de cada mundo. 25 laberintos en 5 mundos, y además Fiebre Estelar.", controls: "<kbd>←</kbd><kbd>↑</kbd><kbd>↓</kbd><kbd>→</kbd> o <kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> para moverte (pulsa el giro antes para tomar la próxima esquina) o desliza en pantallas táctiles. <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar.", label: "Mejor puntuación" },
    fr: { title: "Labyrinthe Fantôme", desc: "File à toute allure dans des labyrinthes lumineux pour ramasser toutes les étoiles pendant que des fantômes coquins te poursuivent, dont le super rapide Zippy ! Attrape orbes de pouvoir, Baskets Turbo et Flocons, enchaîne les étoiles et fais éclater Gros Pouf, le nuage boss à la fin de chaque monde. 25 labyrinthes dans 5 mondes, plus la Ruée aux étoiles.", controls: "<kbd>←</kbd><kbd>↑</kbd><kbd>↓</kbd><kbd>→</kbd> ou <kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> pour bouger (appuie tôt sur un virage pour prendre le prochain coin), ou glisse le doigt sur écran tactile. <kbd>P</kbd> pause, <kbd>M</kbd> couper le son.", label: "Meilleur score" },
    de: { title: "Geisterlabyrinth", desc: "Flitz durch leuchtende Labyrinthe und sammle alle Sterne, während freche Geister dich jagen, darunter der blitzschnelle Zippy! Schnapp dir Power-Kugeln, Turbo-Sneaker und Schneeflocken, bilde Sternketten und bring Dicker Puff, die Boss-Wolke am Ende jeder Welt, zum Platzen. 25 Labyrinthe in 5 Welten, dazu Sternen-Rausch.", controls: "<kbd>←</kbd><kbd>↑</kbd><kbd>↓</kbd><kbd>→</kbd> oder <kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> zum Bewegen (drück eine Richtung früh, um an der nächsten Ecke abzubiegen), oder auf Touchscreens wischen. <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus.", label: "Beste Punktzahl" },
    pt: { title: "Labirinto Fantasma", desc: "Dispare por labirintos brilhantes pegando todas as estrelas enquanto fantasmas travessos te perseguem, incluindo o rapidinho Zippy! Pegue orbes de poder, Tênis Velozes e Flocos de Neve, faça correntes de estrelas e estoure o Grande Puf, a nuvem chefona no fim de cada mundo. 25 labirintos em 5 mundos, e ainda a Corrida Estelar.", controls: "<kbd>←</kbd><kbd>↑</kbd><kbd>↓</kbd><kbd>→</kbd> ou <kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> para andar (aperte a curva antes para virar na próxima esquina), ou deslize em telas de toque. <kbd>P</kbd> pausar, <kbd>M</kbd> mudo.", label: "Melhor pontuação" },
  },
  puckblast: {
    ko: { title: "퍽 블래스트", desc: "에어하키 토너먼트에서 웃긴 동물 상대 여덟 명을 상대로 세게 치고, 벽에 튕기고, 슬랩샷을 날려요. 그다음엔 말렛 두 개를 쓰는 너구리 쌍둥이와 대결! 게이지를 채워 휘어 날아가는 슈퍼 샷 불덩이를 쏘고, 60초 트릭 샷에 도전하고, 멋진 테이블, 말렛, 퍽을 열어 보세요.", controls: "마우스를 움직이거나 손가락을 끌어 말렛을 밀어요(또는 <kbd>←</kbd><kbd>↑</kbd><kbd>↓</kbd><kbd>→</kbd>). 빠르게 휘두르면 슬랩샷, 게이지가 꽉 차면 슈퍼 샷! <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거.", label: "총 별" },
    ja: { title: "パックブラスト", desc: "エアホッケー大会で、ゆかいな動物ライバル8人を相手にスマッシュ、バンクショット、スラップショット！そのあとはマレット2本のアライグマツインズと対決だ。メーターをためてカーブする火の玉スーパーショットを放ち、60秒トリックショットに挑戦して、カッコいいテーブル、マレット、パックを解放しよう。", controls: "マウスを動かすか指でドラッグしてマレットを動かす（または <kbd>←</kbd><kbd>↑</kbd><kbd>↓</kbd><kbd>→</kbd>）。速くふるとスラップショット、メーター満タンでスーパーショット！<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート。", label: "スター合計" },
    zh: { title: "桌上冰球大作战", desc: "在桌上冰球锦标赛中猛击、反弹、抽射，打败八位搞笑的动物对手，再挑战拿两个球拍的浣熊双胞胎！攒满能量放出会拐弯的超级火球射门，试试 60 秒花式射门，解锁超酷的球桌、球拍和冰球。", controls: "移动鼠标或拖动手指来滑动球拍（也可以用 <kbd>←</kbd><kbd>↑</kbd><kbd>↓</kbd><kbd>→</kbd>）。快速挥拍打出抽射，能量满了就是超级射门！<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音。", label: "星星总数" },
    es: { title: "Hockey Explosivo", desc: "¡Golpea, rebota y lanza cañonazos en un torneo de hockey de aire contra ocho animales divertidísimos, y luego enfréntate a los Gemelos Mapache con dos mazos! Llena tu medidor para lanzar una bola de fuego curva, el Supertiro, prueba los Tiros de Fantasía de 60 segundos y desbloquea mesas, mazos y discos alucinantes.", controls: "Mueve el ratón o arrastra el dedo para deslizar tu mazo (o usa <kbd>←</kbd><kbd>↑</kbd><kbd>↓</kbd><kbd>→</kbd>). Golpea rápido para un cañonazo; ¡con el medidor lleno haces un Supertiro! <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar.", label: "Estrellas totales" },
    fr: { title: "Palet Explosif", desc: "Frappe, fais rebondir et envoie des tirs foudroyants dans un tournoi de air hockey contre huit adversaires animaux rigolos, puis affronte les Jumeaux Ratons et leurs deux maillets ! Remplis ta jauge pour une boule de feu courbe, le Super Tir, essaie les Tirs Acrobatiques de 60 secondes et débloque tables, maillets et palets géniaux.", controls: "Bouge la souris ou glisse le doigt pour déplacer ton maillet (ou utilise <kbd>←</kbd><kbd>↑</kbd><kbd>↓</kbd><kbd>→</kbd>). Frappe vite pour un tir foudroyant ; une jauge pleine donne un Super Tir ! <kbd>P</kbd> pause, <kbd>M</kbd> couper le son.", label: "Total d'étoiles" },
    de: { title: "Puck-Knaller", desc: "Schmettere, spiel über Bande und zieh ab in einem Airhockey-Turnier gegen acht lustige Tiergegner, dann tritt gegen die Waschbär-Zwillinge mit zwei Schlägern an! Füll deine Leiste für einen kurvigen Super-Schuss-Feuerball, probier 60-Sekunden-Trickschüsse und schalte coole Tische, Schläger und Pucks frei.", controls: "Beweg die Maus oder zieh mit dem Finger, um deinen Schläger zu schieben (oder nimm <kbd>←</kbd><kbd>↑</kbd><kbd>↓</kbd><kbd>→</kbd>). Schnell zuschlagen für harte Schüsse, eine volle Leiste ergibt einen Super-Schuss! <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus.", label: "Sterne gesamt" },
    pt: { title: "Disco Explosivo", desc: "Bata, tabele e solte petardos num torneio de air hockey contra oito adversários animais engraçados e depois encare os Gêmeos Guaxinins com dois batedores! Encha sua barra para uma bola de fogo curva, o Supertiro, tente as Jogadas de Efeito de 60 segundos e libere mesas, batedores e discos incríveis.", controls: "Mova o mouse ou arraste o dedo para deslizar seu batedor (ou use <kbd>←</kbd><kbd>↑</kbd><kbd>↓</kbd><kbd>→</kbd>). Bata rápido para um petardo; com a barra cheia sai um Supertiro! <kbd>P</kbd> pausar, <kbd>M</kbd> mudo.", label: "Total de estrelas" },
  },
  hoproad: {
    ko: { title: "폴짝 도로", desc: "귀여운 블록 세상에서 붐비는 도로를 폴짝폴짝 건너고, 통나무와 잠수하는 거북이를 타고 강을 건너고, 기찻길을 쌩 지나가요! 버블 방패와 코인 자석 같은 파워업을 챙기고, 빠른 점프 연속 기록을 이어 가고, 사탕 나라로 가는 길에 동물 친구 13마리를 열어 보세요.", controls: "<kbd>↑</kbd> <kbd>←</kbd> <kbd>→</kbd> <kbd>↓</kbd> 또는 <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd>로 점프(<kbd>Space</kbd>는 앞으로 점프). 휴대폰에서는 탭하면 점프, 스와이프하면 방향 전환. <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "최고 거리" },
    ja: { title: "ぴょんぴょんロード", desc: "かわいいブロックの世界で、車がびゅんびゅん走る道路をぴょんとわたり、丸太やもぐるカメに乗って川をこえ、線路をダッシュでかけぬけよう！バブルシールドやコインマグネットなどのパワーアップをゲットして、スピードホップの連続記録をつなぎ、キャンディランドへの道で13匹の動物なかまを解放しよう。", controls: "<kbd>↑</kbd> <kbd>←</kbd> <kbd>→</kbd> <kbd>↓</kbd> または <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> でジャンプ（<kbd>Space</kbd> で前へジャンプ）。スマホではタップでジャンプ、スワイプで向きを変える。<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "最長距離" },
    zh: { title: "跳跳过马路", desc: "在可爱的方块世界里蹦过繁忙的马路，踩着圆木和会潜水的乌龟过河，冲过火车轨道！抢到泡泡护盾和金币磁铁等道具，保持飞快的连跳纪录，在前往糖果乐园的路上解锁 13 位动物朋友。", controls: "用 <kbd>↑</kbd> <kbd>←</kbd> <kbd>→</kbd> <kbd>↓</kbd> 或 <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> 跳跃（<kbd>Space</kbd> 向前跳）。手机上轻点跳跃，滑动转向。<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "最远距离" },
    es: { title: "Salta la Calle", desc: "¡Salta por carreteras llenas de tráfico, móntate en troncos y tortugas buceadoras para cruzar ríos y corre sobre las vías del tren en un mundo de bloques monísimo! Coge potenciadores como el Escudo Burbuja y el Imán de Monedas, mantén una racha de saltos rapidísima y desbloquea 13 amigos animales camino de la Tierra de los Dulces.", controls: "Salta con <kbd>↑</kbd> <kbd>←</kbd> <kbd>→</kbd> <kbd>↓</kbd> o <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> (<kbd>Space</kbd> salta hacia delante). En el móvil, toca para saltar y desliza para girar. <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Mejor distancia" },
    fr: { title: "Saute-Route", desc: "Saute par-dessus les routes animées, chevauche des rondins et des tortues plongeuses pour traverser les rivières et fonce sur les voies ferrées dans un adorable monde en blocs ! Attrape des bonus comme le Bouclier Bulle et l'Aimant à Pièces, garde une série de sauts rapides et débloque 13 amis animaux en route vers le Pays des Bonbons.", controls: "Saute avec <kbd>↑</kbd> <kbd>←</kbd> <kbd>→</kbd> <kbd>↓</kbd> ou <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> (<kbd>Space</kbd> saute en avant). Sur téléphone, touche pour sauter et glisse pour tourner. <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Meilleure distance" },
    de: { title: "Hüpf-Straße", desc: "Hüpf über volle Straßen, reite auf Baumstämmen und tauchenden Schildkröten über Flüsse und flitz über Bahngleise in einer süßen Klötzchenwelt! Schnapp dir Power-ups wie den Blasenschild und den Münzmagneten, halte eine flotte Hüpfserie am Laufen und schalte auf dem Weg ins Bonbonland 13 Tierfreunde frei.", controls: "Hüpf mit <kbd>↑</kbd> <kbd>←</kbd> <kbd>→</kbd> <kbd>↓</kbd> oder <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> (<kbd>Space</kbd> hüpft nach vorn). Auf dem Handy tippen zum Hüpfen und wischen zum Drehen. <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Weiteste Strecke" },
    pt: { title: "Pula Estrada", desc: "Pule estradas movimentadas, atravesse rios em troncos e tartarugas mergulhadoras e corra pelos trilhos do trem num mundinho de blocos fofo! Pegue poderes como o Escudo de Bolha e o Ímã de Moedas, mantenha uma sequência de pulos rápidos e libere 13 amigos animais a caminho da Terra dos Doces.", controls: "Pule com <kbd>↑</kbd> <kbd>←</kbd> <kbd>→</kbd> <kbd>↓</kbd> ou <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> (<kbd>Space</kbd> pula para a frente). No celular, toque para pular e deslize para virar. <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Melhor distância" },
  },
  tankarena: {
    ko: { title: "탱크 아레나", desc: "귀여운 꼬마 탱크를 몰고 4개 월드의 아레나 32곳을 누비며, 포탄을 벽에 튕겨 로봇 탱크를 펑 하고 색종이로 만들어요! 대시로 위험을 빠져나가고, 떨어지는 폭탄을 피하고, 보스 넷을 물리친 다음, 무한 배틀에서 몇 웨이브나 버티는지 도전하세요.", controls: "<kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> 또는 방향키로 운전, 마우스로 조준하고 클릭해서 발사. <kbd>Shift</kbd> 대시, <kbd>E</kbd> 또는 오른쪽 클릭으로 지뢰 설치. 휴대폰에서는 스틱 두 개와 버튼을 써요. <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "모은 별" },
    ja: { title: "タンクアリーナ", desc: "かわいいミニ戦車で4つのワールドの32アリーナを走りまわり、かべで跳ね返した弾でボット戦車をパーンと紙ふぶきにしちゃおう！ダッシュでピンチをすり抜け、落ちてくるばくだんをよけて、4体のボスをたおしたら、エンドレスバトルで何ウェーブ生きのこれるか挑戦だ。", controls: "<kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> か矢印キーで運転、マウスでねらってクリックで発射。<kbd>Shift</kbd> ダッシュ、<kbd>E</kbd> か右クリックで地雷を置く。スマホでは2本のスティックとボタンを使ってね。<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "獲得スター" },
    zh: { title: "坦克竞技场", desc: "驾驶可爱的小坦克穿越 4 个世界的 32 个竞技场，让炮弹在墙上反弹，把机器人坦克炸成五彩纸屑！冲刺躲开危险，避开从天而降的炸弹，打败四个Boss，再到无尽战斗里看看你能撑过多少波。", controls: "<kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> 或方向键驾驶，鼠标瞄准，点击开火。<kbd>Shift</kbd> 冲刺，<kbd>E</kbd> 或右键放地雷。手机上用两个摇杆和按钮。<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "获得星星" },
    es: { title: "Arena de Tanques", desc: "¡Conduce un tanquecito monísimo por 32 arenas en 4 mundos y haz rebotar tus proyectiles en las paredes para convertir los tanques robot en confeti! Esquiva el peligro con un acelerón, evita las bombas que caen, vence a cuatro jefes y mira cuántas oleadas aguantas en Batalla Infinita.", controls: "Conduce con <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> o las flechas, apunta con el ratón y haz clic para disparar. <kbd>Shift</kbd> acelerón, <kbd>E</kbd> o clic derecho suelta una mina. En el móvil, usa los dos joysticks y los botones. <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Estrellas ganadas" },
    fr: { title: "L'Arène des Tanks", desc: "Pilote un adorable petit tank dans 32 arènes réparties sur 4 mondes et fais rebondir tes obus sur les murs pour transformer les tanks robots en confettis ! Fonce pour esquiver le danger, évite les bombes qui tombent, bats quatre boss, puis vois combien de vagues tu tiens en Bataille infinie.", controls: "Conduis avec <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> ou les flèches, vise avec la souris et clique pour tirer. <kbd>Shift</kbd> foncer, <kbd>E</kbd> ou clic droit pose une mine. Sur téléphone, utilise les deux joysticks et les boutons. <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Étoiles gagnées" },
    de: { title: "Panzer-Arena", desc: "Fahr einen süßen kleinen Panzer durch 32 Arenen in 4 Welten und lass deine Geschosse von den Wänden abprallen, bis die Bot-Panzer als Konfetti zerplatzen! Dash durch Gefahren, weich fallenden Bomben aus, besiege vier Bosse und schau dann, wie viele Wellen du in der Endlos-Schlacht überstehst.", controls: "Fahr mit <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> oder den Pfeiltasten, ziel mit der Maus und klicke zum Schießen. <kbd>Shift</kbd> Dash, <kbd>E</kbd> oder Rechtsklick legt eine Mine. Auf dem Handy nimmst du die zwei Sticks und Buttons. <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Gesammelte Sterne" },
    pt: { title: "Arena de Tanques", desc: "Pilote um tanquinho fofo por 32 arenas em 4 mundos e faça seus tiros quicarem nas paredes para estourar os tanques robôs em confete! Dispare para fugir do perigo, desvie das bombas que caem, vença quatro chefões e veja quantas ondas você aguenta na Batalha Infinita.", controls: "Dirija com <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> ou as setas, mire com o mouse e clique para atirar. <kbd>Shift</kbd> arrancada, <kbd>E</kbd> ou clique direito solta uma mina. No celular, use os dois controles e os botões. <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Estrelas ganhas" },
  },
  slicesquad: {
    ko: { title: "과일 베기 특공대", desc: "날아오는 과일을 쓱 그어 반으로 싹둑 자르세요. 하지만 폭탄은 건드리면 안 돼요! 연속 베기를 늘리고, 거대 수박을 부수고, 시간 베리와 하트 복숭아를 잡고, 매일 새로운 데일리 챌린지에 도전하세요. 클래식, 아케이드, 젠 모드로 즐기고 불타는 칼날 자국을 열어 보세요.", controls: "마우스 버튼을 누른 채로 과일을 가로질러 그어요(또는 손가락으로 드래그). <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "최고 점수" },
    ja: { title: "フルーツスラッシュ隊", desc: "飛んでくるフルーツをシュッとスワイプして、ジューシーに真っ二つ！でもばくだんにはさわらないでね。連続カットをのばし、巨大メロンをわって、タイムベリーやハートピーチをゲット。毎日新しいデイリーチャレンジもあるよ。クラシック、アーケード、ゼンで遊んで、燃える刃の軌跡を解放しよう。", controls: "マウスボタンを押したままフルーツの上をスワイプ（または指でドラッグ）。<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "ベストスコア" },
    zh: { title: "切切小分队", desc: "划一下就把飞来的水果切成多汁的两半，但千万别碰炸弹！拉长连切，劈开巨型西瓜，抓住时间莓和爱心桃，每天还有全新的每日挑战。玩经典、街机或禅模式，解锁炫酷的火焰刀光！", controls: "按住鼠标键划过水果（或用手指拖动）。<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "最高分" },
    es: { title: "Escuadrón Rebanador", desc: "¡Desliza para cortar en jugosas mitades la fruta que vuela, pero no toques las bombas! Alarga tu racha, revienta Melones Gigantes, coge Bayas del Tiempo y Melocotones Corazón y acepta un Desafío Diario nuevo cada día. Juega en Clásico, Arcade o Zen y desbloquea estelas de espada llameantes.", controls: "Mantén el botón del ratón y desliza sobre la fruta (o arrastra un dedo). <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Mejor puntuación" },
    fr: { title: "Brigade Tranche-Fruits", desc: "Glisse pour trancher les fruits volants en moitiés juteuses, mais ne touche pas aux bombes ! Allonge ta série, éclate des Melons Géants, attrape des Baies du Temps et des Pêches Cœur, et relève un nouveau Défi du jour chaque jour. Joue en Classique, Arcade ou Zen et débloque des traînées de lame enflammées.", controls: "Maintiens le bouton de la souris et glisse à travers les fruits (ou glisse le doigt). <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Meilleur score" },
    de: { title: "Schnipsel-Trupp", desc: "Wisch, um fliegendes Obst in saftige Hälften zu schneiden – aber fass bloß keine Bomben an! Bau deine Serie aus, zerschmettere Riesenmelonen, schnapp dir Zeitbeeren und Herzpfirsiche und stell dich jeden Tag einer neuen Tages-Challenge. Spiel Klassik, Arcade oder Zen und schalte lodernde Klingenspuren frei.", controls: "Halte die Maustaste gedrückt und wisch über das Obst (oder zieh mit dem Finger). <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Beste Punktzahl" },
    pt: { title: "Esquadrão Fatiador", desc: "Deslize para fatiar as frutas voadoras em metades suculentas, mas não toque nas bombas! Aumente sua sequência, arrebente Melões Gigantes, pegue Frutinhas do Tempo e Pêssegos Coração e encare um Desafio Diário novo todo dia. Jogue no Clássico, Arcade ou Zen e libere rastros de lâmina flamejantes.", controls: "Segure o botão do mouse e deslize por cima das frutas (ou arraste o dedo). <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Melhor pontuação" },
  },
  mergemania: {
    ko: { title: "머지 마니아", desc: "타일을 밀어서 똑같은 짝끼리 합치면 알이 병아리, 새, 드래곤으로 부화해요! 콤보를 계속 이어 가고, 무지개 와일드 스타를 잡고, 얼음 블록을 녹이고, 목표 레벨 40개나 끝없는 클래식 모드를 즐기세요. 우주, 과자, 보석 타일 세트도 열 수 있어요.", controls: "스와이프하거나 <kbd>←</kbd> <kbd>↑</kbd> <kbd>→</kbd> <kbd>↓</kbd>(또는 <kbd>WASD</kbd>)를 눌러 밀어요. <kbd>Z</kbd> 되돌리기, <kbd>H</kbd> 망치, <kbd>X</kbd> 바꾸기, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "최고 점수" },
    ja: { title: "マージマニア", desc: "タイルをスライドして同じペアを合体させると、タマゴがヒヨコ、鳥、ドラゴンにかえるよ！コンボチェーンをつなげて、にじ色のワイルドスターをキャッチ、氷ブロックをとかして、40の目標レベルかエンドレスのクラシックで遊ぼう。宇宙、スイーツ、宝石のタイルセットも解放できるよ。", controls: "スワイプするか <kbd>←</kbd> <kbd>↑</kbd> <kbd>→</kbd> <kbd>↓</kbd>（または <kbd>WASD</kbd>）でスライド。<kbd>Z</kbd> 取り消し、<kbd>H</kbd> ハンマー、<kbd>X</kbd> 入れかえ、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "ベストスコア" },
    zh: { title: "合成狂热", desc: "滑动方块，让相同的两块合在一起，把蛋孵成小鸡、小鸟，最后变成巨龙！保持连击，抓住彩虹万能星，融化冰块，挑战 40 个目标关卡或无尽的经典模式。还能解锁太空、甜点和宝石方块套装。", controls: "滑动屏幕，或按 <kbd>←</kbd> <kbd>↑</kbd> <kbd>→</kbd> <kbd>↓</kbd>（或 <kbd>WASD</kbd>）来滑动。<kbd>Z</kbd> 撤销，<kbd>H</kbd> 锤子，<kbd>X</kbd> 交换，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "最高分" },
    es: { title: "Fusión Manía", desc: "¡Desliza las fichas y fusiona parejas iguales para que los huevos se conviertan en pollitos, pájaros y dragones! Mantén la cadena de combos, atrapa Estrellas Comodín arcoíris, derrite bloques de hielo y juega 40 niveles con objetivos o el Clásico infinito. Desbloquea juegos de fichas de espacio, dulces y gemas.", controls: "Desliza o pulsa <kbd>←</kbd> <kbd>↑</kbd> <kbd>→</kbd> <kbd>↓</kbd> (o <kbd>WASD</kbd>) para mover. <kbd>Z</kbd> deshacer, <kbd>H</kbd> martillo, <kbd>X</kbd> cambiar, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Mejor puntuación" },
    fr: { title: "Fusion Mania", desc: "Fais glisser les tuiles et fusionne les paires identiques pour faire éclore des œufs en poussins, en oiseaux puis en dragons ! Garde ta chaîne de combos, attrape les Étoiles Joker arc-en-ciel, fais fondre les blocs de glace et joue 40 niveaux à objectifs ou le Classique infini. Débloque des sets de tuiles espace, bonbons et gemmes.", controls: "Glisse le doigt ou appuie sur <kbd>←</kbd> <kbd>↑</kbd> <kbd>→</kbd> <kbd>↓</kbd> (ou <kbd>WASD</kbd>) pour faire glisser. <kbd>Z</kbd> annuler, <kbd>H</kbd> marteau, <kbd>X</kbd> échanger, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Meilleur score" },
    de: { title: "Merge-Mania", desc: "Schieb die Plättchen und verschmelze gleiche Paare, damit aus Eiern Küken, Vögel und Drachen schlüpfen! Halte deine Combo-Kette am Laufen, fang Regenbogen-Joker-Sterne, taue Eisblöcke auf und spiel 40 Ziel-Level oder endlos Klassik. Schalte Weltraum-, Süßigkeiten- und Edelstein-Sets frei.", controls: "Wisch oder drück <kbd>←</kbd> <kbd>↑</kbd> <kbd>→</kbd> <kbd>↓</kbd> (oder <kbd>WASD</kbd>) zum Schieben. <kbd>Z</kbd> rückgängig, <kbd>H</kbd> Hammer, <kbd>X</kbd> tauschen, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Beste Punktzahl" },
    pt: { title: "Fusão Mania", desc: "Deslize as peças e junte pares iguais para chocar ovos em pintinhos, passarinhos e dragões! Mantenha a sequência de combos, pegue as Estrelas Coringa de arco-íris, derreta blocos de gelo e jogue 40 fases com objetivos ou o Clássico infinito. Libere conjuntos de peças de espaço, doces e gemas.", controls: "Deslize ou aperte <kbd>←</kbd> <kbd>↑</kbd> <kbd>→</kbd> <kbd>↓</kbd> (ou <kbd>WASD</kbd>) para mover. <kbd>Z</kbd> desfazer, <kbd>H</kbd> martelo, <kbd>X</kbd> trocar, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Melhor pontuação" },
  },
  goalrush: {
    ko: { title: "골 러시", desc: "빠르고 신나는 2대2 아케이드 축구! 패스하고, 태클하고, 어떤 골키퍼도 못 막는 슈퍼 슛을 충전하고, 파워업을 챙기고, 비 오는 날, 눈 오는 날, 조명 아래 야간 경기까지 즐겨요. 컵 세 개를 차지하고, 승부차기에서 이기고, 표적 연습에서 기록을 세워 보세요.", controls: "<kbd>WASD</kbd> 또는 방향키로 이동. <kbd>Space</kbd> 패스 또는 선수 바꾸기, <kbd>X</kbd>를 누르고 있으면 슛 파워 충전(공이 없으면 슬라이딩 태클), <kbd>Shift</kbd> 전력 질주. 휴대폰에서는 스틱과 버튼. <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "컵 별" },
    ja: { title: "ゴールラッシュ", desc: "スピード満点の2対2アーケードサッカー！パス、タックル、そしてどんなキーパーも止められないスーパーシュートをチャージ。パワーアップをゲットして、雨、雪、ナイターの試合も楽しもう。3つのカップを勝ち取り、PK戦を制して、的当て練習で記録を出そう。", controls: "<kbd>WASD</kbd> か矢印キーで移動。<kbd>Space</kbd> パスか選手切りかえ、<kbd>X</kbd> 長押しでシュートのパワーをためる（ボールがないときはスライディングタックル）、<kbd>Shift</kbd> ダッシュ。スマホではスティックとボタン。<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "カップのスター" },
    zh: { title: "进球冲冲冲", desc: "快节奏的 2 对 2 街机足球！传球、铲断、蓄力打出守门员挡不住的超级射门，抢道具，还能在雨天、雪天和灯光下比赛。赢下三座奖杯，拿下点球大战，在射靶练习里创下纪录！", controls: "<kbd>WASD</kbd> 或方向键移动。<kbd>Space</kbd> 传球或切换球员，按住 <kbd>X</kbd> 蓄力射门（没球时是滑铲），<kbd>Shift</kbd> 冲刺。手机上用摇杆和按钮。<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "杯赛星星" },
    es: { title: "Fiebre de Goles", desc: "¡Fútbol arcade rapidísimo de 2 contra 2! Pasa, entra al rival y carga un Supertiro que ningún portero puede parar, coge potenciadores y juega bajo la lluvia, la nieve y los focos. Gana tres copas, supera las tandas de penaltis y bate un récord en Práctica de Puntería.", controls: "Muévete con <kbd>WASD</kbd> o las flechas. <kbd>Space</kbd> pasar o cambiar de jugador, mantén <kbd>X</kbd> para cargar un tiro (o hacer una entrada deslizante sin balón), <kbd>Shift</kbd> esprintar. Joystick y botones en el móvil. <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Estrellas de copa" },
    fr: { title: "Ruée vers le But", desc: "Du foot arcade ultra rapide en 2 contre 2 ! Passe, tacle et charge un Super Tir qu'aucun gardien ne peut arrêter, attrape des bonus et joue sous la pluie, sous la neige et sous les projecteurs. Remporte trois coupes, gagne les tirs au but et bats un record à l'Entraînement de précision.", controls: "Déplace-toi avec <kbd>WASD</kbd> ou les flèches. <kbd>Space</kbd> passe ou changement de joueur, maintiens <kbd>X</kbd> pour charger un tir (ou faire un tacle glissé sans le ballon), <kbd>Shift</kbd> sprint. Joystick et boutons sur téléphone. <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Étoiles de coupe" },
    de: { title: "Tor-Rausch", desc: "Rasanter 2-gegen-2-Arcade-Fußball! Pass, grätsch und lade einen Super-Schuss auf, den kein Torwart halten kann, schnapp dir Power-ups und spiel bei Regen, Schnee und Flutlicht. Gewinn drei Pokale, entscheide Elfmeterschießen für dich und stell beim Zielschießen einen Rekord auf.", controls: "Beweg dich mit <kbd>WASD</kbd> oder den Pfeiltasten. <kbd>Space</kbd> passen oder Spieler wechseln, <kbd>X</kbd> halten, um einen Schuss aufzuladen (ohne Ball: Grätsche), <kbd>Shift</kbd> sprinten. Stick und Buttons auf dem Handy. <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Pokal-Sterne" },
    pt: { title: "Chuva de Gols", desc: "Futebol arcade rapidinho de 2 contra 2! Passe, dê carrinho e carregue um Supertiro que nenhum goleiro segura, pegue poderes e jogue na chuva, na neve e sob os refletores. Vença três copas, ganhe disputas de pênaltis e bata um recorde no Treino de Mira.", controls: "Ande com <kbd>WASD</kbd> ou as setas. <kbd>Space</kbd> passar ou trocar de jogador, segure <kbd>X</kbd> para carregar o chute (ou dar carrinho sem a bola), <kbd>Shift</kbd> correr. Controle e botões no celular. <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Estrelas da copa" },
  },
  dungeondelve: {
    ko: { title: "던전 탐험", desc: "용감한 꼬마 기사를 이끌고 매번 새롭게 바뀌는 던전을 탐험해요! 슬라임, 박쥐, 가시 공, 몰래 숨은 미믹 상자를 펑 물리치고, 폭탄으로 바위를 부수고, 회전 공격을 충전하고, 친절한 개구리 상인에게서 물건을 사세요. 큰 보스를 쓰러뜨리고 캠프에서 보석으로 업그레이드해요.", controls: "<kbd>WASD</kbd> 또는 방향키로 이동. <kbd>J</kbd> / <kbd>Space</kbd> 또는 왼쪽 클릭으로 칼 휘두르기(누르고 있다가 놓으면 회전 공격), <kbd>K</kbd> / <kbd>Shift</kbd> 또는 오른쪽 클릭으로 대시, <kbd>L</kbd> / <kbd>E</kbd>로 폭탄 놓기. 휴대폰에서는 터치 버튼. <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "가장 깊은 층" },
    ja: { title: "ダンジョン探検", desc: "勇かんな小さな騎士をみちびいて、毎回ちがうダンジョンを進もう！スライム、コウモリ、トゲトゲボール、ずるいミミック宝箱をポンとやっつけ、ばくだんで岩をこわし、回転斬りをチャージして、やさしいカエル商人のお店で買い物しよう。大ボスをたおして、キャンプで宝石を使ってパワーアップ！", controls: "<kbd>WASD</kbd> か矢印キーで移動。<kbd>J</kbd> / <kbd>Space</kbd> か左クリックで剣をふる（長押ししてはなすと回転斬り）、<kbd>K</kbd> / <kbd>Shift</kbd> か右クリックでダッシュ、<kbd>L</kbd> / <kbd>E</kbd> でばくだんを置く。スマホではタッチボタン。<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "最深フロア" },
    zh: { title: "地牢探险", desc: "带领勇敢的小骑士，每次都闯进一座全新的地牢！打爆史莱姆、蝙蝠、刺球和狡猾的宝箱怪，用炸弹炸开岩石，蓄力使出旋风斩，在友善的青蛙商人那里购物。打败大Boss，回营地用宝石升级吧！", controls: "<kbd>WASD</kbd> 或方向键移动。<kbd>J</kbd> / <kbd>Space</kbd> 或鼠标左键挥剑（按住再松开就是旋风斩），<kbd>K</kbd> / <kbd>Shift</kbd> 或右键冲刺，<kbd>L</kbd> / <kbd>E</kbd> 放炸弹。手机上用触屏按钮。<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "最深层数" },
    es: { title: "Aventura en la Mazmorra", desc: "¡Guía a un pequeño caballero valiente por una mazmorra nueva en cada partida! Haz puf a slimes, murciélagos, bolas de pinchos y cofres mímicos tramposos, vuela rocas con bombas, carga un ataque giratorio y compra en la tienda de la simpática rana mercader. Vence a los grandes jefes y gasta tus gemas en mejoras en el campamento.", controls: "Muévete con <kbd>WASD</kbd> o las flechas. <kbd>J</kbd> / <kbd>Space</kbd> o clic izquierdo para dar un espadazo (mantén y suelta para girar), <kbd>K</kbd> / <kbd>Shift</kbd> o clic derecho para esquivar, <kbd>L</kbd> / <kbd>E</kbd> para soltar una bomba. Botones táctiles en el móvil. <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Piso más profundo" },
    fr: { title: "Expédition Donjon", desc: "Guide un petit chevalier courageux dans un tout nouveau donjon à chaque partie ! Fais disparaître slimes, chauves-souris, boules à piques et coffres mimiques sournois, fais sauter des rochers à la bombe, charge une attaque tournoyante et fais tes achats chez la gentille grenouille marchande. Bats les gros boss et dépense tes gemmes en améliorations au camp.", controls: "Déplace-toi avec <kbd>WASD</kbd> ou les flèches. <kbd>J</kbd> / <kbd>Space</kbd> ou clic gauche pour frapper à l'épée (maintiens puis relâche pour tournoyer), <kbd>K</kbd> / <kbd>Shift</kbd> ou clic droit pour une ruée, <kbd>L</kbd> / <kbd>E</kbd> pour poser une bombe. Boutons tactiles sur téléphone. <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Étage le plus profond" },
    de: { title: "Dungeon-Abenteuer", desc: "Führe einen mutigen kleinen Ritter bei jedem Lauf durch einen brandneuen Dungeon! Mach Schleime, Fledermäuse, Stachelkugeln und hinterhältige Mimik-Truhen platt, spreng Felsen mit Bomben, lade eine Wirbelattacke auf und kauf beim freundlichen Froschhändler ein. Besiege die großen Bosse und gib deine Edelsteine im Lager für Upgrades aus.", controls: "Beweg dich mit <kbd>WASD</kbd> oder den Pfeiltasten. <kbd>J</kbd> / <kbd>Space</kbd> oder Linksklick schwingt das Schwert (halten und loslassen für eine Drehung), <kbd>K</kbd> / <kbd>Shift</kbd> oder Rechtsklick zum Dashen, <kbd>L</kbd> / <kbd>E</kbd> legt eine Bombe. Touch-Tasten auf dem Handy. <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Tiefste Ebene" },
    pt: { title: "Aventura na Masmorra", desc: "Guie um cavaleirinho corajoso por uma masmorra novinha a cada partida! Detone gosmas, morcegos, bolas de espinhos e baús mímicos traiçoeiros, exploda pedras com bombas, carregue um ataque giratório e compre na lojinha do simpático sapo mercador. Vença os grandes chefões e gaste suas gemas em melhorias no acampamento.", controls: "Ande com <kbd>WASD</kbd> ou as setas. <kbd>J</kbd> / <kbd>Space</kbd> ou clique esquerdo para golpear com a espada (segure e solte para girar), <kbd>K</kbd> / <kbd>Shift</kbd> ou clique direito para esquivar, <kbd>L</kbd> / <kbd>E</kbd> para soltar uma bomba. Botões de toque no celular. <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Andar mais fundo" },
  },
  kartkings: {
    ko: { title: "카트 킹", desc: "초원, 협곡, 얼음 봉우리, 사탕 나라, 우주에서 동물 라이벌 다섯과 카트 레이스! 드리프트와 점프대 트릭으로 부스트를 얻고, 뒤에 바짝 붙어 슬립스트림을 타고, ? 상자에서 줌 버섯, 뿅 스프링, 무지개 혜성을 뽑고, 타임 트라이얼에서 내 고스트와 겨뤄요. 컵을 따서 카트, 페인트, 레이서를 열어 보세요.", controls: "<kbd>↑</kbd>/<kbd>W</kbd> 가속, <kbd>←</kbd> <kbd>→</kbd> 핸들, <kbd>↓</kbd> 브레이크, <kbd>Shift</kbd>(또는 <kbd>Z</kbd>)를 누르고 있으면 드리프트나 점프대 트릭, <kbd>Space</kbd>(또는 <kbd>X</kbd>) 아이템 사용, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거. 터치 버튼과 게임패드도 돼요.", label: "모은 별" },
    ja: { title: "カートキングス", desc: "草原、峡谷、こおった山、キャンディランド、そして宇宙で、動物ライバル5人とカートレース！ドリフトやジャンプ台トリックでブースト、うしろにピタッとついてスリップストリーム、？ボックスからズームキノコ、ボヨヨンばね、レインボーすい星をゲット。タイムアタックでは自分のゴーストと勝負！カップを勝ち取ってカート、ペイント、レーサーを解放しよう。", controls: "<kbd>↑</kbd>/<kbd>W</kbd> アクセル、<kbd>←</kbd> <kbd>→</kbd> ハンドル、<kbd>↓</kbd> ブレーキ、<kbd>Shift</kbd>（または <kbd>Z</kbd>）長押しでドリフトかジャンプ台トリック、<kbd>Space</kbd>（または <kbd>X</kbd>）アイテムを使う、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート。タッチボタンやゲームパッドも使えるよ。", label: "獲得スター" },
    zh: { title: "卡丁车之王", desc: "和五位动物对手在草原、峡谷、冰峰、糖果乐园和外太空里飙卡丁车！漂移和跳台特技都能加速，紧跟对手吃尾流，打开问号箱拿到加速蘑菇、弹弹弹簧和彩虹彗星，还能在计时赛里挑战自己的幽灵车。赢得奖杯，解锁新车、涂装和赛车手！", controls: "<kbd>↑</kbd>/<kbd>W</kbd> 加速，<kbd>←</kbd> <kbd>→</kbd> 转向，<kbd>↓</kbd> 刹车，按住 <kbd>Shift</kbd>（或 <kbd>Z</kbd>）漂移或做跳台特技，<kbd>Space</kbd>（或 <kbd>X</kbd>）使用道具，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音。也支持触屏按钮和手柄。", label: "获得星星" },
    es: { title: "Reyes del Kart", desc: "¡Corre en karts contra cinco rivales animales por praderas, cañones, picos helados, la tierra de los dulces y el espacio exterior! Derrapa y haz trucos en las rampas para ganar turbo, ponte a rebufo, coge cajas ? con Setas Turbo, Muelles Boing y Cometas Arcoíris, y compite contra tu propio fantasma en Contrarreloj. Gana copas para desbloquear karts, pinturas y pilotos.", controls: "<kbd>↑</kbd>/<kbd>W</kbd> acelerar, <kbd>←</kbd> <kbd>→</kbd> girar, <kbd>↓</kbd> frenar, mantén <kbd>Shift</kbd> (o <kbd>Z</kbd>) para derrapar o hacer un truco en rampa, <kbd>Space</kbd> (o <kbd>X</kbd>) usar un objeto, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar. También funcionan los botones táctiles y los mandos.", label: "Estrellas ganadas" },
    fr: { title: "Les Rois du Kart", desc: "Fais la course en karting contre cinq rivaux animaux dans les prairies, les canyons, les sommets glacés, le pays des bonbons et l'espace ! Drifte et fais des figures sur les tremplins pour des boosts, colle-toi dans l'aspiration, ouvre des boîtes ? pour des Champis Turbo, des Ressorts Boing et des Comètes Arc-en-ciel, et affronte ton propre fantôme en Contre-la-montre. Gagne des coupes pour débloquer karts, peintures et pilotes.", controls: "<kbd>↑</kbd>/<kbd>W</kbd> accélérer, <kbd>←</kbd> <kbd>→</kbd> tourner, <kbd>↓</kbd> freiner, maintiens <kbd>Shift</kbd> (ou <kbd>Z</kbd>) pour drifter ou faire une figure sur tremplin, <kbd>Space</kbd> (ou <kbd>X</kbd>) utiliser un objet, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son. Les boutons tactiles et les manettes marchent aussi.", label: "Étoiles gagnées" },
    de: { title: "Kart-Könige", desc: "Fahr Kartrennen gegen fünf tierische Rivalen über Wiesen, durch Schluchten, über eisige Gipfel, durchs Bonbonland und im Weltall! Drifte und mach Rampentricks für Boosts, häng dich in den Windschatten, schnapp dir ?-Boxen mit Turbo-Pilzen, Boing-Federn und Regenbogen-Kometen und fahr im Zeitfahren gegen deinen eigenen Geist. Gewinn Pokale, um Karts, Lackierungen und Fahrer freizuschalten.", controls: "<kbd>↑</kbd>/<kbd>W</kbd> Gas, <kbd>←</kbd> <kbd>→</kbd> lenken, <kbd>↓</kbd> bremsen, <kbd>Shift</kbd> (oder <kbd>Z</kbd>) halten zum Driften oder für einen Rampentrick, <kbd>Space</kbd> (oder <kbd>X</kbd>) Item benutzen, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus. Touch-Tasten und Gamepads gehen auch.", label: "Gesammelte Sterne" },
    pt: { title: "Reis do Kart", desc: "Corra de kart contra cinco rivais animais por campos, cânions, picos gelados, a terra dos doces e o espaço sideral! Drifte e faça manobras nas rampas para ganhar turbo, pegue o vácuo, abra caixas ? com Cogumelos Turbo, Molas Boing e Cometas Arco-íris, e corra contra seu próprio fantasma no Contra o Relógio. Vença copas para liberar karts, pinturas e pilotos.", controls: "<kbd>↑</kbd>/<kbd>W</kbd> acelerar, <kbd>←</kbd> <kbd>→</kbd> virar, <kbd>↓</kbd> frear, segure <kbd>Shift</kbd> (ou <kbd>Z</kbd>) para driftar ou fazer manobra na rampa, <kbd>Space</kbd> (ou <kbd>X</kbd>) usar um item, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo. Botões de toque e controles também funcionam.", label: "Estrelas ganhas" },
  },
  bubblepop: {
    ko: { title: "버블 팝", desc: "알록달록한 네 월드의 48개 레벨에서 조준하고, 벽에 튕기고, 같은 색 거품 3개를 맞춰 펑펑 터뜨려요! 갇힌 동물 친구들을 구하고, 졸린 바위를 떨어뜨리고, 시계 거품으로 발사 횟수를 늘리고, 한 색깔을 통째로 터뜨리는 슈퍼 샷을 충전하세요. 그다음 끝없는 버블 러시에서 얼마나 버티는지 도전!", controls: "마우스를 움직여 조준하고 클릭해서 쏴요(터치: 끌었다가 놓기). 다음 거품을 클릭하거나 <kbd>X</kbd>를 눌러 바꿔요. <kbd>←</kbd> <kbd>→</kbd> 조준, <kbd>Space</kbd> 발사, <kbd>1</kbd>–<kbd>4</kbd> 부스터, <kbd>Q</kbd> 슈퍼 샷, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거.", label: "모은 별" },
    ja: { title: "バブルポップ", desc: "カラフルな4つのワールドの48レベルで、ねらって、かべに跳ね返して、同じ色のバブルを3つそろえてパチン！とじこめられた動物たちを助け、ねむそうな岩を落とし、時計バブルで発射回数をふやして、1色まるごと消せるスーパーショットをチャージしよう。そのあとはエンドレスのバブルラッシュでどこまで粘れるか挑戦だ。", controls: "マウスを動かしてねらい、クリックで発射（タッチ：ドラッグしてはなす）。次のバブルをクリックするか <kbd>X</kbd> で入れかえ。<kbd>←</kbd> <kbd>→</kbd> ねらう、<kbd>Space</kbd> 発射、<kbd>1</kbd>–<kbd>4</kbd> ブースター、<kbd>Q</kbd> スーパーショット、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート。", label: "獲得スター" },
    zh: { title: "泡泡消消乐", desc: "在四个缤纷世界的 48 个关卡里瞄准、反弹，三个同色泡泡连在一起就啪地消掉！救出被困的小动物，打落瞌睡的石头，抢到时钟泡泡多打几发，蓄满超级射击一次消掉一整种颜色。然后去无尽的泡泡冲刺模式看看你能坚持多久！", controls: "移动鼠标瞄准，点击发射（触屏：拖动后松开）。点击下一个泡泡或按 <kbd>X</kbd> 交换。<kbd>←</kbd> <kbd>→</kbd> 瞄准，<kbd>Space</kbd> 发射，<kbd>1</kbd>–<kbd>4</kbd> 道具，<kbd>Q</kbd> 超级射击，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音。", label: "获得星星" },
    es: { title: "Explota Burbujas", desc: "¡Apunta, rebota y junta 3 burbujas del mismo color para explotarlas en 48 niveles de cuatro mundos llenos de color! Rescata a bichitos atrapados, derriba rocas dormilonas, coge burbujas reloj para tener más tiros y carga un Supertiro que explota todo un color. Luego mira cuánto aguantas en la Fiebre de Burbujas infinita.", controls: "Mueve el ratón para apuntar y haz clic para disparar (en táctil: arrastra y suelta). Haz clic en la siguiente burbuja o pulsa <kbd>X</kbd> para cambiarla. <kbd>←</kbd> <kbd>→</kbd> apuntar, <kbd>Space</kbd> disparar, <kbd>1</kbd>–<kbd>4</kbd> potenciadores, <kbd>Q</kbd> Supertiro, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar.", label: "Estrellas ganadas" },
    fr: { title: "Éclate-Bulles", desc: "Vise, fais rebondir et assemble 3 bulles pour les éclater dans 48 niveaux répartis sur quatre mondes colorés ! Libère les petites bêtes prisonnières, fais tomber les rochers endormis, attrape des bulles horloge pour des tirs en plus et charge un Super Tir qui éclate toute une couleur. Puis vois combien de temps tu tiens dans la Ruée de bulles infinie.", controls: "Bouge la souris pour viser et clique pour tirer (en tactile : glisse puis relâche). Clique sur la bulle suivante ou appuie sur <kbd>X</kbd> pour l'échanger. <kbd>←</kbd> <kbd>→</kbd> viser, <kbd>Space</kbd> tirer, <kbd>1</kbd>–<kbd>4</kbd> bonus, <kbd>Q</kbd> Super Tir, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son.", label: "Étoiles gagnées" },
    de: { title: "Blasen-Plopp", desc: "Ziel, lass abprallen und bring 3 gleiche Blasen zusammen, damit sie platzen – in 48 Leveln in vier bunten Welten! Rette gefangene Tierchen, wirf schläfrige Felsen runter, schnapp dir Uhr-Blasen für Extraschüsse und lade einen Super-Schuss auf, der eine ganze Farbe platzen lässt. Dann schau, wie lange du im endlosen Blasen-Rausch durchhältst.", controls: "Beweg die Maus zum Zielen und klicke zum Schießen (Touch: ziehen, dann loslassen). Klicke die nächste Blase an oder drück <kbd>X</kbd> zum Tauschen. <kbd>←</kbd> <kbd>→</kbd> zielen, <kbd>Space</kbd> schießen, <kbd>1</kbd>–<kbd>4</kbd> Booster, <kbd>Q</kbd> Super-Schuss, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus.", label: "Gesammelte Sterne" },
    pt: { title: "Estoura Bolhas", desc: "Mire, quique e junte 3 bolhas para estourá-las em 48 fases de quatro mundos coloridos! Resgate bichinhos presos, derrube pedras sonolentas, pegue bolhas-relógio para ganhar tiros extras e carregue um Supertiro que estoura uma cor inteira. Depois veja quanto tempo você aguenta na Corrida de Bolhas infinita.", controls: "Mova o mouse para mirar e clique para atirar (no toque: arraste e solte). Clique na próxima bolha ou aperte <kbd>X</kbd> para trocar. <kbd>←</kbd> <kbd>→</kbd> mirar, <kbd>Space</kbd> atirar, <kbd>1</kbd>–<kbd>4</kbd> reforços, <kbd>Q</kbd> Supertiro, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo.", label: "Estrelas ganhas" },
  },
  blockstack: {
    ko: { title: "블록 쌓기", desc: "떨어지는 블록을 쌓아서 한 줄을 꽉 채우면 사라져요! 마라톤, 스프린트 40, 챌린지 32개, 그리고 새로운 데일리 대시를 즐겨요. 반짝이는 보석 블록을 없애 블래스터를 충전하고, 피버 게이지를 채워 점수를 두 배로 받고, 반짝이는 블록 스킨을 열어 보세요.", controls: "<kbd>←</kbd> <kbd>→</kbd> 이동, <kbd>↑</kbd>/<kbd>X</kbd> 회전, <kbd>Z</kbd> 반대로 회전, <kbd>↓</kbd> 천천히 내리기, <kbd>Space</kbd> 바로 떨어뜨리기, <kbd>C</kbd>/<kbd>Shift</kbd> 보관, <kbd>B</kbd> 블래스터, <kbd>R</kbd> 다시 시작, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거. 터치스크린에서는 화면 버튼.", label: "모은 별" },
    ja: { title: "ブロックスタック", desc: "落ちてくるブロックを積んで、横一列をうめると消えるよ！マラソン、スプリント40、32のチャレンジ、そして新しいデイリーダッシュで遊ぼう。キラキラの宝石ブロックを消してブラスターをチャージ、フィーバーメーターをためて得点2倍、ピカピカのブロックスキンも解放しよう。", controls: "<kbd>←</kbd> <kbd>→</kbd> 移動、<kbd>↑</kbd>/<kbd>X</kbd> 回転、<kbd>Z</kbd> 逆回転、<kbd>↓</kbd> ソフトドロップ、<kbd>Space</kbd> ハードドロップ、<kbd>C</kbd>/<kbd>Shift</kbd> ホールド、<kbd>B</kbd> ブラスター、<kbd>R</kbd> やり直し、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート。タッチ画面では画面のボタン。", label: "獲得スター" },
    zh: { title: "方块堆堆乐", desc: "堆起落下的方块，填满一整行就能消除！玩马拉松、40 行冲刺、32 个挑战和全新的每日冲刺。消除闪亮的宝石方块给爆破器充能，攒满狂热槽双倍得分，还能解锁亮闪闪的方块皮肤。", controls: "<kbd>←</kbd> <kbd>→</kbd> 移动，<kbd>↑</kbd>/<kbd>X</kbd> 旋转，<kbd>Z</kbd> 反向旋转，<kbd>↓</kbd> 软降，<kbd>Space</kbd> 硬降，<kbd>C</kbd>/<kbd>Shift</kbd> 暂存，<kbd>B</kbd> 爆破器，<kbd>R</kbd> 重来，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音。触屏上有屏幕按钮。", label: "获得星星" },
    es: { title: "Apila Bloques", desc: "¡Apila los bloques que caen y completa filas enteras para borrarlas! Juega Maratón, Sprint 40, 32 Desafíos y un Sprint Diario nuevo. Borra bloques de gemas brillantes para cargar tu Blaster, llena el medidor de Fiebre para puntos dobles y desbloquea aspectos de bloques relucientes.", controls: "<kbd>←</kbd> <kbd>→</kbd> mover, <kbd>↑</kbd>/<kbd>X</kbd> girar, <kbd>Z</kbd> girar al otro lado, <kbd>↓</kbd> bajar suave, <kbd>Space</kbd> caída rápida, <kbd>C</kbd>/<kbd>Shift</kbd> guardar, <kbd>B</kbd> Blaster, <kbd>R</kbd> reiniciar, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar. Botones en pantalla en dispositivos táctiles.", label: "Estrellas ganadas" },
    fr: { title: "Empile-Blocs", desc: "Empile les blocs qui tombent et remplis des lignes entières pour les effacer ! Joue en Marathon, Sprint 40, 32 Défis et un tout nouveau Sprint du jour. Efface les blocs de gemmes scintillants pour charger ton Blaster, remplis la jauge Fièvre pour doubler tes points et débloque des skins de blocs brillants.", controls: "<kbd>←</kbd> <kbd>→</kbd> déplacer, <kbd>↑</kbd>/<kbd>X</kbd> tourner, <kbd>Z</kbd> tourner dans l'autre sens, <kbd>↓</kbd> descente douce, <kbd>Space</kbd> chute directe, <kbd>C</kbd>/<kbd>Shift</kbd> réserve, <kbd>B</kbd> Blaster, <kbd>R</kbd> recommencer, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son. Boutons à l'écran sur écran tactile.", label: "Étoiles gagnées" },
    de: { title: "Blockstapler", desc: "Stapel die fallenden Blöcke und füll ganze Reihen, um sie aufzulösen! Spiel Marathon, Sprint 40, 32 Challenges und einen brandneuen Tages-Sprint. Lös funkelnde Edelsteinblöcke auf, um deinen Blaster zu laden, füll die Fieber-Leiste für doppelte Punkte und schalte glänzende Block-Skins frei.", controls: "<kbd>←</kbd> <kbd>→</kbd> bewegen, <kbd>↑</kbd>/<kbd>X</kbd> drehen, <kbd>Z</kbd> andersherum drehen, <kbd>↓</kbd> langsam fallen lassen, <kbd>Space</kbd> sofort fallen lassen, <kbd>C</kbd>/<kbd>Shift</kbd> halten, <kbd>B</kbd> Blaster, <kbd>R</kbd> neu starten, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus. Bildschirmtasten auf Touchscreens.", label: "Gesammelte Sterne" },
    pt: { title: "Empilha Blocos", desc: "Empilhe os blocos que caem e complete linhas inteiras para limpá-las! Jogue Maratona, Sprint 40, 32 Desafios e uma Corrida Diária novinha. Limpe blocos de gemas brilhantes para carregar seu Blaster, encha a barra de Febre para pontos em dobro e libere visuais de blocos reluzentes.", controls: "<kbd>←</kbd> <kbd>→</kbd> mover, <kbd>↑</kbd>/<kbd>X</kbd> girar, <kbd>Z</kbd> girar para o outro lado, <kbd>↓</kbd> descer devagar, <kbd>Space</kbd> queda rápida, <kbd>C</kbd>/<kbd>Shift</kbd> guardar, <kbd>B</kbd> Blaster, <kbd>R</kbd> reiniciar, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo. Botões na tela em telas de toque.", label: "Estrelas ganhas" },
  },
  strikelanes: {
    ko: { title: "스트라이크 볼링", desc: "빛나는 볼링장에서 스트라이크를 날려요! 조준하고, 휘게 굴리고, 힘을 조절하고, 라이벌 볼러 10명을 이기고, 핀 퍼즐과 새로운 데일리 챌린지를 풀어 보세요. 메가 볼 같은 파워업을 쓰고, 황금 핀을 맞혀 보너스 코인을 받고, 스트라이크 두 번 연속이면 공에 불이 붙어요!", controls: "마우스를 움직여(또는 끌어서) 위치와 조준을 정하고, 클릭해서 단계마다 확정한 다음, 클릭해서 파워 게이지를 멈춰요. <kbd>←</kbd> <kbd>→</kbd>와 <kbd>Space</kbd>도 돼요. <kbd>↑</kbd> <kbd>↓</kbd> 커브, <kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> 파워업, <kbd>Esc</kbd> 뒤로, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "최고 게임" },
    ja: { title: "ストライクレーン", desc: "光かがやくボウリング場でストライクを決めよう！ねらって、カーブをかけて、パワーを調整。ライバルボウラー10人をたおし、ピンパズルや新しいデイリーチャレンジに挑戦しよう。メガボールなどのパワーアップを使い、金のピンでボーナスコインをゲット。2回連続ストライクでボールが燃えるよ！", controls: "マウスを動かして（またはドラッグして）位置とねらいを決め、クリックで各ステップを決定、もう一度クリックでパワーメーターを止める。<kbd>←</kbd> <kbd>→</kbd> と <kbd>Space</kbd> でもOK。<kbd>↑</kbd> <kbd>↓</kbd> カーブ、<kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> パワーアップ、<kbd>Esc</kbd> もどる、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "ベストゲーム" },
    zh: { title: "全中保龄球", desc: "在闪亮的保龄球馆里打出全中！瞄准、打出弧线、控制力度，击败 10 位对手球员，破解球瓶谜题，挑战全新的每日挑战。使用超级球等道具，击中金色球瓶拿额外金币，连续两次全中，你的球就会燃起火焰！", controls: "移动鼠标（或拖动）来移位和瞄准，点击确认每一步，再点击停住力度条。也可以用 <kbd>←</kbd> <kbd>→</kbd> 和 <kbd>Space</kbd>。<kbd>↑</kbd> <kbd>↓</kbd> 弧线，<kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> 道具，<kbd>Esc</kbd> 返回，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "最佳一局" },
    es: { title: "Bolos Strike", desc: "¡Haz plenos en una bolera brillante! Apunta, dale efecto y potencia a tu tiro, vence a 10 jugadores rivales, resuelve puzles de bolos y un Desafío Diario nuevo. Usa potenciadores como la Megabola, derriba bolos dorados para ganar monedas extra ¡y haz dos plenos seguidos para prenderle fuego a tu bola!", controls: "Mueve el ratón (o arrastra) para colocarte y apuntar, haz clic para fijar cada paso y otra vez para parar el medidor de fuerza. O usa <kbd>←</kbd> <kbd>→</kbd> y <kbd>Space</kbd>. <kbd>↑</kbd> <kbd>↓</kbd> efecto, <kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> potenciadores, <kbd>Esc</kbd> atrás, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Mejor partida" },
    fr: { title: "Bowling Strike", desc: "Enchaîne les strikes dans un bowling lumineux ! Vise, donne de l'effet et dose ta puissance, bats 10 joueurs rivaux, résous des énigmes de quilles et un nouveau Défi du jour. Utilise des bonus comme la Méga Boule, touche les quilles dorées pour des pièces bonus et fais deux strikes d'affilée pour enflammer ta boule !", controls: "Bouge la souris (ou glisse) pour te placer et viser, clique pour valider chaque étape, puis clique pour arrêter la jauge de puissance. Ou utilise <kbd>←</kbd> <kbd>→</kbd> et <kbd>Space</kbd>. <kbd>↑</kbd> <kbd>↓</kbd> effet, <kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> bonus, <kbd>Esc</kbd> retour, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Meilleure partie" },
    de: { title: "Strike-Bahnen", desc: "Wirf Strikes auf einer leuchtenden Bowlingbahn! Ziel, gib Drall und dosier deinen Wurf, besiege 10 Gegner, knack Kegel-Rätsel und eine neue Tages-Challenge. Nutz Power-ups wie die Mega-Kugel, triff goldene Pins für Bonusmünzen und wirf zwei Strikes hintereinander, damit deine Kugel Feuer fängt!", controls: "Beweg die Maus (oder zieh), um dich zu positionieren und zu zielen, klicke, um jeden Schritt festzulegen, und klicke dann, um die Kraftleiste zu stoppen. Oder nimm <kbd>←</kbd> <kbd>→</kbd> und <kbd>Space</kbd>. <kbd>↑</kbd> <kbd>↓</kbd> Drall, <kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> Power-ups, <kbd>Esc</kbd> zurück, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Bestes Spiel" },
    pt: { title: "Pistas do Strike", desc: "Faça strikes numa pista de boliche brilhante! Mire, dê efeito e acerte a força, vença 10 jogadores rivais, resolva quebra-cabeças de pinos e um Desafio Diário novo. Use poderes como a Megabola, derrube pinos dourados para ganhar moedas bônus e faça dois strikes seguidos para pôr fogo na sua bola!", controls: "Mova o mouse (ou arraste) para se posicionar e mirar, clique para confirmar cada etapa e clique de novo para parar a barra de força. Ou use <kbd>←</kbd> <kbd>→</kbd> e <kbd>Space</kbd>. <kbd>↑</kbd> <kbd>↓</kbd> efeito, <kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> poderes, <kbd>Esc</kbd> voltar, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Melhor partida" },
  },
  skaterush: {
    ko: { title: "스케이트 러시", desc: "학교 운동장, 해변 산책로, 네온 거리, 옥상을 누비며 알리, 킥플립, 그랩, 그라인드! 트릭을 이어 거대한 콤보를 만들고, RC카와 게를 뛰어넘고, 파워업 거품을 잡고, 스페셜 게이지를 채워 점수를 두 배로 받아요. 그다음엔 프리 스케이트: 새로운 코스에서 60초 안에 기록을 세워 보세요.", controls: "<kbd>Space</kbd> 또는 탭으로 알리(누르고 있으면 더 높이). 공중에서: <kbd>←</kbd> 킥플립, <kbd>→</kbd> 힐플립, <kbd>↑</kbd> 360 스핀, <kbd>↓</kbd>를 누르고 있으면 그랩(또는 스와이프한 채로 유지). 땅에서는 <kbd>←</kbd> <kbd>→</kbd>로 속도 조절, 레일 위에서는 균형 잡기. <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "모은 별" },
    ja: { title: "スケートラッシュ", desc: "校庭、ビーチの遊歩道、ネオンの街、屋上で、オーリー、キックフリップ、グラブ、グラインド！トリックをつなげて大コンボ、ラジコンカーやカニをとびこえ、パワーアップバブルをゲットして、SPECIALメーターをためれば得点2倍。そしてフリースケート：新しいコースで60秒以内に記録を出そう。", controls: "<kbd>Space</kbd> かタップでオーリー（長押しでもっと高く）。空中で：<kbd>←</kbd> キックフリップ、<kbd>→</kbd> ヒールフリップ、<kbd>↑</kbd> 360スピン、<kbd>↓</kbd> 長押しでグラブ（またはスワイプしてそのまま）。地面では <kbd>←</kbd> <kbd>→</kbd> でスピード調整、レールの上ではバランスをとる。<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "獲得スター" },
    zh: { title: "滑板冲冲冲", desc: "在校园、海滨木栈道、霓虹街道和楼顶上豚跳、尖翻、抓板、磨杆！把招式连成超长连击，跳过遥控车和螃蟹，抓住道具泡泡，攒满必杀槽双倍得分。再试试自由滑：全新赛道，60 秒内创下纪录！", controls: "<kbd>Space</kbd> 或轻触来豚跳（按住跳得更高）。空中时：<kbd>←</kbd> 尖翻，<kbd>→</kbd> 跟翻，<kbd>↑</kbd> 360 转体，按住 <kbd>↓</kbd> 抓板（或滑动后按住）。地面上 <kbd>←</kbd> <kbd>→</kbd> 调整速度，在杆上则用来保持平衡。<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "获得星星" },
    es: { title: "Skate a Tope", desc: "¡Haz ollies, kickflips, grabs y grinds por patios de colegio, paseos marítimos, calles de neón y azoteas! Encadena trucos en combos gigantes, salta sobre coches teledirigidos y cangrejos, coge burbujas de potenciadores y llena tu medidor ESPECIAL para puntos dobles. Luego prueba Skate Libre: una pista nueva y 60 segundos para batir un récord.", controls: "<kbd>Space</kbd> o toca para hacer un ollie (mantén para subir más). En el aire: <kbd>←</kbd> kickflip, <kbd>→</kbd> heelflip, <kbd>↑</kbd> giro 360, mantén <kbd>↓</kbd> para un grab (o desliza y mantén). En el suelo, <kbd>←</kbd> <kbd>→</kbd> cambian la velocidad; en las barandillas te mantienen en equilibrio. <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Estrellas ganadas" },
    fr: { title: "Fonce en Skate", desc: "Ollie, kickflip, grab et grind dans les cours d'école, sur les promenades de plage, dans les rues néon et sur les toits ! Enchaîne les figures en combos géants, saute par-dessus les voitures télécommandées et les crabes, attrape des bulles bonus et remplis ta jauge SPÉCIAL pour doubler tes points. Puis essaie le Skate libre : une toute nouvelle piste et 60 secondes pour battre un record.", controls: "<kbd>Space</kbd> ou touche pour un ollie (maintiens pour aller plus haut). En l'air : <kbd>←</kbd> kickflip, <kbd>→</kbd> heelflip, <kbd>↑</kbd> 360, maintiens <kbd>↓</kbd> pour un grab (ou glisse et maintiens). Au sol, <kbd>←</kbd> <kbd>→</kbd> changent la vitesse ; sur les rails, ils gardent ton équilibre. <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Étoiles gagnées" },
    de: { title: "Skate-Action", desc: "Ollie, Kickflip, Grab und Grind über Schulhöfe, Strandpromenaden, Neonstraßen und Dächer! Verkette Tricks zu riesigen Combos, spring über RC-Autos und Krabben, schnapp dir Power-up-Blasen und füll deine SPECIAL-Leiste für doppelte Punkte. Dann probier Free Skate: eine brandneue Strecke und 60 Sekunden für einen Rekord.", controls: "<kbd>Space</kbd> oder tippen für einen Ollie (halten für mehr Höhe). In der Luft: <kbd>←</kbd> Kickflip, <kbd>→</kbd> Heelflip, <kbd>↑</kbd> 360er, <kbd>↓</kbd> halten für einen Grab (oder wischen und halten). Am Boden ändern <kbd>←</kbd> <kbd>→</kbd> das Tempo, auf Rails halten sie dein Gleichgewicht. <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Gesammelte Sterne" },
    pt: { title: "Skate Radical", desc: "Ollie, kickflip, grab e grind por pátios de escola, calçadões de praia, ruas de neon e telhados! Junte manobras em combos gigantes, pule carrinhos de controle remoto e caranguejos, pegue bolhas de poder e encha sua barra ESPECIAL para pontos em dobro. Depois tente o Skate Livre: uma pista novinha e 60 segundos para bater um recorde.", controls: "<kbd>Space</kbd> ou toque para dar um ollie (segure para ir mais alto). No ar: <kbd>←</kbd> kickflip, <kbd>→</kbd> heelflip, <kbd>↑</kbd> giro 360, segure <kbd>↓</kbd> para um grab (ou deslize e segure). No chão, <kbd>←</kbd> <kbd>→</kbd> mudam a velocidade; nos corrimãos, mantêm o equilíbrio. <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Estrelas ganhas" },
  },
  idlekingdom: {
    ko: { title: "느긋한 왕국", desc: "성을 톡톡 눌러 골드를 모으고, 농장, 빵집, 마법사 탑, 드래곤 둥지로 왕국을 키워요. 내가 없을 때도 왕국은 계속 돈을 벌어요! 왕실 퀘스트를 완료하고, 밀밭의 까마귀를 쫓아내고, 수확 축제 같은 왕실 파워를 터뜨리세요. 새 시대를 열면 왕관을 받아서 모든 게 영원히 빨라져요!", controls: "성을 클릭하거나 탭하면(또는 <kbd>Space</kbd>) 골드를 받아요. 빠르게 탭하면 콤보! 패널에서 건물을 짓고 업그레이드해요. <kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> 왕실 파워, <kbd>G</kbd> 황금 거위 잡기, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "번 골드" },
    ja: { title: "のんびり王国", desc: "お城をタップしてゴールドを集め、畑、パン屋、魔法使いの塔、ドラゴンの巣で王国を大きくしよう。留守のあいだもかせぎ続けるよ！ロイヤルクエストを達成して、小麦畑のカラスを追いはらい、収穫祭などのロイヤルパワーを発動。新しい時代を始めると王冠がもらえて、ずっと全部が速くなるよ！", controls: "お城をクリックかタップ（または <kbd>Space</kbd>）でゴールド。すばやくタップでコンボ！パネルで建てたり強化したりしよう。<kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> ロイヤルパワー、<kbd>G</kbd> 金のガチョウをつかまえる、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "稼いだゴールド" },
    zh: { title: "放置王国", desc: "点点城堡赚金子，建起农场、面包房、巫师塔和龙巢，打造一个你不在时也会一直赚钱的王国！完成皇家任务，赶走麦田里的乌鸦，释放丰收节等皇家能力。开启新纪元赚取王冠，让一切永远变得更快！", controls: "点击或轻触城堡（或按 <kbd>Space</kbd>）赚金子。快速连点打出连击！用面板建造和升级。<kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> 皇家能力，<kbd>G</kbd> 抓住金鹅，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "赚到的金子" },
    es: { title: "Reino sin Prisa", desc: "¡Toca tu castillo para ganar oro y construye un reino de granjas, panaderías, torres de magos y nidos de dragón que sigue ganando aunque no estés! Completa Misiones Reales, espanta a los cuervos de tu trigo y desata Poderes Reales como el Festival de la Cosecha. ¡Empieza una Nueva Era para ganar coronas que lo aceleran todo para siempre!", controls: "Haz clic o toca el castillo (o pulsa <kbd>Space</kbd>) para ganar oro. ¡Toca rápido para un combo! Usa el panel para construir y mejorar. <kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> Poderes Reales, <kbd>G</kbd> atrapar la oca dorada, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Oro ganado" },
    fr: { title: "Royaume Tranquille", desc: "Touche ton château pour gagner de l'or et bâtis un royaume de fermes, de boulangeries, de tours de sorciers et de nids de dragons qui continue de rapporter même quand tu n'es pas là ! Termine des Quêtes royales, chasse les corbeaux de ton blé et déchaîne des Pouvoirs royaux comme la Fête des moissons. Lance une Nouvelle Ère pour gagner des couronnes qui accélèrent tout pour toujours !", controls: "Clique ou touche le château (ou appuie sur <kbd>Space</kbd>) pour de l'or. Tape vite pour un combo ! Utilise le panneau pour construire et améliorer. <kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> Pouvoirs royaux, <kbd>G</kbd> attraper l'oie dorée, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Or gagné" },
    de: { title: "Faulenzer-Königreich", desc: "Tipp auf deine Burg für Gold und bau ein Königreich aus Höfen, Bäckereien, Zaubertürmen und Drachenhorsten, das sogar weiterverdient, wenn du weg bist! Erledige königliche Quests, verscheuch die Krähen von deinem Weizen und entfessle königliche Kräfte wie das Erntefest. Starte ein neues Zeitalter und verdien Kronen, die alles für immer schneller machen!", controls: "Klicke oder tippe auf die Burg (oder drück <kbd>Space</kbd>) für Gold. Tipp schnell für eine Combo! Im Menü baust und verbesserst du. <kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> königliche Kräfte, <kbd>G</kbd> goldene Gans fangen, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Verdientes Gold" },
    pt: { title: "Reino Ocioso", desc: "Toque no seu castelo para ganhar ouro e construa um reino de fazendas, padarias, torres de magos e ninhos de dragão que continua rendendo mesmo quando você sai! Cumpra Missões Reais, espante os corvos do seu trigo e solte Poderes Reais como o Festival da Colheita. Comece uma Nova Era para ganhar coroas que deixam tudo mais rápido para sempre!", controls: "Clique ou toque no castelo (ou aperte <kbd>Space</kbd>) para ganhar ouro. Toque rápido para fazer combo! Use o painel para construir e melhorar. <kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> Poderes Reais, <kbd>G</kbd> pegar o ganso dourado, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Ouro ganho" },
  },
  toothpaste: {
    ko: { title: "치약 프로", desc: "욕실 컨베이어 벨트 위로 칫솔들이 쌩쌩 지나가요! 꾹 눌러서 반들반들한 치약 튜브를 짜고, 딱 맞는 순간에 손을 떼서 칫솔모 위에 완벽한 치약 줄을 올려 보세요. 욕실 네 곳의 25개 레벨에서 흔들리는 칫솔, 거대 칫솔, 양면 칫솔, 전동 칫솔을 만나고, 치과 러시에서 플라크 대장을 물리치고, 코인으로 새 튜브, 맛, 칫솔을 사요.", controls: "마우스, 손가락 또는 <kbd>Space</kbd>를 누르고 있으면 짜고, 놓으면 멈춰요. <kbd>R</kbd> 튜브 다시 채우기, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거.", label: "모은 별" },
    ja: { title: "ハミガキプロ", desc: "おふろ場のベルトコンベアを歯ブラシがビュンビュン流れてくる！長押しでツヤツヤのチューブをしぼって、ぴったりのタイミングではなし、ブラシの上にパーフェクトな歯みがき粉をのせよう。4つのおふろ場の25レベルで、ぐらぐら、巨大、両面、電動の歯ブラシが登場。デンティストラッシュでキャプテン・プラークをたおし、コインで新しいチューブ、味、歯ブラシを買おう。", controls: "マウス、指、または <kbd>Space</kbd> を長押しでしぼり、はなすと止まる。<kbd>R</kbd> チューブを補充、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート。", label: "獲得スター" },
    zh: { title: "牙膏大师", desc: "浴室传送带上，一支支牙刷飞驰而过！按住挤压亮晶晶的牙膏管，在刚刚好的时刻松手，在刷毛上挤出一条完美的牙膏。在四间浴室的 25 个关卡里挑战摇摇晃晃的、巨大的、双面的和电动的牙刷，在牙医冲刺中打败牙菌斑船长，再用金币买新的牙膏管、口味和牙刷。", controls: "按住鼠标、手指或 <kbd>Space</kbd> 挤牙膏，松开就停。<kbd>R</kbd> 补满牙膏管，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音。", label: "获得星星" },
    es: { title: "Pasta de Dientes Pro", desc: "¡Los cepillos de dientes pasan zumbando por una cinta transportadora del baño! Mantén pulsado para apretar el tubo brillante y suelta justo a tiempo para dejar una tira perfecta de pasta sobre las cerdas. Juega 25 niveles en cuatro baños con cepillos tambaleantes, gigantes, de doble cara y eléctricos, vence al Capitán Placa en la Fiebre del Dentista y gasta tus monedas en tubos, sabores y cepillos nuevos.", controls: "Mantén el ratón, un dedo o <kbd>Space</kbd> para apretar y suelta para parar. <kbd>R</kbd> rellena el tubo, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar.", label: "Estrellas ganadas" },
    fr: { title: "Dentifrice Pro", desc: "Des brosses à dents filent sur un tapis roulant de salle de bain ! Maintiens pour presser le tube brillant et relâche pile au bon moment pour déposer une bande de dentifrice parfaite sur les poils. Joue 25 niveaux dans quatre salles de bain avec des brosses branlantes, géantes, double face et électriques, bats le Capitaine Plaque dans la Ruée chez le dentiste et dépense tes pièces en nouveaux tubes, parfums et brosses.", controls: "Maintiens la souris, un doigt ou <kbd>Space</kbd> pour presser, et relâche pour arrêter. <kbd>R</kbd> recharge le tube, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son.", label: "Étoiles gagnées" },
    de: { title: "Zahnpasta-Profi", desc: "Zahnbürsten sausen auf einem Badezimmer-Fließband vorbei! Halte gedrückt, um die glänzende Tube zu drücken, und lass genau im richtigen Moment los, damit ein perfekter Pastastreifen auf den Borsten landet. Spiel 25 Level in vier Badezimmern mit wackeligen, riesigen, doppelseitigen und elektrischen Bürsten, besiege Kapitän Plaque im Zahnarzt-Ansturm und gib deine Münzen für neue Tuben, Geschmacksrichtungen und Bürsten aus.", controls: "Halte die Maus, einen Finger oder <kbd>Space</kbd> zum Drücken, lass los zum Stoppen. <kbd>R</kbd> füllt die Tube nach, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus.", label: "Gesammelte Sterne" },
    pt: { title: "Pasta de Dente Pro", desc: "Escovas de dente passam voando numa esteira do banheiro! Segure para apertar o tubo brilhante e solte na hora certinha para deixar uma faixa perfeita de pasta nas cerdas. Jogue 25 fases em quatro banheiros com escovas bambas, gigantes, de dois lados e elétricas, vença o Capitão Placa na Correria do Dentista e gaste suas moedas em novos tubos, sabores e escovas.", controls: "Segure o mouse, um dedo ou <kbd>Space</kbd> para apertar e solte para parar. <kbd>R</kbd> reabastece o tubo, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo.", label: "Estrelas ganhas" },
  },
  skystack: {
    ko: { title: "하늘까지 쌓기", desc: "흔들리는 블록을 톡 떨어뜨려 세상에서 제일 높은 탑을 쌓아요! 퍼펙트로 쌓아 콤보를 잇고, 블록 크기를 되살리고, 피버를 터뜨리세요. 새를 피하고, 바람과 웃긴 보스 넷을 이겨 내며 구름 위를 지나 우주까지 올라가요.", controls: "탭, 클릭 또는 <kbd>Space</kbd>로 떨어뜨리기. <kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> 부스트 사용. <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "가장 높은 탑" },
    ja: { title: "スカイスタック", desc: "ゆれるブロックをタップで落として、史上最高のタワーを建てよう！パーフェクトに乗せてコンボをつなぎ、ブロックの大きさを取りもどして、フィーバー発動！鳥をよけ、風と4体のヘンテコなボスに勝って、雲をつきぬけ宇宙まで行こう。", controls: "タップ、クリック、または <kbd>Space</kbd> で落とす。<kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> ブーストを使う。<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "最高のタワー" },
    zh: { title: "天空叠叠乐", desc: "轻点放下摇摆的方块，盖出史上最高的塔！完美落下就能连击，让方块恢复原来的大小，还能触发狂热模式。躲开小鸟，战胜大风和四个搞笑Boss，一路穿过云层，冲进外太空！", controls: "轻点、点击或按 <kbd>Space</kbd> 放下方块。<kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> 使用加成。<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "最高的塔" },
    es: { title: "Torre al Cielo", desc: "¡Toca para soltar cada bloque que se balancea y construye la torre más alta del mundo! Consigue caídas perfectas para encadenar combos, recuperar el tamaño de tus bloques y activar la Fiebre. Esquiva pájaros y vence al viento y a cuatro jefes chiflados mientras subes por encima de las nubes hasta el espacio.", controls: "Toca, haz clic o pulsa <kbd>Space</kbd> para soltar. <kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> usan potenciadores. <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Torre más alta" },
    fr: { title: "Tour jusqu'au Ciel", desc: "Touche pour lâcher chaque bloc qui se balance et construis la tour la plus haute de tous les temps ! Réussis des poses parfaites pour enchaîner les combos, faire regrandir tes blocs et déclencher la Fièvre. Évite les oiseaux, résiste au vent et bats quatre boss rigolos en montant au-dessus des nuages jusque dans l'espace.", controls: "Touche, clique ou appuie sur <kbd>Space</kbd> pour lâcher. <kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> utilisent les bonus. <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Plus haute tour" },
    de: { title: "Himmelsturm", desc: "Tipp, um jeden schwingenden Block fallen zu lassen, und bau den höchsten Turm aller Zeiten! Perfekte Landungen bringen Combos, lassen deine Blöcke wieder wachsen und lösen das Fieber aus. Weich Vögeln aus, trotz dem Wind und besiege vier alberne Bosse auf deinem Weg über die Wolken bis ins Weltall.", controls: "Tippe, klicke oder drück <kbd>Space</kbd> zum Fallenlassen. <kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> für Boosts. <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Höchster Turm" },
    pt: { title: "Torre até o Céu", desc: "Toque para soltar cada bloco balançando e construa a torre mais alta de todas! Acerte encaixes perfeitos para fazer combos, recuperar o tamanho dos blocos e ativar a Febre. Desvie dos pássaros, vença o vento e quatro chefões malucos no caminho para além das nuvens até o espaço sideral.", controls: "Toque, clique ou aperte <kbd>Space</kbd> para soltar. <kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> usam reforços. <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Torre mais alta" },
  },
  bullseye: {
    ko: { title: "정중앙 명중", desc: "활시위를 당기고, 바람을 읽고, 숨을 참고 완벽한 한 발을 쏘세요! 토너먼트 세 개에서 라이벌 궁수 12명을 이기고, 링과 벽을 넘기는 트릭 샷 24개를 성공시키고, 풍선 블리츠에서 풍선을 터뜨려요. 새 활, 화살, 옷도 열 수 있어요.", controls: "뒤로 끌었다가 놓으면 발사(또는 <kbd>↑</kbd> <kbd>↓</kbd>로 조준하고 <kbd>Space</kbd>를 누르고 있기). <kbd>Shift</kbd>나 폐 버튼을 누르고 있으면 숨 참기. <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "최고 점수" },
    ja: { title: "ど真ん中！", desc: "弓を引いて、風を読んで、息を止めてパーフェクトな一発を！3つの大会でライバル弓使い12人に勝ち、輪っかをくぐったりかべをこえたりする24のトリックショットを決めて、バルーンブリッツで風船をわろう。新しい弓、矢、衣装も解放できるよ。", controls: "後ろにドラッグしてはなすと発射（または <kbd>↑</kbd> <kbd>↓</kbd> でねらって <kbd>Space</kbd> 長押し）。<kbd>Shift</kbd> か肺のボタンを長押しで息を止める。<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "ベストスコア" },
    zh: { title: "正中靶心", desc: "拉开弓弦，判断风向，屏住呼吸射出完美一箭！在三场锦标赛中击败 12 位对手弓箭手，完成 24 个穿圈越墙的花式射击，还能在气球闪击战里射爆气球。解锁新的弓、箭和服装！", controls: "往后拖再松手就能射击（或用 <kbd>↑</kbd> <kbd>↓</kbd> 瞄准，按住 <kbd>Space</kbd>）。按住 <kbd>Shift</kbd> 或肺部按钮屏住呼吸。<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "最高分" },
    es: { title: "¡En el Blanco!", desc: "¡Tensa tu arco, lee el viento y contén la respiración para el tiro perfecto! Vence a 12 arqueros rivales en tres torneos, logra 24 tiros de fantasía a través de aros y por encima de muros, y explota globos en Globos Blitz. Desbloquea arcos, flechas y trajes nuevos.", controls: "Arrastra hacia atrás y suelta para disparar (o apunta con <kbd>↑</kbd> <kbd>↓</kbd> y mantén <kbd>Space</kbd>). Mantén <kbd>Shift</kbd> o el botón de los pulmones para contener la respiración. <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Mejor puntuación" },
    fr: { title: "En Plein Mille", desc: "Bande ton arc, lis le vent et retiens ton souffle pour le tir parfait ! Bats 12 archers rivaux dans trois tournois, réussis 24 tirs acrobatiques à travers des cerceaux et par-dessus des murs, et éclate des ballons dans Ballons Blitz. Débloque de nouveaux arcs, flèches et tenues.", controls: "Tire en arrière et relâche pour tirer (ou vise avec <kbd>↑</kbd> <kbd>↓</kbd> et maintiens <kbd>Space</kbd>). Maintiens <kbd>Shift</kbd> ou le bouton poumons pour retenir ton souffle. <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Meilleur score" },
    de: { title: "Volltreffer", desc: "Spann deinen Bogen, lies den Wind und halt die Luft an für den perfekten Schuss! Besiege 12 rivalisierende Bogenschützen in drei Turnieren, schaff 24 Trickschüsse durch Ringe und über Mauern und lass Ballons platzen im Ballon-Blitz. Schalte neue Bögen, Pfeile und Outfits frei.", controls: "Zieh nach hinten und lass los zum Schießen (oder ziel mit <kbd>↑</kbd> <kbd>↓</kbd> und halte <kbd>Space</kbd>). Halte <kbd>Shift</kbd> oder den Lungen-Button, um die Luft anzuhalten. <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Beste Punktzahl" },
    pt: { title: "Na Mosca!", desc: "Puxe o arco, leia o vento e prenda a respiração para o tiro perfeito! Vença 12 arqueiros rivais em três torneios, acerte 24 tiros de efeito por dentro de aros e por cima de muros, e estoure balões no Balões Blitz. Libere novos arcos, flechas e roupas.", controls: "Arraste para trás e solte para atirar (ou mire com <kbd>↑</kbd> <kbd>↓</kbd> e segure <kbd>Space</kbd>). Segure <kbd>Shift</kbd> ou o botão do pulmão para prender a respiração. <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Melhor pontuação" },
  },
  pinballparty: {
    ko: { title: "핀볼 파티", desc: "보물 해안, 스타 보이저, 슈거 러시까지 테마가 다른 핀볼 테이블 세 곳에서 플리퍼를 치고, 흔들고, 공을 발사해요! 락을 켜서 멀티볼을 터뜨리고, 미션을 끝내 파티 모드를 시작하고, 잭팟을 노리세요. 별을 모아 새 테이블과 반짝이는 새 공을 열어요.", controls: "플리퍼: <kbd>←</kbd> <kbd>→</kbd> 또는 <kbd>Z</kbd> <kbd>/</kbd>, 또는 화면 왼쪽/오른쪽을 탭. <kbd>↓</kbd>나 <kbd>Space</kbd>를 누르고 있다가 놓으면 발사. <kbd>N</kbd> 테이블 흔들기, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "최고 점수" },
    ja: { title: "ピンボールパーティー", desc: "トレジャーコーブ、スターボイジャー、シュガーラッシュ、3つのテーマのピンボール台でフリップ、ナッジ、発射！ロックを点灯してマルチボール、ミッションをクリアしてパーティーモードを始め、ジャックポットをねらおう。スターを集めて新しい台とピカピカの新しいボールを解放しよう。", controls: "フリッパー：<kbd>←</kbd> <kbd>→</kbd> または <kbd>Z</kbd> <kbd>/</kbd>、または画面の左/右をタップ。<kbd>↓</kbd> か <kbd>Space</kbd> 長押しで発射。<kbd>N</kbd> ナッジ、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "ハイスコア" },
    zh: { title: "弹珠台派对", desc: "在宝藏湾、星际航行者和糖果狂欢三张主题弹珠台上挥板、推台、发射！点亮锁定开启多球，完成任务进入派对模式，冲击超级大奖。收集星星解锁新的球台和亮闪闪的新弹珠！", controls: "挡板：<kbd>←</kbd> <kbd>→</kbd> 或 <kbd>Z</kbd> <kbd>/</kbd>，或轻触屏幕左/右侧。按住 <kbd>↓</kbd> 或 <kbd>Space</kbd> 发射。<kbd>N</kbd> 推台，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "最高分" },
    es: { title: "Fiesta de Pinball", desc: "¡Dale a los flippers, sacude y lanza la bola en tres mesas de pinball temáticas: Cala del Tesoro, Viajero Estelar y Fiebre de Azúcar! Enciende el bloqueo para la multibola, completa misiones para empezar el Modo Fiesta y persigue el bote. Gana estrellas para desbloquear mesas nuevas y bolas relucientes.", controls: "Flippers: <kbd>←</kbd> <kbd>→</kbd> o <kbd>Z</kbd> <kbd>/</kbd>, o toca el lado izquierdo/derecho. Mantén <kbd>↓</kbd> o <kbd>Space</kbd> para lanzar. <kbd>N</kbd> sacudir, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Récord" },
    fr: { title: "Fête du Flipper", desc: "Actionne les flips, secoue la table et lance la bille sur trois flippers à thème : la Crique au Trésor, Star Voyager et Sucre Folie ! Allume le verrou pour le multibille, termine des missions pour lancer le Mode Fête et vise le jackpot. Gagne des étoiles pour débloquer de nouvelles tables et des billes toutes neuves.", controls: "Flips : <kbd>←</kbd> <kbd>→</kbd> ou <kbd>Z</kbd> <kbd>/</kbd>, ou touche le côté gauche/droit. Maintiens <kbd>↓</kbd> ou <kbd>Space</kbd> pour lancer. <kbd>N</kbd> secouer, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Record" },
    de: { title: "Flipper-Party", desc: "Flippe, rüttle und schieß die Kugel auf drei Themen-Flippertischen ab: Schatzbucht, Sternenreisender und Zuckerrausch! Aktiviere das Lock für Multiball, schaff Missionen, um den Party-Modus zu starten, und jag den Jackpot. Sammle Sterne, um neue Tische und glänzende neue Kugeln freizuschalten.", controls: "Flipper: <kbd>←</kbd> <kbd>→</kbd> oder <kbd>Z</kbd> <kbd>/</kbd>, oder tippe links/rechts. Halte <kbd>↓</kbd> oder <kbd>Space</kbd> zum Abschießen. <kbd>N</kbd> rütteln, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Highscore" },
    pt: { title: "Festa do Pinball", desc: "Bata, balance e lance a bola em três mesas de pinball temáticas: Enseada do Tesouro, Viajante Estelar e Febre do Açúcar! Acenda a trava para a multibola, complete missões para começar o Modo Festa e corra atrás do jackpot. Ganhe estrelas para liberar mesas novas e bolinhas brilhantes.", controls: "Palhetas: <kbd>←</kbd> <kbd>→</kbd> ou <kbd>Z</kbd> <kbd>/</kbd>, ou toque no lado esquerdo/direito. Segure <kbd>↓</kbd> ou <kbd>Space</kbd> para lançar. <kbd>N</kbd> balançar, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Recorde" },
  },
  boardbuddies: {
    ko: { title: "보드게임 친구들", desc: "체커, 사목, 리버시, 틱택토, 얼티밋 틱택토를 귀여운 동물 친구 15명과 쉬움, 보통, 어려움으로 즐겨요! 트로피 사다리를 올라 챔피언 레오와 맞붙고, 한 화면에서 친구와 대결하고, 재미있는 보드와 말을 열어 보세요.", controls: "클릭하거나 탭해서 둬요(체커는 말을 클릭한 다음 갈 곳을 클릭). <kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> 이동, <kbd>Enter</kbd> 놓기, 사목에서는 <kbd>1</kbd>–<kbd>7</kbd>로 떨어뜨리기, <kbd>H</kbd> 힌트, <kbd>U</kbd> 무르기, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거.", label: "사다리 별" },
    ja: { title: "ボードゲームなかま", desc: "チェッカー、四目ならべ、リバーシ、まるばつ、アルティメットまるばつを、かわいい動物なかま15人とかんたん、ふつう、むずかしいで遊ぼう！トロフィーラダーをのぼってチャンピオンのレオと対決、同じ画面で友だちとも遊べて、楽しいボードやコマも解放できるよ。", controls: "クリックかタップで打つ（チェッカーはコマをクリックしてから行き先をクリック）。<kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> 移動、<kbd>Enter</kbd> 置く、四目ならべでは <kbd>1</kbd>–<kbd>7</kbd> で落とす、<kbd>H</kbd> ヒント、<kbd>U</kbd> 待った、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート。", label: "ラダーのスター" },
    zh: { title: "棋盘好伙伴", desc: "和 15 位可爱的动物伙伴玩跳棋、四子棋、黑白棋、井字棋和终极井字棋，有简单、中等、困难三种难度！爬上奖杯天梯挑战冠军狮子里奥，在同一块屏幕上和朋友对战，还能解锁好玩的棋盘和棋子。", controls: "点击或轻触落子（跳棋先点棋子，再点要去的位置）。<kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> 移动，<kbd>Enter</kbd> 落子，四子棋用 <kbd>1</kbd>–<kbd>7</kbd> 投子，<kbd>H</kbd> 提示，<kbd>U</kbd> 悔棋，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音。", label: "天梯星星" },
    es: { title: "Amigos de Tablero", desc: "¡Juega a las Damas, Cuatro en Raya, Reversi, Tres en Raya y Tres en Raya Definitivo contra 15 animalitos adorables en Fácil, Medio y Difícil! Sube la Escalera de Trofeos hasta enfrentarte a Leo el Campeón, juega con un amigo en la misma pantalla y desbloquea tableros y fichas divertidos.", controls: "Haz clic o toca para jugar (en las Damas, haz clic en una ficha y luego adonde va). <kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> mover, <kbd>Enter</kbd> colocar, <kbd>1</kbd>–<kbd>7</kbd> soltar en Cuatro en Raya, <kbd>H</kbd> pista, <kbd>U</kbd> deshacer, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar.", label: "Estrellas de la escalera" },
    fr: { title: "Copains de Plateau", desc: "Joue aux Dames, au Puissance 4, à Reversi, au Morpion et au Morpion Ultime contre 15 adorables copains animaux en Facile, Moyen et Difficile ! Grimpe l'Échelle des trophées pour affronter Léo le Champion, joue avec un ami sur le même écran et débloque des plateaux et des pions rigolos.", controls: "Clique ou touche pour jouer (aux Dames, clique sur un pion puis sur sa destination). <kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> déplacer, <kbd>Enter</kbd> placer, <kbd>1</kbd>–<kbd>7</kbd> lâcher un jeton au Puissance 4, <kbd>H</kbd> indice, <kbd>U</kbd> annuler, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son.", label: "Étoiles de l'échelle" },
    de: { title: "Brettspiel-Kumpel", desc: "Spiel Dame, Vier gewinnt, Reversi, Tic-Tac-Toe und Ultimate Tic-Tac-Toe gegen 15 süße Tierkumpel auf Leicht, Mittel und Schwer! Kletter die Pokal-Leiter hoch bis zu Champion Leo, spiel mit einem Freund am selben Bildschirm und schalte lustige Bretter und Spielsteine frei.", controls: "Klicke oder tippe zum Spielen (bei Dame erst einen Stein anklicken, dann das Ziel). <kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> bewegen, <kbd>Enter</kbd> setzen, <kbd>1</kbd>–<kbd>7</kbd> einwerfen bei Vier gewinnt, <kbd>H</kbd> Tipp, <kbd>U</kbd> rückgängig, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus.", label: "Leiter-Sterne" },
    pt: { title: "Amigos de Tabuleiro", desc: "Jogue Damas, Lig 4, Reversi, Jogo da Velha e Jogo da Velha Supremo contra 15 amiguinhos animais fofos no Fácil, Médio e Difícil! Suba a Escada de Troféus para enfrentar Leo, o Campeão, jogue com um amigo na mesma tela e libere tabuleiros e peças divertidos.", controls: "Clique ou toque para jogar (nas Damas, clique numa peça e depois para onde ela vai). <kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> mover, <kbd>Enter</kbd> colocar, <kbd>1</kbd>–<kbd>7</kbd> soltar no Lig 4, <kbd>H</kbd> dica, <kbd>U</kbd> desfazer, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo.", label: "Estrelas da escada" },
  },
  treasuresweeper: {
    ko: { title: "보물 찾기 대작전", desc: "햇살 가득한 섬에서 해적 보물을 파내요! 숫자는 바로 옆 칸에 숨은 장난꾸러기 게가 몇 마리인지 알려 줘요. 깃발을 꽂고, 앵무새 폴리의 나침반을 따라가며, 앵무새, 편지병, 김이 나는 화산이 있는 섬 지도 32개를 정복하세요. 느긋하게 즐기거나 보물 러시에서 시간과 경주해요.", controls: "클릭하거나 탭해서 파고, 오른쪽 클릭이나 길게 누르기(또는 깃발 도구)로 깃발 꽂기. 숫자를 클릭하면 주변을 한꺼번에 파요. <kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> 이동, <kbd>Space</kbd> 파기, <kbd>F</kbd> 깃발, <kbd>C</kbd> 나침반, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거.", label: "모은 별" },
    ja: { title: "トレジャースイーパー", desc: "日ざしいっぱいの島で海ぞくのお宝を掘りあてよう！数字はとなりにかくれているいたずらガニの数を教えてくれるよ。旗を立てて、オウムのポリーのコンパスをたどり、オウム、手紙入りのビン、湯気の立つ火山がある32の島マップをクリアしよう。のんびり遊ぶか、トレジャーラッシュで時間と勝負！", controls: "クリックかタップで掘る、右クリックか長押し（または旗ツール）で旗を立てる。数字をクリックするとまわりをまとめて掘るよ。<kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> 移動、<kbd>Space</kbd> 掘る、<kbd>F</kbd> 旗、<kbd>C</kbd> コンパス、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート。", label: "獲得スター" },
    zh: { title: "寻宝扫雷", desc: "在阳光明媚的小岛上挖掘海盗宝藏！数字会告诉你旁边藏着几只调皮的螃蟹，插上旗子，跟着鹦鹉波莉的指南针，完成 32 张有鹦鹉、漂流瓶和冒烟火山的海岛地图。可以悠闲地玩，也可以在寻宝冲刺里和时间赛跑！", controls: "点击或轻触挖掘，右键或长按（或旗子工具）插旗。点击数字可以挖开周围的格子。<kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> 移动，<kbd>Space</kbd> 挖掘，<kbd>F</kbd> 插旗，<kbd>C</kbd> 指南针，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音。", label: "获得星星" },
    es: { title: "Buscatesoros", desc: "¡Excava en busca del tesoro pirata en islas soleadas! Los números te dicen cuántos cangrejos traviesos se esconden al lado, así que pon banderas, sigue la brújula de Polly la lora y completa 32 mapas de islas con loros, botellas con mensaje y volcanes humeantes. Juega con calma o corre contra el reloj en Fiebre del Tesoro.", controls: "Haz clic o toca para excavar; clic derecho o mantener pulsado (o la herramienta bandera) para poner bandera. Haz clic en un número para excavar a su alrededor. <kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> mover, <kbd>Space</kbd> excavar, <kbd>F</kbd> bandera, <kbd>C</kbd> brújula, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar.", label: "Estrellas ganadas" },
    fr: { title: "Démineur au Trésor", desc: "Creuse pour trouver le trésor des pirates sur des îles ensoleillées ! Les chiffres te disent combien de crabes farceurs se cachent à côté : plante des drapeaux, suis la boussole de Polly le perroquet et termine 32 cartes d'îles avec perroquets, bouteilles à la mer et volcans fumants. Joue tranquille ou fais la course contre la montre dans la Ruée au trésor.", controls: "Clique ou touche pour creuser, clic droit ou appui long (ou l'outil drapeau) pour planter un drapeau. Clique sur un chiffre pour creuser autour. <kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> déplacer, <kbd>Space</kbd> creuser, <kbd>F</kbd> drapeau, <kbd>C</kbd> boussole, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son.", label: "Étoiles gagnées" },
    de: { title: "Schatzsucher", desc: "Grab auf sonnigen Inseln nach Piratenschätzen! Die Zahlen verraten dir, wie viele freche Krabben sich nebenan verstecken. Steck Fahnen, folge dem Kompass von Papagei Polly und schaff 32 Inselkarten mit Papageien, Flaschenpost und dampfenden Vulkanen. Spiel ganz entspannt oder renn im Schatz-Rausch gegen die Uhr.", controls: "Klicke oder tippe zum Graben, Rechtsklick oder lang drücken (oder das Fahnen-Werkzeug) zum Markieren. Klicke auf eine Zahl, um drumherum zu graben. <kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> bewegen, <kbd>Space</kbd> graben, <kbd>F</kbd> Fahne, <kbd>C</kbd> Kompass, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus.", label: "Gesammelte Sterne" },
    pt: { title: "Caça ao Tesouro", desc: "Cave atrás do tesouro pirata em ilhas ensolaradas! Os números mostram quantos caranguejos espertinhos estão escondidos ao lado, então finque bandeiras, siga a bússola da papagaia Polly e complete 32 mapas de ilhas com papagaios, garrafas com mensagem e vulcões fumegantes. Jogue com calma ou corra contra o relógio na Corrida do Tesouro.", controls: "Clique ou toque para cavar; clique direito ou toque longo (ou a ferramenta de bandeira) para marcar. Clique num número para cavar em volta dele. <kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> mover, <kbd>Space</kbd> cavar, <kbd>F</kbd> bandeira, <kbd>C</kbd> bússola, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo.", label: "Estrelas ganhas" },
  },
  picturecross: {
    ko: { title: "그림 로직", desc: "숫자 힌트를 보고 알맞은 칸을 칠해서 알록달록한 픽셀 그림을 완성해요! 작은 5x5부터 큰 15x15까지 손으로 만든 퍼즐 62개를 풀어 보세요. 힌트, 실수해도 괜찮은 어린이 모드, 완성한 그림을 모두 모아 두는 앨범도 있어요.", controls: "클릭하거나 끌어서 칸 칠하기, 오른쪽 클릭(또는 X 도구)으로 X 표시. <kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> 이동, <kbd>Space</kbd> 칠하기, <kbd>X</kbd> X 표시, <kbd>H</kbd> 힌트, <kbd>Z</kbd> 되돌리기, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거.", label: "모은 별" },
    ja: { title: "お絵かきロジック", desc: "数字のヒントを見て正しいマスをぬりつぶし、カラフルなドット絵を完成させよう！小さな5x5から大きな15x15まで、手作りパズルが62問。ヒント、まちがえても大丈夫なキッズモード、完成した絵が全部並ぶアルバムもあるよ。", controls: "クリックかドラッグでマスをぬる、右クリック（またはバツツール）でバツをつける。<kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> 移動、<kbd>Space</kbd> ぬる、<kbd>X</kbd> バツ、<kbd>H</kbd> ヒント、<kbd>Z</kbd> 取り消し、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート。", label: "獲得スター" },
    zh: { title: "数字填色画", desc: "根据数字线索涂满正确的格子，揭开一幅彩色像素画！62 道手工设计的谜题，从迷你的 5x5 到大大的 15x15，还有提示、不怕出错的儿童模式，以及收藏你完成的每幅画的相册。", controls: "点击或拖动涂格子，右键（或叉号工具）打叉。<kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> 移动，<kbd>Space</kbd> 涂色，<kbd>X</kbd> 打叉，<kbd>H</kbd> 提示，<kbd>Z</kbd> 撤销，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音。", label: "获得星星" },
    es: { title: "Dibujo Secreto", desc: "¡Usa las pistas numéricas para rellenar las casillas correctas y descubrir un colorido dibujo de píxeles! Resuelve 62 puzles hechos a mano, desde cuadrículas pequeñitas de 5x5 hasta grandes dibujos de 15x15, con pistas, un modo Niños que perdona los errores y un álbum con cada dibujo que terminas.", controls: "Haz clic o arrastra para rellenar casillas; clic derecho (o la herramienta cruz) para tacharlas. <kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> mover, <kbd>Space</kbd> rellenar, <kbd>X</kbd> tachar, <kbd>H</kbd> pista, <kbd>Z</kbd> deshacer, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar.", label: "Estrellas ganadas" },
    fr: { title: "Image Mystère", desc: "Utilise les indices chiffrés pour colorier les bonnes cases et révéler une image en pixels toute colorée ! Résous 62 énigmes faites main, des toutes petites grilles 5x5 aux grandes images 15x15, avec des indices, un mode Enfant qui pardonne les erreurs et un album de toutes les images terminées.", controls: "Clique ou glisse pour remplir les cases, clic droit (ou l'outil croix) pour les barrer. <kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> déplacer, <kbd>Space</kbd> remplir, <kbd>X</kbd> barrer, <kbd>H</kbd> indice, <kbd>Z</kbd> annuler, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son.", label: "Étoiles gagnées" },
    de: { title: "Bilderrätsel", desc: "Nutze die Zahlenhinweise, um die richtigen Kästchen auszumalen und ein buntes Pixelbild aufzudecken! Löse 62 handgemachte Rätsel von winzigen 5x5-Gittern bis zu großen 15x15-Bildern, mit Tipps, einem fehlerverzeihenden Kindermodus und einem Album mit jedem fertigen Bild.", controls: "Klicke oder zieh zum Ausmalen, Rechtsklick (oder das Kreuz-Werkzeug) zum Durchstreichen. <kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> bewegen, <kbd>Space</kbd> ausmalen, <kbd>X</kbd> Kreuz, <kbd>H</kbd> Tipp, <kbd>Z</kbd> rückgängig, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus.", label: "Gesammelte Sterne" },
    pt: { title: "Desenho Secreto", desc: "Use as pistas de números para pintar os quadradinhos certos e revelar um desenho colorido em pixels! Resolva 62 quebra-cabeças feitos à mão, de grades pequeninas de 5x5 a desenhos grandes de 15x15, com dicas, um modo Criança que perdoa erros e um álbum com cada desenho que você terminar.", controls: "Clique ou arraste para pintar; clique direito (ou a ferramenta X) para marcar com X. <kbd>←</kbd> <kbd>→</kbd> <kbd>↑</kbd> <kbd>↓</kbd> mover, <kbd>Space</kbd> pintar, <kbd>X</kbd> marcar X, <kbd>H</kbd> dica, <kbd>Z</kbd> desfazer, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo.", label: "Estrelas ganhas" },
  },
  lemonadestand: {
    ko: { title: "레모네이드 가게", desc: "나만의 레모네이드 가게를 운영해요! 날씨를 확인하고, 레몬, 설탕, 얼음, 컵을 사고, 완벽한 레시피를 섞고, 가격을 정하세요. 그다음 손님들이 줄을 서서 맛 평가를 해 줘요. 새 음료를 열고, 가게를 업그레이드하고, 해변, 경기장, 놀이공원으로 옮겨 가요!", controls: "마우스나 탭으로 하루를 계획해요. 장사 중에는 가게를 클릭하거나 탭해서 더 빨리 따르고, 금화를 탭해서 팁을 받아요. <kbd>Space</kbd> 손님 부르기, <kbd>F</kbd> 빨리 감기, <kbd>Enter</kbd> 내주기, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "판 컵 수" },
    ja: { title: "レモネード屋さん", desc: "自分だけのレモネード屋さんを開こう！天気をチェックして、レモン、さとう、氷、カップを買い、最高のレシピをまぜて、値段を決めよう。お客さんが行列を作って感想を言ってくれるよ。新しいドリンクを解放して、お店をパワーアップ、ビーチ、スタジアム、遊園地へお引っこし！", controls: "マウスかタップで1日の計画を立てよう。営業中はお店をクリックかタップして速く注ぎ、金貨をタップしてチップをゲット。<kbd>Space</kbd> よびこみ、<kbd>F</kbd> 早送り、<kbd>Enter</kbd> 出す、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "売れたカップ" },
    zh: { title: "柠檬水小摊", desc: "经营你自己的柠檬水小摊！看看天气，买柠檬、糖、冰块和杯子，调出完美配方，定好价格，然后看着顾客排队并告诉你他们的感受。解锁新饮品，升级小摊，搬到海滩、体育场和游乐园去！", controls: "用鼠标或轻触来规划一天。营业时点击或轻触小摊倒得更快，点金币接小费。<kbd>Space</kbd> 吆喝，<kbd>F</kbd> 加速，<kbd>Enter</kbd> 上饮料，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "售出杯数" },
    es: { title: "Puesto de Limonada", desc: "¡Lleva tu propio puesto de limonada! Mira el tiempo, compra limones, azúcar, hielo y vasos, mezcla la receta perfecta y elige un precio; luego mira cómo los clientes hacen cola y te dicen qué les parece. ¡Desbloquea bebidas nuevas, mejora tu puesto y múdate a la playa, al estadio y a la feria!", controls: "Planea tu día con el ratón o tocando. Durante el día, haz clic o toca el puesto para servir más rápido y toca las monedas de oro para atrapar propinas. <kbd>Space</kbd> pregonar, <kbd>F</kbd> acelerar, <kbd>Enter</kbd> servir, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Vasos vendidos" },
    fr: { title: "Le Stand de Limonade", desc: "Tiens ton propre stand de limonade ! Regarde la météo, achète citrons, sucre, glaçons et gobelets, mélange la recette parfaite et fixe un prix, puis regarde les clients faire la queue et te dire ce qu'ils en pensent. Débloque de nouvelles boissons, améliore ton stand et installe-toi à la plage, au stade et à la fête foraine !", controls: "Prépare ta journée à la souris ou au doigt. Pendant la journée, clique ou touche le stand pour servir plus vite et touche les pièces d'or pour attraper les pourboires. <kbd>Space</kbd> crier, <kbd>F</kbd> accélérer, <kbd>Enter</kbd> servir, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Verres vendus" },
    de: { title: "Limonadenstand", desc: "Führe deinen eigenen Limonadenstand! Check das Wetter, kauf Zitronen, Zucker, Eis und Becher, misch das perfekte Rezept und leg einen Preis fest – dann stehen die Kunden Schlange und sagen dir, wie's schmeckt. Schalte neue Getränke frei, rüste deinen Stand auf und zieh an den Strand, ins Stadion und auf den Rummel!", controls: "Plan deinen Tag mit der Maus oder per Tippen. Tagsüber klickst oder tippst du auf den Stand, um schneller einzuschenken, und tippst Goldmünzen an, um Trinkgeld zu fangen. <kbd>Space</kbd> rufen, <kbd>F</kbd> vorspulen, <kbd>Enter</kbd> servieren, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Verkaufte Becher" },
    pt: { title: "Barraca de Limonada", desc: "Comande sua própria barraca de limonada! Veja a previsão do tempo, compre limões, açúcar, gelo e copos, misture a receita perfeita e escolha um preço; depois veja os clientes fazendo fila e dizendo o que acharam. Libere bebidas novas, melhore sua barraca e mude para a praia, o estádio e o parque de diversões!", controls: "Planeje seu dia com o mouse ou tocando. Durante o dia, clique ou toque na barraca para servir mais rápido e toque nas moedas de ouro para pegar gorjetas. <kbd>Space</kbd> anunciar, <kbd>F</kbd> acelerar, <kbd>Enter</kbd> servir, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Copos vendidos" },
  },
  moonlander: {
    ko: { title: "달 착륙선", desc: "작은 착륙선을 몰고 여섯 행성을 날아다녀요! 엔진을 켜고, 기울이고, 착륙대에 살며시 내려앉으세요. 길 잃은 우주비행사를 구하고, 빛나는 크리스털을 모으고, 얼음 동굴을 빠져나가요. 크리스털로 우주선을 업그레이드하고 별을 모두 모아 보세요.", controls: "<kbd>↑</kbd> / <kbd>W</kbd> / <kbd>Space</kbd>를 누르고 있으면 엔진 분사, <kbd>←</kbd> <kbd>→</kbd>(또는 <kbd>A</kbd> <kbd>D</kbd>)로 기울이기, <kbd>S</kbd>로 똑바로 세우기. 터치스크린에서는 화면 버튼을 써요. <kbd>R</kbd> 다시 시작, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "모은 별" },
    ja: { title: "ムーンランダー", desc: "小さな着陸船で6つの惑星を飛びまわろう！エンジンをふかして、かたむけて、着陸パッドにそっと着地。取り残された宇宙飛行士を助けて、光るクリスタルを集め、氷の洞くつを飛びぬけよう。クリスタルで船をパワーアップして、スターを全部集めよう。", controls: "<kbd>↑</kbd> / <kbd>W</kbd> / <kbd>Space</kbd> 長押しでエンジン噴射、<kbd>←</kbd> <kbd>→</kbd>（または <kbd>A</kbd> <kbd>D</kbd>）でかたむける、<kbd>S</kbd> でまっすぐにもどす。タッチ画面では画面のボタンを使ってね。<kbd>R</kbd> やり直し、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "獲得スター" },
    zh: { title: "登月小飞船", desc: "驾驶小小的着陆器飞越六颗星球！点火、倾斜，然后轻轻降落在着陆平台上。营救被困的宇航员，收集发光的水晶，穿过冰洞。用水晶升级你的飞船，拿到所有星星！", controls: "按住 <kbd>↑</kbd> / <kbd>W</kbd> / <kbd>Space</kbd> 点火，<kbd>←</kbd> <kbd>→</kbd>（或 <kbd>A</kbd> <kbd>D</kbd>）倾斜，<kbd>S</kbd> 摆正。触屏设备请使用屏幕按钮。<kbd>R</kbd> 重来，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "获得星星" },
    es: { title: "Módulo Lunar", desc: "¡Pilota un pequeño módulo de aterrizaje por seis planetas! Enciende el motor, inclínate y posa la nave con suavidad en las plataformas de aterrizaje, rescata a astronautas perdidos, coge cristales brillantes y vuela por cuevas heladas. Gasta los cristales en mejoras para la nave y consigue todas las estrellas.", controls: "Mantén <kbd>↑</kbd> / <kbd>W</kbd> / <kbd>Space</kbd> para encender el motor, <kbd>←</kbd> <kbd>→</kbd> (o <kbd>A</kbd> <kbd>D</kbd>) para inclinarte, <kbd>S</kbd> para enderezarte. En pantallas táctiles, usa los botones de la pantalla. <kbd>R</kbd> reiniciar, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Estrellas ganadas" },
    fr: { title: "Mission Lune", desc: "Pilote un petit atterrisseur sur six planètes ! Allume le moteur, incline-toi et pose-toi en douceur sur les plateformes d'atterrissage, sauve des astronautes en détresse, ramasse des cristaux lumineux et traverse des grottes glacées. Dépense tes cristaux en améliorations pour ton vaisseau et gagne toutes les étoiles.", controls: "Maintiens <kbd>↑</kbd> / <kbd>W</kbd> / <kbd>Space</kbd> pour allumer le moteur, <kbd>←</kbd> <kbd>→</kbd> (ou <kbd>A</kbd> <kbd>D</kbd>) pour t'incliner, <kbd>S</kbd> pour te redresser. Sur écran tactile, utilise les boutons à l'écran. <kbd>R</kbd> recommencer, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Étoiles gagnées" },
    de: { title: "Mondlandung", desc: "Flieg eine kleine Landefähre über sechs Planeten! Zünde das Triebwerk, kipp dich und setz sanft auf Landeplätzen auf, rette gestrandete Astronauten, sammle leuchtende Kristalle und flieg durch eisige Höhlen. Gib Kristalle für Schiffs-Upgrades aus und hol dir alle Sterne.", controls: "Halte <kbd>↑</kbd> / <kbd>W</kbd> / <kbd>Space</kbd> für das Triebwerk, <kbd>←</kbd> <kbd>→</kbd> (oder <kbd>A</kbd> <kbd>D</kbd>) zum Kippen, <kbd>S</kbd> zum Aufrichten. Auf Touchscreens nimmst du die Bildschirmtasten. <kbd>R</kbd> neu starten, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Gesammelte Sterne" },
    pt: { title: "Pouso na Lua", desc: "Pilote uma pequena nave de pouso por seis planetas! Ligue o motor, incline e pouse de leve nas plataformas de pouso, resgate astronautas perdidos, pegue cristais brilhantes e voe por cavernas geladas. Gaste os cristais em melhorias para a nave e ganhe todas as estrelas.", controls: "Segure <kbd>↑</kbd> / <kbd>W</kbd> / <kbd>Space</kbd> para ligar o motor, <kbd>←</kbd> <kbd>→</kbd> (ou <kbd>A</kbd> <kbd>D</kbd>) para inclinar, <kbd>S</kbd> para endireitar. Em telas de toque, use os botões na tela. <kbd>R</kbd> reiniciar, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Estrelas ganhas" },
  },
  colorsort: {
    ko: { title: "색깔 정리", desc: "유리관 사이로 알록달록한 액체를 부어서 관마다 한 가지 색만 남게 만들어요! 언제나 풀 수 있는 퍼즐 200개, 숨은 색 층, 데일리 퍼즐, 빠른 러시 모드, 그리고 모을 수 있는 관과 배경 스킨이 있어요.", controls: "관을 클릭하거나 탭한 다음, 다른 관을 골라 부어요. <kbd>1</kbd>–<kbd>9</kbd> 또는 <kbd>←</kbd> <kbd>→</kbd> + <kbd>Space</kbd>로 관 고르기, <kbd>Z</kbd> 되돌리기, <kbd>R</kbd> 다시 시작, <kbd>H</kbd> 힌트, <kbd>T</kbd> 관 추가, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "모은 별" },
    ja: { title: "カラーソート", desc: "ガラスの試験管どうしでカラフルな液体を注ぎ分けて、どの管も1色だけにしよう！必ず解けるパズルが200問、なぞの層、毎日のパズル、スピード勝負のラッシュモード、集められる管と背景のスキンもあるよ。", controls: "管をクリックかタップして、別の管を選んで注ぐ。<kbd>1</kbd>–<kbd>9</kbd> か <kbd>←</kbd> <kbd>→</kbd> + <kbd>Space</kbd> で管を選ぶ、<kbd>Z</kbd> 取り消し、<kbd>R</kbd> やり直し、<kbd>H</kbd> ヒント、<kbd>T</kbd> 管を追加、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "獲得スター" },
    zh: { title: "颜色分类", desc: "在玻璃管之间倒来倒去，让每根管子只装一种颜色！200 道一定有解的谜题，还有神秘色层、每日谜题、快节奏冲刺模式，以及可以收集的试管和背景皮肤。", controls: "点击或轻触一根管子，再点另一根就能倒进去。<kbd>1</kbd>–<kbd>9</kbd> 或 <kbd>←</kbd> <kbd>→</kbd> + <kbd>Space</kbd> 选择管子，<kbd>Z</kbd> 撤销，<kbd>R</kbd> 重来，<kbd>H</kbd> 提示，<kbd>T</kbd> 加一根管子，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "获得星星" },
    es: { title: "Ordena Colores", desc: "¡Vierte líquidos de colores entre tubos de cristal hasta que cada tubo tenga un solo color! 200 puzles que siempre tienen solución, capas misteriosas, un puzle diario, un modo Rush rapidísimo y aspectos de tubos y fondos para coleccionar.", controls: "Haz clic o toca un tubo y luego otro para verter. <kbd>1</kbd>–<kbd>9</kbd> o <kbd>←</kbd> <kbd>→</kbd> + <kbd>Space</kbd> eligen tubos, <kbd>Z</kbd> deshacer, <kbd>R</kbd> reiniciar, <kbd>H</kbd> pista, <kbd>T</kbd> tubo extra, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Estrellas ganadas" },
    fr: { title: "Tri des Couleurs", desc: "Verse des liquides colorés d'un tube à l'autre jusqu'à ce que chaque tube n'ait plus qu'une seule couleur ! 200 énigmes toujours solubles, des couches mystère, une énigme du jour, un mode Rush ultra rapide, et des skins de tubes et de fonds à collectionner.", controls: "Clique ou touche un tube, puis un autre pour verser. <kbd>1</kbd>–<kbd>9</kbd> ou <kbd>←</kbd> <kbd>→</kbd> + <kbd>Space</kbd> pour choisir les tubes, <kbd>Z</kbd> annuler, <kbd>R</kbd> recommencer, <kbd>H</kbd> indice, <kbd>T</kbd> tube en plus, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Étoiles gagnées" },
    de: { title: "Farben sortieren", desc: "Gieß bunte Flüssigkeiten zwischen Glasröhrchen hin und her, bis in jedem Röhrchen nur noch eine Farbe ist! 200 Rätsel, die immer lösbar sind, geheimnisvolle Schichten, ein Tagesrätsel, ein flotter Rush-Modus und Röhrchen- und Hintergrund-Skins zum Sammeln.", controls: "Klicke oder tippe auf ein Röhrchen, dann auf ein anderes zum Umgießen. <kbd>1</kbd>–<kbd>9</kbd> oder <kbd>←</kbd> <kbd>→</kbd> + <kbd>Space</kbd> wählen Röhrchen, <kbd>Z</kbd> rückgängig, <kbd>R</kbd> neu starten, <kbd>H</kbd> Tipp, <kbd>T</kbd> Extra-Röhrchen, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Gesammelte Sterne" },
    pt: { title: "Separa Cores", desc: "Despeje líquidos coloridos entre tubos de vidro até cada tubo ficar com uma cor só! 200 quebra-cabeças que sempre têm solução, camadas misteriosas, um desafio diário, um modo Corrida bem rápido e visuais de tubos e fundos para colecionar.", controls: "Clique ou toque num tubo e depois em outro para despejar. <kbd>1</kbd>–<kbd>9</kbd> ou <kbd>←</kbd> <kbd>→</kbd> + <kbd>Space</kbd> escolhem tubos, <kbd>Z</kbd> desfazer, <kbd>R</kbd> reiniciar, <kbd>H</kbd> dica, <kbd>T</kbd> tubo extra, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Estrelas ganhas" },
  },
  hillrider: {
    ko: { title: "언덕 라이더", desc: "지프, 오프로드 바이크, 몬스터 트럭, 달 탐사차, 레이싱카를 몰고 울퉁불퉁한 언덕을 달려요. 머리를 콩 박으면 안 돼요! 공중에서 몸을 기울여 회전 착지를 하고, 연료가 떨어지기 전에 연료통을 챙기고, 차를 업그레이드해서 달까지 달려 보세요.", controls: "<kbd>→</kbd>/<kbd>D</kbd> 가속, <kbd>←</kbd>/<kbd>A</kbd> 브레이크와 후진(공중에서는 몸 기울이기), <kbd>Space</kbd> 니트로, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거. 휴대폰에서는 페달을 써요.", label: "최고 거리" },
    ja: { title: "ヒルライダー", desc: "ジープ、ダートバイク、モンスタートラック、月面ローバー、レースカーででこぼこの丘を走ろう。頭をゴツンとぶつけないでね！空中でかたむけて宙返り着地、タンクが空になる前に燃料缶をゲット、マシンをパワーアップして月まで走りぬけよう。", controls: "<kbd>→</kbd>/<kbd>D</kbd> アクセル、<kbd>←</kbd>/<kbd>A</kbd> ブレーキとバック（空中ではかたむける）、<kbd>Space</kbd> ニトロ、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート。スマホではペダルを使ってね。", label: "最長距離" },
    zh: { title: "登山赛车", desc: "开着吉普车、越野摩托、怪兽卡车、月球车或赛车翻越颠簸的山丘，可别撞到脑袋！在空中倾斜身体完成空翻落地，在油箱见底前抢到油桶，升级你的座驾，一路开到月球上去！", controls: "<kbd>→</kbd>/<kbd>D</kbd> 油门，<kbd>←</kbd>/<kbd>A</kbd> 刹车和倒车（在空中也能倾斜车身），<kbd>Space</kbd> 氮气加速，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音。手机上用踏板按钮。", label: "最远距离" },
    es: { title: "Rey de las Colinas", desc: "¡Conduce un todoterreno, una moto de cross, un monster truck, un rover lunar o un coche de carreras por colinas llenas de baches, y no te des en la cabeza! Inclínate en el aire para aterrizar volteretas, coge bidones de gasolina antes de quedarte seco y mejora tu vehículo para llegar hasta la Luna.", controls: "<kbd>→</kbd>/<kbd>D</kbd> acelerar, <kbd>←</kbd>/<kbd>A</kbd> frenar y marcha atrás (también te inclinan en el aire), <kbd>Space</kbd> nitro, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar. En el móvil, usa los pedales.", label: "Mejor distancia" },
    fr: { title: "Pilote des Collines", desc: "Conduis une jeep, une moto-cross, un monster truck, un rover lunaire ou une voiture de course sur des collines pleines de bosses, et ne te cogne pas la tête ! Penche-toi en l'air pour réussir des saltos, attrape les bidons d'essence avant la panne sèche et améliore ton véhicule pour rouler jusqu'à la Lune.", controls: "<kbd>→</kbd>/<kbd>D</kbd> accélérer, <kbd>←</kbd>/<kbd>A</kbd> freiner et reculer (ils te font aussi pencher en l'air), <kbd>Space</kbd> nitro, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son. Sur téléphone, utilise les pédales.", label: "Meilleure distance" },
    de: { title: "Hügel-Raser", desc: "Fahr einen Jeep, ein Dirtbike, einen Monstertruck, einen Mondrover oder einen Rennwagen über holprige Hügel – und stoß dir bloß nicht den Kopf! Lehn dich in der Luft für Saltos, schnapp dir Benzinkanister, bevor der Tank leer ist, und rüste dein Fahrzeug auf, um bis zum Mond zu fahren.", controls: "<kbd>→</kbd>/<kbd>D</kbd> Gas, <kbd>←</kbd>/<kbd>A</kbd> Bremse und Rückwärtsgang (in der Luft kippen sie dich), <kbd>Space</kbd> Nitro, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus. Auf dem Handy nimmst du die Pedale.", label: "Weiteste Strecke" },
    pt: { title: "Piloto das Colinas", desc: "Dirija um jipe, uma moto de trilha, um monster truck, um jipe lunar ou um carro de corrida por colinas esburacadas, e não bata a cabeça! Incline no ar para pousar piruetas, pegue galões de combustível antes do tanque secar e melhore seu veículo para ir até a Lua.", controls: "<kbd>→</kbd>/<kbd>D</kbd> acelerar, <kbd>←</kbd>/<kbd>A</kbd> frear e dar ré (também inclinam no ar), <kbd>Space</kbd> nitro, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo. No celular, use os pedais.", label: "Melhor distância" },
  },
  jetpup: {
    ko: { title: "제트 강아지", desc: "강아지에게 제트팩을 메고 연구소를 쌩쌩 날아다녀요! 전기 장치, 로켓, 레이저, 그리고 위스커스 선장을 피하고, 로봇 슈트, 새 친구, 중력 부츠를 타 보세요. 코인과 뼈다귀로 기계 장치와 귀여운 옷을 사요.", controls: "<kbd>Space</kbd>, 마우스 버튼 또는 손가락을 누르고 있으면 날아요. <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "최고 거리" },
    ja: { title: "ジェットわんこ", desc: "子犬にジェットパックをつけて研究所をビューンと飛ぼう！ビリビリ装置、ロケット、レーザー、そしてキャプテン・ウィスカーズをかわして、メカスーツ、鳥のなかま、重力ブーツに乗ろう。コインとホネでガジェットやかわいいコスチュームを買えるよ。", controls: "<kbd>Space</kbd>、マウスボタン、または指を長押しで飛ぶ。<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "最長距離" },
    zh: { title: "喷气小狗", desc: "给小狗绑上喷气背包，在实验室里飞速穿梭！躲开电击器、火箭、激光和胡须船长，骑上机甲战衣、小鸟伙伴或重力靴，再用金币和骨头买小道具和可爱服装。", controls: "按住 <kbd>Space</kbd>、鼠标键或手指就能飞。<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "最远距离" },
    es: { title: "Perrito a Reacción", desc: "¡Ponle una mochila cohete a un perrito y vuela a toda velocidad por el laboratorio! Esquiva electrochoques, cohetes, láseres y al Capitán Bigotes, móntate en un traje robot, un amigo pájaro o unas botas de gravedad, y gasta monedas y huesos en artilugios y disfraces monísimos.", controls: "Mantén <kbd>Space</kbd>, el botón del ratón o el dedo para volar. <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Mejor distancia" },
    fr: { title: "Toutou Jet", desc: "Équipe un chiot d'un jetpack et fonce à travers le labo ! Esquive les électrocuteurs, les fusées, les lasers et le Capitaine Moustaches, chevauche une armure robot, un copain oiseau ou des bottes de gravité, et dépense pièces et os en gadgets et costumes trop mignons.", controls: "Maintiens <kbd>Space</kbd>, le bouton de la souris ou ton doigt pour voler. <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Meilleure distance" },
    de: { title: "Düsen-Welpe", desc: "Schnall einem Welpen ein Jetpack um und düs durchs Labor! Weich Blitzfallen, Raketen, Lasern und Kapitän Schnurrhaar aus, reite einen Mech-Anzug, einen Vogelkumpel oder Schwerkraftstiefel und gib Münzen und Knochen für Gadgets und süße Kostüme aus.", controls: "Halte <kbd>Space</kbd>, die Maustaste oder deinen Finger zum Fliegen. <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Weiteste Strecke" },
    pt: { title: "Cãozinho a Jato", desc: "Coloque uma mochila a jato num cachorrinho e voe pelo laboratório! Desvie de choques, foguetes, lasers e do Capitão Bigodes, ande num traje robô, num amigo pássaro ou em botas de gravidade, e gaste moedas e ossos em engenhocas e fantasias fofas.", controls: "Segure <kbd>Space</kbd>, o botão do mouse ou o dedo para voar. <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Melhor distância" },
  },
  tennisace: {
    ko: { title: "테니스 에이스", desc: "딱 맞는 순간에 라켓을 휘둘러 스매시, 로브, 서브로 잔디, 클레이, 하드 코트의 동물 테니스 투어를 돌파해요. 슈퍼 샷을 터뜨리고, 라이벌을 이겨서 그 선수로도 플레이하고, 새 라켓과 옷을 사고, 트레이닝 캠프에서 타이밍을 갈고닦으세요.", controls: "<kbd>Space</kbd> 치기 또는 서브(공을 띄우고 가장 높을 때 치기), <kbd>K</kbd> 로브, <kbd>L</kbd> 드롭샷, <kbd>E</kbd> 슈퍼 샷, <kbd>←</kbd>/<kbd>→</kbd>를 누르고 있으면 조준, 방향키로 이동(처음엔 자동 달리기가 켜져 있어요), <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거. 휴대폰에서는 탭해서 쳐요.", label: "모은 별" },
    ja: { title: "テニスエース", desc: "ぴったりのタイミングでラケットをふって、スマッシュ、ロブ、サーブで芝、クレー、ハードコートの動物テニスツアーを勝ちぬこう。スーパーショットを放ち、ライバルに勝ったらそのキャラで遊べるよ。新しいラケットや服を買って、トレーニングキャンプでタイミングをみがこう。", controls: "<kbd>Space</kbd> 打つかサーブ（トスして一番高いところで打つ）、<kbd>K</kbd> ロブ、<kbd>L</kbd> ドロップショット、<kbd>E</kbd> スーパーショット、<kbd>←</kbd>/<kbd>→</kbd> 長押しでねらう、矢印キーで移動（最初はオートランがオン）、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート。スマホではタップで打つ。", label: "獲得スター" },
    zh: { title: "网球王牌", desc: "抓准时机挥拍，用扣杀、挑高球和发球闯过草地、红土和硬地上的动物网球巡回赛。打出超级击球，打败对手就能用他们来比赛，买新球拍和服装，再到训练营磨练你的节奏感。", controls: "<kbd>Space</kbd> 击球或发球（抛球后在最高点击球），<kbd>K</kbd> 挑高球，<kbd>L</kbd> 放小球，<kbd>E</kbd> 超级击球，按住 <kbd>←</kbd>/<kbd>→</kbd> 瞄准，方向键移动（一开始自动跑位是开着的），<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音。手机上轻点击球。", label: "获得星星" },
    es: { title: "As del Tenis", desc: "¡Golpea justo a tiempo para rematar, hacer globos y sacar en un circuito de tenis de animales sobre hierba, tierra batida y pista dura! Desata supergolpes, vence a tus rivales para jugar con ellos, compra raquetas y ropa nuevas y afina tu puntería en el Campamento de Entrenamiento.", controls: "<kbd>Space</kbd> golpear o sacar (lanza la bola y golpea arriba del todo), <kbd>K</kbd> globo, <kbd>L</kbd> dejada, <kbd>E</kbd> supergolpe, mantén <kbd>←</kbd>/<kbd>→</kbd> para apuntar, flechas para moverte (al principio corres solo), <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar. En el móvil, toca para golpear.", label: "Estrellas ganadas" },
    fr: { title: "As du Tennis", desc: "Frappe pile au bon moment pour smasher, lober et servir tout au long d'un circuit de tennis animal sur gazon, terre battue et dur. Déchaîne des super coups, bats tes rivaux pour jouer avec eux, achète de nouvelles raquettes et tenues, et affine ton timing au Camp d'entraînement.", controls: "<kbd>Space</kbd> frapper ou servir (lance la balle, puis frappe en haut), <kbd>K</kbd> lob, <kbd>L</kbd> amorti, <kbd>E</kbd> super coup, maintiens <kbd>←</kbd>/<kbd>→</kbd> pour viser, les flèches pour bouger (la course auto est activée au début), <kbd>P</kbd> pause, <kbd>M</kbd> couper le son. Sur téléphone, touche pour frapper.", label: "Étoiles gagnées" },
    de: { title: "Tennis-Ass", desc: "Schlag genau im richtigen Moment zu und smashe, lobbe und serviere dich durch eine Tier-Tennistour auf Rasen, Sand und Hartplatz. Entfessle Superschläge, besiege Rivalen, um mit ihnen zu spielen, kauf neue Schläger und Outfits und verbessere dein Timing im Trainingscamp.", controls: "<kbd>Space</kbd> schlagen oder aufschlagen (hochwerfen, dann oben treffen), <kbd>K</kbd> Lob, <kbd>L</kbd> Stoppball, <kbd>E</kbd> Superschlag, <kbd>←</kbd>/<kbd>→</kbd> halten zum Zielen, Pfeiltasten zum Laufen (Auto-Laufen ist am Anfang an), <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus. Auf dem Handy tippen zum Schlagen.", label: "Gesammelte Sterne" },
    pt: { title: "Ás do Tênis", desc: "Bata na hora certinha para dar smashes, lobs e saques num circuito de tênis de animais na grama, no saibro e na quadra dura. Solte supergolpes, vença os rivais para jogar com eles, compre raquetes e roupas novas e afine seu tempo de bola no Campo de Treino.", controls: "<kbd>Space</kbd> rebater ou sacar (jogue a bola e bata no alto), <kbd>K</kbd> lob, <kbd>L</kbd> curtinha, <kbd>E</kbd> supergolpe, segure <kbd>←</kbd>/<kbd>→</kbd> para mirar, setas para andar (a corrida automática começa ligada), <kbd>P</kbd> pausar, <kbd>M</kbd> mudo. No celular, toque para rebater.", label: "Estrelas ganhas" },
  },
  skybounce: {
    ko: { title: "하늘 점프", desc: "통통 튀는 발판을 밟고 점점 더 높이 뛰어올라요! 웃긴 몬스터를 밟고, 제트팩과 프로펠러 모자를 잡고, 햇살 가득한 초원에서 우주까지 올라가세요. 폭풍 구름을 물리치고, 미션을 끝내고, 캐릭터를 열고, 데일리 클라임에도 도전하세요.", controls: "<kbd>←</kbd> <kbd>→</kbd>, <kbd>A</kbd> <kbd>D</kbd> 또는 마우스로 방향 조종, <kbd>Space</kbd>, <kbd>↑</kbd> 또는 클릭으로 쏘기. 터치스크린에서는 누른 채로 방향을 잡고 별 버튼으로 쏴요. <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "최고 높이" },
    ja: { title: "スカイバウンス", desc: "ボヨンボヨンの足場でどんどん高くジャンプ！ヘンテコなモンスターをふみつけて、ジェットパックやプロペラ帽子をゲット。ひだまりの草原から宇宙までのぼろう！ストームクラウドをたおし、ミッションをクリアして、キャラクターを解放、デイリークライムにも挑戦しよう。", controls: "<kbd>←</kbd> <kbd>→</kbd>、<kbd>A</kbd> <kbd>D</kbd> かマウスで方向を変える、<kbd>Space</kbd>、<kbd>↑</kbd> かクリックで撃つ。タッチ画面では長押しで方向を変えて、スターボタンで撃つ。<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "最高到達点" },
    zh: { title: "跳跳上青天", desc: "在弹弹的平台上越跳越高，踩扁搞笑的小怪物，抓住喷气背包和螺旋桨帽子，从阳光草原一路爬到外太空！打败风暴云，完成任务，解锁新角色，再挑战每日攀登吧。", controls: "<kbd>←</kbd> <kbd>→</kbd>、<kbd>A</kbd> <kbd>D</kbd> 或鼠标控制方向，<kbd>Space</kbd>、<kbd>↑</kbd> 或点击射击。触屏上按住控制方向，用星星按钮射击。<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "最高高度" },
    es: { title: "Rebote al Cielo", desc: "¡Rebota cada vez más alto en plataformas saltarinas, aplasta monstruos chiflados y coge mochilas cohete y gorros con hélice! Sube desde praderas soleadas hasta el espacio exterior. Vence a la Nube Tormenta, completa misiones, desbloquea personajes y prueba la Escalada Diaria.", controls: "<kbd>←</kbd> <kbd>→</kbd>, <kbd>A</kbd> <kbd>D</kbd> o el ratón para dirigir; <kbd>Space</kbd>, <kbd>↑</kbd> o clic para disparar. En pantallas táctiles, mantén pulsado para dirigir y usa el botón de estrella para disparar. <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Mejor altura" },
    fr: { title: "Rebond Céleste", desc: "Rebondis toujours plus haut sur des plateformes à ressort, écrase des monstres rigolos et attrape des jetpacks et des chapeaux à hélice. Grimpe des prairies ensoleillées jusque dans l'espace ! Bats le Nuage d'orage, termine des missions, débloque des personnages et essaie l'Ascension du jour.", controls: "<kbd>←</kbd> <kbd>→</kbd>, <kbd>A</kbd> <kbd>D</kbd> ou la souris pour diriger, <kbd>Space</kbd>, <kbd>↑</kbd> ou clic pour tirer. Sur écran tactile, maintiens pour diriger et utilise le bouton étoile pour tirer. <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Meilleure hauteur" },
    de: { title: "Himmelshüpfer", desc: "Hüpf auf federnden Plattformen immer höher, stampf alberne Monster platt und schnapp dir Jetpacks und Propellermützen. Kletter von sonnigen Wiesen bis ins Weltall! Besiege die Sturmwolke, erledige Missionen, schalte Figuren frei und probier den täglichen Aufstieg.", controls: "<kbd>←</kbd> <kbd>→</kbd>, <kbd>A</kbd> <kbd>D</kbd> oder die Maus zum Steuern, <kbd>Space</kbd>, <kbd>↑</kbd> oder Klick zum Schießen. Auf Touchscreens halten zum Steuern und mit dem Stern-Button schießen. <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Beste Höhe" },
    pt: { title: "Pulo ao Céu", desc: "Quique cada vez mais alto em plataformas de mola, pise em monstrinhos malucos e pegue mochilas a jato e chapéus de hélice. Suba de campos ensolarados até o espaço sideral! Vença a Nuvem de Tempestade, complete missões, libere personagens e tente a Escalada Diária.", controls: "<kbd>←</kbd> <kbd>→</kbd>, <kbd>A</kbd> <kbd>D</kbd> ou o mouse para guiar; <kbd>Space</kbd>, <kbd>↑</kbd> ou clique para atirar. Em telas de toque, segure para guiar e use o botão de estrela para atirar. <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Melhor altura" },
  },
  powderpeak: {
    ko: { title: "파우더 피크", desc: "스노보드를 타고 눈 덮인 산을 가르며 내려가요! 슬라롬 깃발 사이를 쌩쌩 지나고, 점프대에서 날아올라 스핀, 플립, 그랩을 하고, 레일을 그라인드하고, 눈사태보다 빨리 달아나세요. 산 4곳, 이벤트 24개, 그리고 열 수 있는 보드와 옷이 가득해요.", controls: "<kbd>←</kbd> <kbd>→</kbd> 방향 조종과 스핀, <kbd>↓</kbd> 웅크리기 또는 그랩, <kbd>↑</kbd> 브레이크 또는 플립, <kbd>Space</kbd> 또는 클릭으로 점프. 마우스로도 조종돼요. 터치스크린에서는 왼쪽이나 오른쪽을 누르고, 가운데를 누르면 웅크리기, 위로 스와이프하면 점프. <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "모은 별" },
    ja: { title: "パウダーピーク", desc: "スノーボードで雪山をかっこよくすべりおりよう！スラロームの旗をすりぬけ、キッカーから飛び出してスピン、フリップ、グラブ、レールをグラインドして、なだれから逃げきろう。4つの山、24のイベント、解放できるボードや服がいっぱい！", controls: "<kbd>←</kbd> <kbd>→</kbd> 方向とスピン、<kbd>↓</kbd> しゃがむかグラブ、<kbd>↑</kbd> ブレーキかフリップ、<kbd>Space</kbd> かクリックでジャンプ。マウスでも操作できるよ。タッチ画面では左か右を長押し、真ん中でしゃがむ、上にスワイプでジャンプ。<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "獲得スター" },
    zh: { title: "粉雪巅峰", desc: "踩着滑雪板从雪山上飞驰而下！穿过回转旗门，从跳台腾空做旋转、空翻和抓板，在铁杆上滑行，还要甩开雪崩！4 座雪山、24 项赛事，还有好多滑雪板和服装等你解锁。", controls: "<kbd>←</kbd> <kbd>→</kbd> 转向和旋转，<kbd>↓</kbd> 下蹲或抓板，<kbd>↑</kbd> 刹车或空翻，<kbd>Space</kbd> 或点击跳跃。鼠标也能控制方向。触屏上按住左侧或右侧转向，按中间下蹲，向上滑动跳跃。<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "获得星星" },
    es: { title: "Pico Nevado", desc: "¡Baja montañas nevadas con tu snowboard! Pasa zumbando entre las banderas del eslalon, salta desde los kickers para hacer giros, volteretas y grabs, deslízate por barandillas y escapa de la avalancha. Cuatro montañas, 24 pruebas y tablas y trajes para desbloquear.", controls: "<kbd>←</kbd> <kbd>→</kbd> girar y hacer giros, <kbd>↓</kbd> agacharse o grab, <kbd>↑</kbd> frenar o voltereta, <kbd>Space</kbd> o clic para saltar. El ratón también sirve para dirigir. En pantallas táctiles, mantén el lado izquierdo o derecho, el centro para agacharte y desliza hacia arriba para saltar. <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Estrellas ganadas" },
    fr: { title: "Pic Poudreuse", desc: "Dévale des montagnes enneigées sur ton snowboard ! File entre les portes du slalom, décolle des tremplins pour des rotations, des flips et des grabs, glisse sur les rails et échappe à l'avalanche. Quatre montagnes, 24 épreuves, et des planches et tenues à débloquer.", controls: "<kbd>←</kbd> <kbd>→</kbd> diriger et tourner, <kbd>↓</kbd> se baisser ou grab, <kbd>↑</kbd> freiner ou flip, <kbd>Space</kbd> ou clic pour sauter. La souris permet aussi de diriger. Sur écran tactile, maintiens le côté gauche ou droit, le milieu pour te baisser, et glisse vers le haut pour sauter. <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Étoiles gagnées" },
    de: { title: "Pulverschnee-Gipfel", desc: "Carve mit deinem Snowboard verschneite Berge hinunter! Flitz durch Slalomtore, heb von Kickern ab für Spins, Flips und Grabs, grinde über Rails und häng die Lawine ab. Vier Berge, 24 Events und jede Menge Boards und Outfits zum Freischalten.", controls: "<kbd>←</kbd> <kbd>→</kbd> lenken und drehen, <kbd>↓</kbd> ducken oder Grab, <kbd>↑</kbd> bremsen oder Flip, <kbd>Space</kbd> oder Klick zum Springen. Mit der Maus lenkst du auch. Auf Touchscreens links oder rechts halten, Mitte zum Ducken, nach oben wischen zum Springen. <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Gesammelte Sterne" },
    pt: { title: "Pico Nevado", desc: "Desça montanhas nevadas na sua prancha de snowboard! Passe zunindo pelas bandeiras do slalom, decole das rampas para giros, mortais e grabs, deslize nos corrimãos e fuja da avalanche. Quatro montanhas, 24 provas e pranchas e roupas para liberar.", controls: "<kbd>←</kbd> <kbd>→</kbd> virar e girar, <kbd>↓</kbd> agachar ou grab, <kbd>↑</kbd> frear ou mortal, <kbd>Space</kbd> ou clique para pular. O mouse também guia. Em telas de toque, segure o lado esquerdo ou direito, o meio para agachar e deslize para cima para pular. <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Estrelas ganhas" },
  },
  candydrop: {
    ko: { title: "캔디 드롭", desc: "쓱 그어서 줄을 끊고 사탕을 흔들어 먹보 몽치의 입에 쏙! 비눗방울을 타고 둥둥 떠오르고, 공기 쿠션을 뿡 불고, 가시를 피하고, 순간이동 파이프로 슝 이동해요. 사탕 상자 네 개에 퍼즐 48개, 레벨마다 별 3개를 노려 보세요.", controls: "쓱 그어서(드래그) 줄 끊기, 사탕을 클릭하거나 탭해서(또는 <kbd>Space</kbd>) 비눗방울 터뜨리기, 쿠션을 클릭하거나 탭해서(또는 <kbd>1</kbd>–<kbd>4</kbd>) 바람 불기. <kbd>H</kbd> 힌트, <kbd>R</kbd> 다시 시작, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거", label: "모은 별" },
    ja: { title: "キャンディドロップ", desc: "スワイプでロープを切って、キャンディをゆらしてマンチの口へポイッ！シャボン玉でぷかぷか浮かんで、エアクッションをプシュッとふかし、トゲをよけて、ワープパイプでビューン。4つのキャンディボックスに48のパズル、どのレベルでもスター3つをねらおう。", controls: "スワイプ（ドラッグ）でロープを切る、キャンディをクリックかタップ（または <kbd>Space</kbd>）でシャボン玉をわる、クッションをクリックかタップ（または <kbd>1</kbd>–<kbd>4</kbd>）で空気をふかす。<kbd>H</kbd> ヒント、<kbd>R</kbd> やり直し、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート", label: "獲得スター" },
    zh: { title: "糖果掉掉乐", desc: "划一下剪断绳子，让糖果荡进小吃货蒙奇的嘴里！乘着泡泡飘起来，拍打气垫吹一口气，躲开尖刺，钻进传送管道嗖地穿越。四个糖果盒共 48 道谜题，每一关都有 3 颗星星等你拿！", controls: "划动（拖动）剪断绳子，点击或轻触糖果（或按 <kbd>Space</kbd>）戳破泡泡，点击或轻触气垫（或按 <kbd>1</kbd>–<kbd>4</kbd>）吹气。<kbd>H</kbd> 提示，<kbd>R</kbd> 重来，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音", label: "获得星星" },
    es: { title: "¡Que Caiga el Dulce!", desc: "¡Desliza para cortar las cuerdas y balancear el caramelo hasta la boca de Munch! Flota en burbujas, sopla con cojines de aire, esquiva pinchos y viaja por tuberías de teletransporte. 48 puzles en cuatro cajas de dulces, con 3 estrellas por ganar en cada nivel.", controls: "Desliza (arrastra) para cortar cuerdas, haz clic o toca el caramelo (o <kbd>Space</kbd>) para explotar burbujas, haz clic o toca un cojín (o <kbd>1</kbd>–<kbd>4</kbd>) para soplar. <kbd>H</kbd> pista, <kbd>R</kbd> reiniciar, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar", label: "Estrellas ganadas" },
    fr: { title: "Bonbon Plouf", desc: "Glisse pour couper les cordes et fais balancer le bonbon jusque dans la bouche de Munch ! Flotte dans des bulles, souffle avec des coussins d'air, évite les piques et file dans des tuyaux de téléportation. 48 énigmes dans quatre boîtes de bonbons, avec 3 étoiles à gagner à chaque niveau.", controls: "Glisse (fais glisser) pour couper les cordes, clique ou touche le bonbon (ou <kbd>Space</kbd>) pour éclater les bulles, clique ou touche un coussin (ou <kbd>1</kbd>–<kbd>4</kbd>) pour souffler. <kbd>H</kbd> indice, <kbd>R</kbd> recommencer, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son", label: "Étoiles gagnées" },
    de: { title: "Bonbon-Plumps", desc: "Wisch, um die Seile durchzuschneiden, und schwing das Bonbon in Munchs Mund! Schweb in Seifenblasen, puste mit Luftkissen, weich Stacheln aus und saus durch Teleport-Rohre. 48 Rätsel in vier Bonbonschachteln, mit 3 Sternen in jedem Level zu holen.", controls: "Wisch (zieh), um Seile zu schneiden, klicke oder tippe auf das Bonbon (oder <kbd>Space</kbd>), um Blasen platzen zu lassen, klicke oder tippe auf ein Kissen (oder <kbd>1</kbd>–<kbd>4</kbd>) zum Pusten. <kbd>H</kbd> Tipp, <kbd>R</kbd> neu starten, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus", label: "Gesammelte Sterne" },
    pt: { title: "Cai, Docinho!", desc: "Deslize para cortar as cordas e balançar o doce até a boca do Munch! Flutue em bolhas, sopre com almofadas de ar, desvie dos espinhos e passe voando por canos de teletransporte. 48 quebra-cabeças em quatro caixas de doces, com 3 estrelas para ganhar em cada fase.", controls: "Deslize (arraste) para cortar as cordas, clique ou toque no doce (ou <kbd>Space</kbd>) para estourar bolhas, clique ou toque numa almofada (ou <kbd>1</kbd>–<kbd>4</kbd>) para soprar. <kbd>H</kbd> dica, <kbd>R</kbd> reiniciar, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo", label: "Estrelas ganhas" },
  },
  sumobots: {
    ko: { title: "스모 로봇", desc: "작은 로봇을 만들어 하늘에 떠 있는 무대 밖으로 라이벌을 밀어내요! 돌진해서 들이받고, 막기로 튕겨 내고, 힘을 모아 방어를 뚫으세요. 얼음, 범퍼, 빙글빙글 도는 망치도 조심! 보스 로봇 5대를 넘어 리그 컵 5개를 차지하고, 차고에서 부품을 업그레이드하거나, 키보드 하나로 친구와 대결해요.", controls: "<kbd>WASD</kbd> 또는 방향키로 이동, <kbd>Space</kbd>를 탭하면 돌진(누르고 있으면 충전), <kbd>Shift</kbd>를 누르고 있으면 막기, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거. 2인용: P1 <kbd>WASD</kbd> + <kbd>F</kbd>/<kbd>G</kbd>, P2 방향키 + <kbd>.</kbd>/<kbd>/</kbd>. 터치 스틱과 버튼도 돼요.", label: "모은 별" },
    ja: { title: "すもうロボ", desc: "小さなロボットを作って、空にうかぶ土俵からライバルをおし出そう！ダッシュでぶつかり、ガードではね返し、パワーをためて相手のガードをくだけ。氷、バンパー、回るハンマーにも注意！5体のボスロボをこえて5つのリーグカップをのぼり、ガレージでパーツを強化したり、1つのキーボードで友だちと対戦したりしよう。", controls: "<kbd>WASD</kbd> か矢印キーで移動、<kbd>Space</kbd> をタップでダッシュ（長押しでチャージ）、<kbd>Shift</kbd> 長押しでガード、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート。2人プレイ：P1 <kbd>WASD</kbd> + <kbd>F</kbd>/<kbd>G</kbd>、P2 矢印キー + <kbd>.</kbd>/<kbd>/</kbd>。タッチのスティックとボタンも使えるよ。", label: "獲得スター" },
    zh: { title: "相扑机器人", desc: "造一个小机器人，把对手推下漂浮在空中的擂台！冲撞对手，用格挡把他们弹回去，蓄力击破他们的防御，同时躲开冰面、弹簧柱和旋转大锤。闯过 5 个Boss机器人，夺下 5 座联赛杯，在车库升级零件，或者用一个键盘和朋友对战！", controls: "<kbd>WASD</kbd> 或方向键移动，轻按 <kbd>Space</kbd> 冲撞（按住蓄力），按住 <kbd>Shift</kbd> 格挡，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音。双人：P1 <kbd>WASD</kbd> + <kbd>F</kbd>/<kbd>G</kbd>，P2 方向键 + <kbd>.</kbd>/<kbd>/</kbd>。也支持触屏摇杆和按钮。", label: "获得星星" },
    es: { title: "Robots de Sumo", desc: "¡Construye un robotito y echa a tus rivales de plataformas flotantes en el cielo! Embiste a los bots, bloquea para rebotarlos y carga tu ataque para romper su guardia, mientras esquivas hielo, rebotadores y martillos giratorios. Sube 5 copas de liga superando a 5 bots jefe, mejora tus piezas en el taller o lucha contra un amigo en un solo teclado.", controls: "<kbd>WASD</kbd> o flechas para moverte, toca <kbd>Space</kbd> para embestir (mantén para cargar), mantén <kbd>Shift</kbd> para bloquear, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar. 2 jugadores: J1 <kbd>WASD</kbd> + <kbd>F</kbd>/<kbd>G</kbd>, J2 flechas + <kbd>.</kbd>/<kbd>/</kbd>. También funcionan el joystick y los botones táctiles.", label: "Estrellas ganadas" },
    fr: { title: "Robots Sumo", desc: "Construis un petit robot et pousse tes rivaux hors de plateformes flottant dans le ciel ! Fonce dans les bots, bloque pour les renvoyer et charge ton attaque pour briser leur garde, tout en évitant la glace, les bumpers et les marteaux tournants. Grimpe 5 coupes de ligue face à 5 robots boss, améliore tes pièces au garage ou affronte un ami sur un seul clavier.", controls: "<kbd>WASD</kbd> ou les flèches pour bouger, touche <kbd>Space</kbd> pour foncer (maintiens pour charger), maintiens <kbd>Shift</kbd> pour bloquer, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son. 2 joueurs : J1 <kbd>WASD</kbd> + <kbd>F</kbd>/<kbd>G</kbd>, J2 flèches + <kbd>.</kbd>/<kbd>/</kbd>. Le joystick et les boutons tactiles marchent aussi.", label: "Étoiles gagnées" },
    de: { title: "Sumo-Roboter", desc: "Bau einen kleinen Roboter und schubs deine Rivalen von schwebenden Himmelsplattformen! Ramm die Bots, blocke, um sie abprallen zu lassen, und lade auf, um ihre Deckung zu durchbrechen – und weich dabei Eis, Bumpern und kreiselnden Hämmern aus. Kämpf dich durch 5 Liga-Pokale an 5 Boss-Bots vorbei, rüste deine Teile in der Garage auf oder tritt an einer Tastatur gegen einen Freund an.", controls: "<kbd>WASD</kbd> oder Pfeiltasten zum Bewegen, <kbd>Space</kbd> antippen zum Rammen (halten zum Aufladen), <kbd>Shift</kbd> halten zum Blocken, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus. 2 Spieler: S1 <kbd>WASD</kbd> + <kbd>F</kbd>/<kbd>G</kbd>, S2 Pfeiltasten + <kbd>.</kbd>/<kbd>/</kbd>. Touch-Stick und Buttons gehen auch.", label: "Gesammelte Sterne" },
    pt: { title: "Robôs de Sumô", desc: "Monte um robozinho e empurre seus rivais para fora de plataformas flutuantes no céu! Dê trombadas nos bots, bloqueie para rebatê-los e carregue o golpe para quebrar a defesa deles, enquanto desvia de gelo, para-choques e martelos giratórios. Suba 5 copas da liga passando por 5 robôs chefões, melhore suas peças na garagem ou enfrente um amigo num teclado só.", controls: "<kbd>WASD</kbd> ou setas para andar, toque <kbd>Space</kbd> para dar trombada (segure para carregar), segure <kbd>Shift</kbd> para bloquear, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo. 2 jogadores: J1 <kbd>WASD</kbd> + <kbd>F</kbd>/<kbd>G</kbd>, J2 setas + <kbd>.</kbd>/<kbd>/</kbd>. O controle e os botões de toque também funcionam.", label: "Estrelas ganhas" },
  },
  cardcastle: {
    ko: { title: "카드 캐슬", desc: "솔리테어 세 가지를 한 번에: 클론다이크, 스파이더, 피라미드! 카드를 끌거나 탭해서 자동으로 옮기고, 되돌리기와 힌트를 쓰고, 이기면 카드가 통통 튀는 걸 구경하세요. 별을 모아 나만의 성을 짓고, 데일리 딜을 즐기고, 새 카드 뒷면과 테이블을 열어요.", controls: "카드를 끌거나 클릭하면 자동으로 옮겨요. <kbd>Space</kbd> 카드 뽑기, <kbd>U</kbd> 되돌리기, <kbd>H</kbd> 힌트, <kbd>N</kbd> 새 게임, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거.", label: "모은 별" },
    ja: { title: "トランプのお城", desc: "3つのソリティアが1つに！クロンダイク、スパイダー、ピラミッド。カードをドラッグするかタップで自動移動、取り消しやヒントも使えて、勝つとカードがはずむよ。スターを集めて自分のお城を建て、毎日のディールで遊び、新しいカードの裏面やテーブルを解放しよう。", controls: "カードをドラッグするかクリックで自動移動。<kbd>Space</kbd> カードをめくる、<kbd>U</kbd> 取り消し、<kbd>H</kbd> ヒント、<kbd>N</kbd> 新しいゲーム、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート。", label: "獲得スター" },
    zh: { title: "纸牌城堡", desc: "三种接龙一次玩个够：克朗代克、蜘蛛和金字塔！拖动纸牌或轻点自动移牌，能撤销也有提示，赢了还能看纸牌蹦蹦跳跳。收集星星建造你自己的城堡，玩每日牌局，解锁新的牌背和牌桌！", controls: "拖动纸牌或点击自动移牌。<kbd>Space</kbd> 翻牌，<kbd>U</kbd> 撤销，<kbd>H</kbd> 提示，<kbd>N</kbd> 新游戏，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音。", label: "获得星星" },
    es: { title: "Castillo de Cartas", desc: "¡Tres solitarios en uno: Klondike, Spider y Pirámide! Arrastra las cartas o tócalas para moverlas solas, usa deshacer y pistas, y mira cómo rebotan las cartas cuando ganas. Gana estrellas para construir tu propio castillo, juega los repartos diarios y desbloquea reversos de cartas y mesas nuevas.", controls: "Arrastra las cartas o haz clic para moverlas solas. <kbd>Space</kbd> robar, <kbd>U</kbd> deshacer, <kbd>H</kbd> pista, <kbd>N</kbd> partida nueva, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar.", label: "Estrellas ganadas" },
    fr: { title: "Château de Cartes", desc: "Trois patiences en une : Klondike, Spider et Pyramide ! Fais glisser les cartes ou touche-les pour les déplacer toutes seules, utilise annuler et les indices, et regarde les cartes rebondir quand tu gagnes. Gagne des étoiles pour construire ton propre château, joue les donnes du jour et débloque de nouveaux dos de cartes et tapis.", controls: "Fais glisser les cartes ou clique pour les déplacer automatiquement. <kbd>Space</kbd> piocher, <kbd>U</kbd> annuler, <kbd>H</kbd> indice, <kbd>N</kbd> nouvelle partie, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son.", label: "Étoiles gagnées" },
    de: { title: "Kartenschloss", desc: "Drei Patiencen in einer: Klondike, Spider und Pyramide! Zieh Karten oder tipp sie an, damit sie von selbst wandern, nutz Rückgängig und Tipps und schau zu, wie die Karten beim Sieg herumhüpfen. Sammle Sterne, um dein eigenes Schloss zu bauen, spiel die Tagesrunden und schalte neue Kartenrücken und Tische frei.", controls: "Zieh Karten oder klicke für automatisches Ziehen. <kbd>Space</kbd> Karte aufdecken, <kbd>U</kbd> rückgängig, <kbd>H</kbd> Tipp, <kbd>N</kbd> neues Spiel, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus.", label: "Gesammelte Sterne" },
    pt: { title: "Castelo de Cartas", desc: "Três paciências em uma: Klondike, Spider e Pirâmide! Arraste as cartas ou toque nelas para movê-las sozinhas, use desfazer e dicas, e veja as cartas pularem quando você vence. Ganhe estrelas para construir seu próprio castelo, jogue as rodadas diárias e libere novos versos de cartas e mesas.", controls: "Arraste as cartas ou clique para movê-las sozinhas. <kbd>Space</kbd> comprar, <kbd>U</kbd> desfazer, <kbd>H</kbd> dica, <kbd>N</kbd> novo jogo, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo.", label: "Estrelas ganhas" },
  },
  waverider: {
    ko: { title: "파도 라이더", desc: "열대 석호, 거친 강, 밤의 항구를 제트스키로 질주해요! 부표마다 화살표가 가리키는 쪽으로 지나가 파워를 얻고, 점프대에서 날아올라 플립과 스핀을 하고, 터보로 쌩 앞서 나가세요. 컵 3개에서 트로피를 따고, 타임 트라이얼에서 내 고스트와 겨루고, 더 빠른 제트스키를 열어요.", controls: "<kbd>↑</kbd>/<kbd>W</kbd> 출발, <kbd>←</kbd> <kbd>→</kbd> 방향, <kbd>↓</kbd> 브레이크, <kbd>Space</kbd>/<kbd>Shift</kbd> 터보. 공중에서: <kbd>←</kbd>/<kbd>→</kbd> 스핀, <kbd>↑</kbd> 앞 플립, <kbd>↓</kbd> 백플립. <kbd>C</kbd> 카메라, <kbd>P</kbd> 일시정지, <kbd>M</kbd> 음소거. 휴대폰에서는 가속이 자동이에요.", label: "모은 별" },
    ja: { title: "ウェーブライダー", desc: "南国のラグーン、荒れた川、夜の港をジェットスキーでかけぬけよう！ブイは矢印の向きの側を通るとパワーアップ、ジャンプ台から飛んでフリップやスピンを決めて、ターボで一気に前へ！3つのカップでトロフィーを勝ち取り、タイムアタックで自分のゴーストと勝負して、もっと速いジェットスキーを解放しよう。", controls: "<kbd>↑</kbd>/<kbd>W</kbd> 進む、<kbd>←</kbd> <kbd>→</kbd> 方向、<kbd>↓</kbd> ブレーキ、<kbd>Space</kbd>/<kbd>Shift</kbd> ターボ。空中で：<kbd>←</kbd>/<kbd>→</kbd> スピン、<kbd>↑</kbd> 前方フリップ、<kbd>↓</kbd> バックフリップ。<kbd>C</kbd> カメラ、<kbd>P</kbd> 一時停止、<kbd>M</kbd> ミュート。スマホではアクセルが自動だよ。", label: "獲得スター" },
    zh: { title: "乘风破浪", desc: "骑着水上摩托飞驰过热带泻湖、湍急河流和夜晚的港口！按箭头指示从浮标的一侧通过就能获得能量，从跳台飞起做空翻和旋转，再用涡轮冲到最前面。在 3 个杯赛中赢得奖杯，在计时赛里挑战自己的幽灵，解锁更快的水上摩托！", controls: "<kbd>↑</kbd>/<kbd>W</kbd> 前进，<kbd>←</kbd> <kbd>→</kbd> 转向，<kbd>↓</kbd> 刹车，<kbd>Space</kbd>/<kbd>Shift</kbd> 涡轮加速。空中时：<kbd>←</kbd>/<kbd>→</kbd> 旋转，<kbd>↑</kbd> 前空翻，<kbd>↓</kbd> 后空翻。<kbd>C</kbd> 镜头，<kbd>P</kbd> 暂停，<kbd>M</kbd> 静音。手机上会自动加速。", label: "获得星星" },
    es: { title: "Jinete de Olas", desc: "¡Corre en moto de agua por lagunas tropicales, ríos salvajes y un puerto de noche! Pasa cada boya por el lado que indica su flecha para cargarte de energía, salta desde las rampas para hacer volteretas y giros, y usa el turbo para salir disparado. Gana trofeos en 3 copas, compite contra tu propio fantasma en Contrarreloj y desbloquea motos de agua más rápidas.", controls: "<kbd>↑</kbd>/<kbd>W</kbd> avanzar, <kbd>←</kbd> <kbd>→</kbd> girar, <kbd>↓</kbd> frenar, <kbd>Space</kbd>/<kbd>Shift</kbd> turbo. En el aire: <kbd>←</kbd>/<kbd>→</kbd> giro, <kbd>↑</kbd> voltereta hacia delante, <kbd>↓</kbd> voltereta hacia atrás. <kbd>C</kbd> cámara, <kbd>P</kbd> pausa, <kbd>M</kbd> silenciar. En el móvil el acelerador es automático.", label: "Estrellas ganadas" },
    fr: { title: "Surfeur des Vagues", desc: "Fais la course en jet-ski dans des lagons tropicaux, des rivières sauvages et un port de nuit ! Passe chaque bouée du côté indiqué par sa flèche pour te recharger, décolle des tremplins pour des flips et des rotations, et utilise ton turbo pour foncer devant. Gagne des trophées dans 3 coupes, affronte ton propre fantôme en Contre-la-montre et débloque des jet-skis plus rapides.", controls: "<kbd>↑</kbd>/<kbd>W</kbd> avancer, <kbd>←</kbd> <kbd>→</kbd> tourner, <kbd>↓</kbd> freiner, <kbd>Space</kbd>/<kbd>Shift</kbd> turbo. En l'air : <kbd>←</kbd>/<kbd>→</kbd> rotation, <kbd>↑</kbd> flip avant, <kbd>↓</kbd> flip arrière. <kbd>C</kbd> caméra, <kbd>P</kbd> pause, <kbd>M</kbd> couper le son. Sur téléphone, l'accélérateur est automatique.", label: "Étoiles gagnées" },
    de: { title: "Wellenreiter", desc: "Rase mit Jetskis durch tropische Lagunen, wilde Flüsse und einen Hafen bei Nacht! Fahr an jeder Boje auf der Seite vorbei, die ihr Pfeil zeigt, um Power zu tanken, flieg über Rampen für Flips und Spins und zieh mit dem Turbo davon. Gewinn Pokale in 3 Cups, fahr im Zeitfahren gegen deinen eigenen Geist und schalte schnellere Jetskis frei.", controls: "<kbd>↑</kbd>/<kbd>W</kbd> Gas, <kbd>←</kbd> <kbd>→</kbd> lenken, <kbd>↓</kbd> bremsen, <kbd>Space</kbd>/<kbd>Shift</kbd> Turbo. In der Luft: <kbd>←</kbd>/<kbd>→</kbd> Spin, <kbd>↑</kbd> Vorwärtssalto, <kbd>↓</kbd> Rückwärtssalto. <kbd>C</kbd> Kamera, <kbd>P</kbd> Pause, <kbd>M</kbd> Ton aus. Auf dem Handy gibt's automatisch Gas.", label: "Gesammelte Sterne" },
    pt: { title: "Rei das Ondas", desc: "Corra de jet ski por lagoas tropicais, rios agitados e um porto à noite! Passe cada boia pelo lado que a seta mostra para ganhar energia, voe das rampas para dar mortais e giros, e use o turbo para disparar na frente. Ganhe troféus em 3 copas, corra contra seu próprio fantasma no Contra o Relógio e libere jet skis mais rápidos.", controls: "<kbd>↑</kbd>/<kbd>W</kbd> acelerar, <kbd>←</kbd> <kbd>→</kbd> virar, <kbd>↓</kbd> frear, <kbd>Space</kbd>/<kbd>Shift</kbd> turbo. No ar: <kbd>←</kbd>/<kbd>→</kbd> giro, <kbd>↑</kbd> mortal para a frente, <kbd>↓</kbd> mortal para trás. <kbd>C</kbd> câmera, <kbd>P</kbd> pausar, <kbd>M</kbd> mudo. No celular, o acelerador é automático.", label: "Estrelas ganhas" },
  },
};
